const e="65 chapters",o=[{id:"chapter-01",number:1,title:"자음 (Consonants) · 모음 (Vowels)",goal:"Read any syllable block by identifying its consonant and vowel components",biteCount:8,bites:[{kind:"words",title:"단어 Words 1 · 한글~",cards:[{kind:"guess",word:{ko:"한글",romanization:"hangeul",en:"Hangul (Korean writing system)",pos:"noun",nuance:"Say 한글 for the writing system, 한국어 for the language. This chapter is about the writing system first."},sentence:{ko:"한글은 배우기 쉬워요.",en:"Hangul is easy to learn."},target:"한글",options:["consonant","vowel","Hangul (Korean writing system)"],note:"Topic particle 은 attaches to 한글 — you will learn this particle in Chapter 2"},{kind:"guess",word:{ko:"자음",romanization:"jaeum",en:"consonant",pos:"noun",nuance:"A consonant can sit at the beginning of a block, and some consonants can also sit at the bottom as 받침."},sentence:{ko:"ㄱ은 자음이에요.",en:"ㄱ is a consonant."},target:"자음",options:["Hangul (Korean writing system)","letter / character","consonant"],note:"이에요 means 'is/am/are' — the simplest Korean copula; perfect for labeling what something is"},{kind:"guess",word:{ko:"모음",romanization:"moeum",en:"vowel",pos:"noun",nuance:"The visual direction of a vowel helps the learner remember the mouth shape."},sentence:{ko:"ㅏ는 모음이에요.",en:"ㅏ is a vowel."},target:"모음",options:["Hangul (Korean writing system)","vowel","letter / character"],note:"는 is the topic marker for vowel-ending words — 모음 ends in ㅁ so it uses 은, but ㅏ alone ends in a vowel, so 는 attaches"},{kind:"guess",word:{ko:"글자",romanization:"geulja",en:"letter / character",pos:"noun",nuance:"글자 can mean an individual written unit. In this chapter it usually points to a Hangul block or letter being studied."},sentence:{ko:"이 글자가 뭐예요?",en:"What is this character?"},target:"글자",options:["Hangul (Korean writing system)","consonant","letter / character"],note:"뭐예요 = 'what is it?' — an essential question frame for asking about unfamiliar characters"},{kind:"guess",word:{ko:"소리",romanization:"sori",en:"sound",pos:"noun",nuance:"소리 points to what you hear, while 글자 points to what you see."},sentence:{ko:"이 글자의 소리가 뭐예요?",en:"What is the sound of this character?"},target:"소리",options:["Hangul (Korean writing system)","sound","consonant"],note:"의 is a possessive particle — '글자의 소리' = 'the sound of the character'"},{kind:"guess",word:{ko:"받침",romanization:"batchim",en:"final consonant (bottom of syllable block)",pos:"noun",nuance:"받침은 동사 '받치다(아래에서 받쳐 주다, to support from underneath)'에서 나온 명사로, 컵이나 그릇 '아래에' 받쳐 두는 작은 판을 두루 가리켜요. 그래서 핵심 의미는 '무엇의 아래에 두어 받쳐 주는 것'이고, 영어처럼 용도별로 saucer/coaster/trivet으로 쪼개지 않고 한 단어로 폭넓게 써요. 가장 가까운 짝은 '컵받침'인데, 받침이 일반적인 '아래 받치는 것' 전체를 뜻한다면 컵받침은 '컵 전용 받침'으로 범위가 좁아요 — 즉 컵받침은 받침의 한 종류예요. 같은 원리로 냄비받침(trivet)도 만들어져요. 영어 화자가 흔히 하는 실수는 받침을 음식을 담아 먹는 접시로 오해하는 것인데, 받침은 먹는 그릇이 아니라 다른 것을 받쳐 두는 '바닥 판'이에요. 또 한국어 받침은 글자에서 자음이 아래에 받치는 부분(예: '강'의 ㅇ)도 가리키니, 식기 맥락인지 한글 맥락인지 문맥으로 구별하세요."},sentence:{ko:"한에는 받침 ㄴ이 있어요.",en:"한 has the final consonant ㄴ."},target:"받침",options:["Hangul (Korean writing system)","letter / character","final consonant (bottom of syllable block)"],note:"한 = ㅎ + ㅏ + ㄴ. The final ㄴ is the 받침."},{kind:"payoff",line:{speaker:"민준",ko:"저는 민준이에요. 한글은 처음이에요.",en:"I'm Minjun. Hangul is new for me."},hl:"한글"}],canDo:"Tell consonants from vowels and name the ten core 자음 shapes",id:"chapter-01-b1",chapterId:"chapter-01",index:0},{kind:"pattern",title:"문법 Grammar · 자음 (Consonants)",cards:[{kind:"teach",name:"자음 (Consonants)",sub:"Ten Core Shapes",rows:[],examples:[{ko:"가 / 고 / 구",en:"ㄱ with different vowels",romanization:"ga / go / gu",note:"ㄱ makes a 'g/k' sound — the shape curves like the back of the throat closing. Same consonant, different vowels produce different syllables"},{ko:"나 / 노 / 누",en:"ㄴ with different vowels",romanization:"na / no / nu",note:"ㄴ = 'n' — the shape shows the tongue tip pressed to the ridge behind the upper teeth; this is exactly the mouth position for 'n'"},{ko:"마 / 모 / 무",en:"ㅁ with different vowels",romanization:"ma / mo / mu",note:"ㅁ = 'm' — literally a box representing a closed mouth; lips close for 'm', which is what the box shape shows"},{ko:"바 / 보 / 부",en:"ㅂ with different vowels",romanization:"ba / bo / bu",note:"ㅂ = 'b/p' — the box (ㅁ) opens at the top as lips part; the two top strokes represent the lips opening"}],more:{func:"",funcLead:"",keyPoint:null,pronunciation:"",pitfall:{wrong:"Reading 이 as 'ee' (as in 'see') — exactly like English",right:"이 is close to English 'ee' but shorter and unrounded — and only approximately. The real fix is to listen to a native speaker and imitate, not to map to English sounds.",explanation:"English speakers instinctively reach for their own vowel sounds when they see romanization. But Korean 이 is not English 'ee', Korean 으 has no English equivalent at all, and Korean ㄹ is not 'r' or 'l'. Romanization is a temporary scaffold — use it to check yourself, but learn the actual sounds by ear. The earlier you stop reading romanization as English, the faster your pronunciation improves."}}},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"이 is close to English 'ee' but shorter and unrounded — and only approximately. The real fix is to listen to a native speaker and imitate, not to map to English sounds.",ok:!0},{text:"Reading 이 as 'ee' (as in 'see') — exactly like English",ok:!1}],explanation:"English speakers instinctively reach for their own vowel sounds when they see romanization. But Korean 이 is not English 'ee', Korean 으 has no English equivalent at all, and Korean ㄹ is not 'r' or 'l'. Romanization is a temporary scaffold — use it to check yourself, but learn the actual sounds by ear. The earlier you stop reading romanization as English, the faster your pronunciation improves."},{kind:"drill",prompt:"어떻게 읽어요? · How do you read it?",sentence:"가",options:[{text:"na",ok:!1},{text:"ga",ok:!0},{text:"ma",ok:!1}],explanation:"가 / 고 / 구 = ga / go / gu"},{kind:"drill",prompt:"어떻게 읽어요? · How do you read it?",sentence:"나",options:[{text:"ga",ok:!1},{text:"na",ok:!0},{text:"ma",ok:!1}],explanation:"나 / 노 / 누 = na / no / nu"}],canDo:"Tell consonants from vowels and name the ten core 자음 shapes",id:"chapter-01-b2",chapterId:"chapter-01",index:1},{kind:"words",title:"단어 Words 2 · 발음~",cards:[{kind:"guess",word:{ko:"발음",romanization:"bareum",en:"pronunciation",pos:"noun",nuance:"발음(發音) is Sino-Korean — 發 'to emit/produce' + 音 'sound' — literally 'to produce sound,' i.e. pronunciation, how a word is sounded out. Distinguish it from 억양(抑揚) 'intonation' (the rise and fall of pitch across a sentence) and 발성 'voice production/projection' — 발음 is specifically the articulation of individual sounds and syllables. As a noun it becomes a verb with 하다: 발음하다 'to pronounce.' Collocations: 발음이 좋다/나쁘다/어렵다/정확하다, 발음을 연습하다, 발음 연습 'pronunciation drill,' 받침 발음 'final-consonant pronunciation.' The headline English-speaker pitfall is PARTICLES: 발음 is the SUBJECT of descriptive adjectives, so it's 발음이 좋다/어렵다 (이/가), but the OBJECT of action verbs, so 발음을 연습하다/하다 (을/를). Saying 발음을 좋다 is ungrammatical because 좋다 'to be good' is a stative adjective that can't take a direct object. Also, English 'pronounce' as a verb tempts bare 발음 — you must say 발음하다."},sentence:{ko:"발음이 어려워요.",en:"The pronunciation is difficult."},target:"발음",options:["pronunciation","letter / character","sound"],note:"A natural comment to make as a beginner — acknowledges that pronunciation takes practice"},{kind:"guess",word:{ko:"읽다",romanization:"ikda",en:"to read",pos:"verb",nuance:"읽다 has pronunciation changes, but beginners can first memorize 읽어요 as the practical polite form."},sentence:{ko:"한글을 천천히 읽어요.",en:"I read Hangul slowly."},target:"읽어",options:["to read","to listen","to repeat / follow along"],note:"Focus on reading the Hangul shape before checking romanization."},{kind:"guess",word:{ko:"쓰다",romanization:"sseuda",en:"to write / use",pos:"verb",nuance:"쓰다 can mean write or use. The object tells the meaning: 이름을 쓰다, 카드를 쓰다."},sentence:{ko:"이름을 써요.",en:"I write my name."},target:"써",options:["to listen","to write / use","to repeat / follow along"],note:"쓰다 is ㅡ-irregular: the ㅡ drops before 아/어, giving 써요 not 쓰어요"},{kind:"guess",word:{ko:"듣다",romanization:"deutda",en:"to listen",pos:"verb",nuance:"듣다 is ㄷ irregular: 듣다 becomes 들어요 in polite speech."},sentence:{ko:"소리를 듣고 따라 해요.",en:"I listen to the sound and repeat it."},target:"듣고",options:["to read","to write / use","to listen"],note:"Useful first-lesson action; the irregular form 들어요 is learned later."},{kind:"guess",word:{ko:"말하다",romanization:"malhada",en:"to speak / say",pos:"verb",nuance:"Use 로 for language: 한국어로 말해요, 영어로 말해요. 말하다 can mean both “speak” and “say,” so the object or quote decides the English translation."},sentence:{ko:"천천히 말해요.",en:"I speak slowly."},target:"말해",options:["to listen","to repeat / follow along","to speak / say"],note:"말하다 → 말해요 in polite form; 천천히 = slowly — essential classroom vocabulary"},{kind:"guess",word:{ko:"따라 하다",romanization:"ttara hada",en:"to repeat / follow along",pos:"verb",nuance:"하다 combines with many nouns: 공부하다, 일하다, 운동하다. It is one of the most important Korean verbs."},sentence:{ko:"저를 따라 하세요.",en:"Please repeat after me."},target:"따라 하",options:["to read","to write / use","to repeat / follow along"],note:"따라 하세요 is a polite command — very common in language class settings"}],canDo:"See a vowel's lines and dots and read its direction (모음)",id:"chapter-01-b3",chapterId:"chapter-01",index:2},{kind:"pattern",title:"문법 Grammar · 모음 (Vowels)",cards:[{kind:"teach",name:"모음 (Vowels)",sub:"Lines, Dots, and Direction",rows:[],examples:[{ko:"아 / 어",en:"ㅏ vs ㅓ — both tall vowels beside the consonant",romanization:"a / eo",note:"ㅏ: tick points RIGHT — mouth open, sound comes forward. ㅓ: tick points LEFT — sound pulls back in the throat. The tick is the only difference on the page and in your mouth."},{ko:"오 / 우",en:"ㅗ vs ㅜ — both wide vowels below the consonant",romanization:"o / u",note:"ㅗ: tick points UP from the horizontal line — lips round and rise. ㅜ: tick points DOWN — lips round and drop. The compass direction = the lip movement direction."},{ko:"으 / 이",en:"ㅡ vs ㅣ — no tick needed",romanization:"eu / i",note:"ㅡ: just the horizontal bar — the mouth is flat and neutral, no rounding. ㅣ: just the vertical bar — teeth close, sound is 'ee'. These are the simplest vowel shapes."},{ko:"애 / 에",en:"Combined vowels — ㅏ+ㅣ and ㅓ+ㅣ",romanization:"ae / e",note:"ㅐ (ㅏ+ㅣ) and ㅔ (ㅓ+ㅣ) look similar and in modern Korean are often pronounced identically as a mid-front 'e' sound. Beginners can treat them the same."}],more:{func:"",funcLead:"",keyPoint:null,pronunciation:"",pitfall:{wrong:"Pronouncing 으 (ㅡ) as 'oo' or 'u' based on romanization 'eu'",right:"으 has no English equivalent — it is a central unrounded vowel. Keep your lips flat (no rounding) and the tongue in the middle of the mouth.",explanation:"The romanization 'eu' looks like the French 'eu' or English 'uh', so beginners round their lips. But 으 is made with flat, unrounded lips — the opposite of 'oo'. To train this sound: say 'ee' (이) and keep your lips in exactly that flat position, then move your tongue back. The sound you get is 으. Practice 이 then 으 back and forth."}}},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"Pronouncing 으 (ㅡ) as 'oo' or 'u' based on romanization 'eu'",ok:!1},{text:"으 has no English equivalent — it is a central unrounded vowel. Keep your lips flat (no rounding) and the tongue in the middle of the mouth.",ok:!0}],explanation:"The romanization 'eu' looks like the French 'eu' or English 'uh', so beginners round their lips. But 으 is made with flat, unrounded lips — the opposite of 'oo'. To train this sound: say 'ee' (이) and keep your lips in exactly that flat position, then move your tongue back. The sound you get is 으. Practice 이 then 으 back and forth."},{kind:"drill",prompt:"어떻게 읽어요? · How do you read it?",sentence:"아",options:[{text:"o",ok:!1},{text:"a",ok:!0},{text:"eu",ok:!1}],explanation:"아 / 어 = a / eo"},{kind:"drill",prompt:"어떻게 읽어요? · How do you read it?",sentence:"오",options:[{text:"o",ok:!0},{text:"a",ok:!1},{text:"eu",ok:!1}],explanation:"오 / 우 = o / u"}],canDo:"See a vowel's lines and dots and read its direction (모음)",id:"chapter-01-b4",chapterId:"chapter-01",index:3},{kind:"words",title:"단어 Words 3 · 천천히~",cards:[{kind:"guess",word:{ko:"천천히",romanization:"cheoncheonhi",en:"slowly",pos:"adverb",nuance:"천천히 is polite and clear for asking someone to slow down."},sentence:{ko:"천천히 말해 주세요.",en:"Please speak slowly."},target:"천천히",options:["slowly","Hangul (Korean writing system)","consonant"],note:"One of the most useful phrases for a beginner — you will say this constantly in your first weeks of Korean"},{kind:"guess",word:{ko:"다시",romanization:"dasi",en:"again",pos:"adverb",nuance:"다시 is one of the most useful repair words for learners."},sentence:{ko:"다시 들어요.",en:"I listen again."},target:"다시",options:["Hangul (Korean writing system)","again","consonant"],note:"다시 comes before the verb it modifies — Korean adverbs do not change form"},{kind:"guess",word:{ko:"알겠어요",romanization:"algesseoyo",en:"I understand / I see / okay",pos:"expression",nuance:"알겠어요 often means “okay, I got it,” not only intellectual understanding."},sentence:{ko:"네, 알겠어요.",en:"Yes, I understand."},target:"알겠어요",options:["Hangul (Korean writing system)","I understand / I see / okay","consonant"],note:"알겠어요 literally means 'I will know it' (future-inference form of 알다) but functions as 'I get it now' — use it as a fixed phrase"},{kind:"guess",word:{ko:"모르겠어요",romanization:"moreugesseoyo",en:"I don't know / I'm not sure",pos:"expression",nuance:"모르다 is the antonym of 알다 'to know', and the -겠- before the polite -어요 ending softens the assertion into 'I can't seem to tell / I'm not certain' rather than a blunt fact. This makes 모르겠어요 notably more humble and polite than 몰라요 — which, without -겠-, can sound curt or even dismissive, like 'I don't know and that's that'. Use 모르겠어요 with customers, teachers, seniors, or anyone you're being careful with; 몰라요 is fine between close friends. Adding 잘 (잘 모르겠어요) counterintuitively intensifies the not-knowing — it does NOT mean 'I know well'; in negative verbs, 잘 boosts the negative, meaning 'I really have no idea'. The -ㄴ지/-ㄹ지 construction embeds questions inside 모르겠어요: 어디인지 모르겠어요, 맞는지 모르겠어요, 언제 오실지 모르겠어요 — this pattern is essential for natural speech. Compare 안 알아요: Korean does not negate 알다 with 안; the dedicated negative is 모르다, making 안 알아요 wrong for 'I don't know'."},sentence:{ko:"이 글자 모르겠어요.",en:"I don't know this character."},target:"모르겠어요",options:["Hangul (Korean writing system)","consonant","I don't know / I'm not sure"],note:"The counterpart to 알겠어요 — equally important to have in your first lesson vocabulary"},{kind:"guess",word:{ko:"연습하다",romanization:"yeonseupada",en:"to practice",pos:"verb",nuance:"연습하다 is Sino-Korean 練習 — 練 'train/temper (as in tempering metal)' + 習 'repeatedly do/learn' — so 'train by repetition', i.e. drill a skill until it improves. The key contrast is with 공부하다 'to study': 공부하다 is taking in knowledge (grammar, facts, theory), whereas 연습하다 is repeated hands-on doing to build a SKILL — you 공부해 grammar but 연습해 speaking and piano. A closely related word is 훈련하다 (訓練, 'train'), which is more systematic/physical (soldiers, athletes), while 연습하다 is everyday practice. The thing practiced is a direct OBJECT with 을/를: 발음을 연습하다. The English-speaker pitfall is twofold: don't say 발음에 연습하다 (no 에), and don't reach for 공부하다 when you mean drilling a skill. As a noun+하다 verb it conjugates on 하다 (연습해요, 연습했어요, formal 연습합니다); negative/impossible split the noun (연습 안 해요, 연습 못 해요)."},sentence:{ko:"매일 한글을 연습해요.",en:"I practice Hangul every day."},target:"연습해",options:["to practice","to listen","to speak / say"],note:"매일 = every day; 연습하다 follows the 하다 verb pattern — 연습 (practice noun) + 하다 (to do)"},{kind:"payoff",line:{speaker:"민준",ko:"한... 조금 천천히 말해 주세요.",en:"Han... please say it a little slowly."},hl:"천천히"}],canDo:"Build a syllable block from 자음 + 모음 (+ 받침)",id:"chapter-01-b5",chapterId:"chapter-01",index:4},{kind:"dialogue",title:"대화 Dialogue · 진짜 한국어",cards:[{kind:"chat",setting:"Jiyeon (a Korean tutor) meets Minjun (a complete beginner) for their first online lesson",lines:[{speaker:"지연",ko:"안녕하세요! 지연이에요. 이름이 뭐예요?",en:"Hello! I'm Jiyeon. What's your name?",romanization:"Annyeonghaseyo! Jiyeonieyo. Ireumi mwoyeyo?"},{speaker:"민준",ko:"저는 민준이에요. 한글은 처음이에요.",en:"I'm Minjun. Hangul is new for me.",romanization:"Jeoneun minjunieyo. Hangeureun cheoeumieyo."},{speaker:"지연",ko:"좋아요. 오늘은 글자 하나만 먼저 볼게요. 이건 '한'이에요.",en:"Good. Today let's look at just one character first. This is 한.",romanization:"Joayo. Oneureun geulja hanaman meonjeo bolgeyo. Igeon 'han'ieyo."},{speaker:"민준",ko:"한... 조금 천천히 말해 주세요.",en:"Han... please say it a little slowly.",romanization:"Han... jogeum cheoncheonhi malhae juseyo."},{speaker:"지연",ko:"한. ㅎ, ㅏ, ㄴ이 같이 있어요.",en:"Han. ㅎ, ㅏ, and ㄴ are together.",romanization:"Han. Hieut, a, nieuni gachi isseoyo."},{speaker:"민준",ko:"그러면 ㅎ은 자음이고, ㅏ는 모음이에요?",en:"Then ㅎ is a consonant, and ㅏ is a vowel?",romanization:"Geureomyeon hieuteun jaeumigo, aneun moeumieyo?"},{speaker:"지연",ko:"맞아요. 마지막 ㄴ도 자음이에요. 세 개가 모여서 한 글자가 돼요.",en:"Right. The final ㄴ is also a consonant. Three pieces come together and become one character.",romanization:"Majayo. Majimak nieundo jaeumieyo. Se gaega moyeoseo han geuljaga dwaeyo."},{speaker:"민준",ko:"아, 한이에요. 로마자보다 한글을 먼저 볼게요.",en:"Ah, it's 한. I'll look at the Hangul first, before the romanization.",romanization:"A, hanieyo. Romajaboda hangeureul meonjeo bolgeyo."}]},{kind:"order",prompt:"Build: 'Please speak slowly.'",tokens:["천천히","말해","주세요"],correct:"천천히 말해 주세요",explanation:"천천히 tells how to speak, and 말해 주세요 makes the polite request. This is the classroom phrase learners need when the Korean is too fast."},{kind:"drill",prompt:"누가 한 말일까요? · Who said this?",sentence:"맞아요. 마지막 ㄴ도 자음이에요. 세 개가 모여서 한 글자가 돼요.",options:[{text:"민준",ok:!1},{text:"지연",ok:!0}],explanation:"Right. The final ㄴ is also a consonant. Three pieces come together and become one character."},{kind:"drill",prompt:`무엇이 들어갈까요? · "I'm Minjun. Hangul is new for me."`,sentence:"저는 민준이에요. ___은 처음이에요.",options:[{text:"자음",ok:!1},{text:"모음",ok:!1},{text:"한글",ok:!0}],explanation:""}],canDo:"Tell consonants from vowels and name the ten core 자음 shapes",id:"chapter-01-b6",chapterId:"chapter-01",index:5},{kind:"reading",title:"읽기 Reading · 민준의 첫 한글 공부 (Minjun's First Hangul Study)",cards:[{kind:"read",title:"민준의 첫 한글 공부 (Minjun's First Hangul Study)",chunks:["오늘 처음으로 한글을 공부했어요. 한글 글자는 자음과 모음으로 만들어요. 오늘 자음 열 개를 배웠어요: ㄱ, ㄴ, ㄷ, ㄹ, ㅁ, ㅂ, ㅅ, ㅇ, ㅈ, ㅎ. 모음도 여섯 개 배웠어요: ㅏ, ㅓ, ㅗ, ㅜ, ㅡ, ㅣ.","이 자음과 모음을 합치면 글자가 돼요. 예를 들어, ㅎ + ㅏ + ㄴ = 한이에요. 처음에는 어려웠지만 이제 조금 읽을 수 있어요. 내일 더 연습할 거예요."],translation:"Today I studied Hangul for the first time. Hangul characters are made with consonants and vowels. Today I learned ten consonants: ㄱ, ㄴ, ㄷ, ㄹ, ㅁ, ㅂ, ㅅ, ㅇ, ㅈ, ㅎ. I also learned six vowels: ㅏ, ㅓ, ㅗ, ㅜ, ㅡ, ㅣ. When you combine these consonants and vowels, you get a character. For example, ㅎ + ㅏ + ㄴ = 한. At first it was difficult, but now I can read a little. I will practice more tomorrow.",qas:[{q:"How many consonants did Minjun learn today?",a:"열 개 (ten) — ㄱ, ㄴ, ㄷ, ㄹ, ㅁ, ㅂ, ㅅ, ㅇ, ㅈ, ㅎ"},{q:"What example does the diary give for how a syllable block is made?",a:"ㅎ + ㅏ + ㄴ = 한 — a consonant (ㅎ) + a vowel (ㅏ) + a final consonant (ㄴ) combine into one spoken syllable block"},{q:"Find all the 이에요/예요 copula forms in the text. Why does each one appear, and when does the ending change from 이에요 to 예요?",a:"Two: 한이에요 (한 ends in the final consonant ㄴ, so it takes 이에요) and 거예요 in 연습할 거예요 (거 ends in a vowel, so it takes 예요). 글자가 돼요 is not the copula; it is 되다, meaning becomes. The reusable rule is: consonant-final words take 이에요, vowel-final words take 예요."}]},{kind:"drill",prompt:"지문에서 뭐라고 했어요? · What did the passage say?",sentence:"오늘 처음으로 ___을 공부했어요.",options:[{text:"소리",ok:!1},{text:"받침",ok:!1},{text:"한글",ok:!0}],explanation:""},{kind:"drill",prompt:"지문에서 뭐라고 했어요? · What did the passage say?",sentence:"오늘 ___ 열 개를 배웠어요: ㄱ, ㄴ, ㄷ, ㄹ, ㅁ, ㅂ, ㅅ, ㅇ, ㅈ, ㅎ.",options:[{text:"소리",ok:!1},{text:"읽다",ok:!1},{text:"자음",ok:!0}],explanation:""}],canDo:"See a vowel's lines and dots and read its direction (모음)",id:"chapter-01-b7",chapterId:"chapter-01",index:6},{kind:"boss",title:"보스 Boss bite · 다 걸어요",cards:[{kind:"drill",prompt:"Which vowel has a vertical stroke with a short tick pointing right?",sentence:null,options:[{text:"ㅓ",ok:!1},{text:"ㅏ",ok:!0},{text:"ㅗ",ok:!1},{text:"ㅣ",ok:!1}],explanation:"ㅏ has a vertical stroke with a short tick pointing RIGHT. ㅓ looks similar but the tick points LEFT (that is the 'uh/eo' sound). ㅗ is a horizontal stroke with a tick pointing UP (the 'o' sound). ㅣ is just a vertical bar with no tick (the 'ee' sound). The direction of the tick is the key distinguishing feature."},{kind:"drill",prompt:"The syllable block 한 is made of which components?",sentence:null,options:[{text:"ㅎ + ㅏ + ㄴ",ok:!0},{text:"ㅎ + ㄴ + ㅏ",ok:!1},{text:"ㄴ + ㅏ + ㅎ",ok:!1},{text:"ㅎ + ㅓ + ㄴ",ok:!1}],explanation:"Korean syllable blocks follow the order: (1) initial consonant at top-left, (2) vowel to the right or below, (3) optional final consonant at the bottom. So 한 = ㅎ (initial) + ㅏ (vowel, to the right because it is a tall vowel) + ㄴ (final, at the bottom). The other options have the order wrong or use the wrong vowel — ㅓ would give 헌, not 한."},{kind:"drill",prompt:"Which of these is the SILENT consonant placeholder used when a syllable starts with a vowel sound?",sentence:null,options:[{text:"ㅎ",ok:!1},{text:"ㅇ",ok:!0},{text:"ㅅ",ok:!1},{text:"ㄴ",ok:!1}],explanation:"ㅇ in the onset (initial) position makes no sound — it is a placeholder that allows vowel-initial syllables to have a proper block shape. So 아 is written as ㅇ+ㅏ, not just ㅏ floating alone. ㅎ makes an 'h' sound, ㅅ makes an 's' sound, ㄴ makes an 'n' sound. Only ㅇ is silent at the start of a syllable (though it makes 'ng' at the end)."},{kind:"drill",prompt:"How do you say 'Please speak slowly' in Korean?",sentence:null,options:[{text:"천천히 말해 주세요.",ok:!0},{text:"다시 들어요.",ok:!1},{text:"알겠어요.",ok:!1},{text:"모르겠어요.",ok:!1}],explanation:"천천히 = slowly, 말해 주세요 = please speak (V + 아/어 주세요 pattern). 다시 들어요 means 'listen again', 알겠어요 means 'I understand', 모르겠어요 means 'I don't know'. The V + 아/어 주세요 pattern (pattern-015) is used for polite requests for someone to perform an action for you."},{kind:"drill",prompt:"A learner sees ㅎ + ㅏ + ㄴ. Which block should they read?",sentence:null,options:[{text:"한",ok:!0},{text:"하",ok:!1},{text:"나",ok:!1},{text:"헌",ok:!1}],explanation:"ㅎ is the first consonant, ㅏ is the vowel, and ㄴ sits at the bottom as 받침. Together they form 한. This checks the Chapter 1 skill: read the block from its parts before relying on romanization."},{kind:"drill",prompt:"Where does a TALL vowel like ㅏ, ㅓ, or ㅣ appear in a syllable block?",sentence:null,options:[{text:"Below the consonant",ok:!1},{text:"To the right of the consonant",ok:!0},{text:"Above the consonant",ok:!1},{text:"It can go anywhere",ok:!1}],explanation:"Tall vowels (ㅏ, ㅓ, ㅣ, ㅐ, ㅔ and their compounds) sit to the RIGHT of the consonant: 가 (ㄱ+ㅏ), 서 (ㅅ+ㅓ), 시 (ㅅ+ㅣ). Wide vowels (ㅗ, ㅜ, ㅡ) sit BELOW the consonant: 고 (ㄱ+ㅗ), 수 (ㅅ+ㅜ). This layout rule is completely regular — once you know it, you can read any block."},{kind:"drill",prompt:"What does 알겠어요 most naturally mean in a classroom context?",sentence:null,options:[{text:"I don't understand.",ok:!1},{text:"Please say it again.",ok:!1},{text:"I understand / I see / Okay.",ok:!0},{text:"Is that right?",ok:!1}],explanation:"알겠어요 literally contains 알다 (to know) + 겠 (future/inference marker) + 어요, but it functions as 'I got it / I understand / Okay' in conversation. It is NOT 모르겠어요 (I don't know / I'm not sure), NOT 다시 말해 주세요 (please say it again), NOT 맞아요? (is that right?). Use 알겠어요 to signal to your teacher that you have understood what they just explained."},{kind:"drill",prompt:"Which block starts with a vowel sound and uses ㅇ as the silent placeholder?",sentence:null,options:[{text:"아",ok:!0},{text:"나",ok:!1},{text:"한",ok:!1}],explanation:"아 begins with a vowel sound, so ㅇ fills the first consonant slot silently. 나 and 한 begin with real consonant sounds."}],canDo:"Build a syllable block from 자음 + 모음 (+ 받침)",id:"chapter-01-b8",chapterId:"chapter-01",index:7}]},{id:"chapter-02",number:2,title:"N은/는 · N이에요/예요",goal:"Greet, thank, and apologize using the five most essential Korean phrases",biteCount:8,bites:[{kind:"words",title:"단어 Words 1 · 안녕하세요~",cards:[{kind:"guess",word:{ko:"안녕하세요",romanization:"annyeonghaseyo",en:"Hello / Hi (polite)",pos:"expression",nuance:"안녕하세요 is the all-purpose 존댓말 greeting for strangers, coworkers, shopkeepers, teachers — basically any adult you are not on 반말 terms with. The root 안녕(安寧) means 'peace/well-being', so the phrase literally asks 'are you at peace?', but modern Koreans hear it simply as 'hello'; it works morning, noon, and night since Korean has no separate 'good morning/afternoon/evening' equivalents. The register ladder runs: 안녕 (반말, close friends / children / clear juniors) → 안녕하세요 (standard polite) → 안녕하십니까 (격식체, formal broadcasts and service settings). A key social rule: saying 안녕 to a teacher, boss, or older stranger signals either extreme intimacy or disrespect — always default to 안녕하세요 until 반말 is mutually established. The classic English-speaker trap is splitting greetings by time of day or tacking on 어떻게 지내세요? every time — in Korean, 안녕하세요 alone is the complete, natural hello, and opening with a wellbeing question to a stranger sounds oddly probing."},sentence:{ko:"안녕하세요. 저는 지수예요.",en:"Hello. I am Jisu."},target:"안녕하세요",options:["Hello / Hi (polite)","Goodbye (said by the one leaving)","Thank you (formal)"],note:"안녕하세요 is always the opener; then your name introduction follows naturally."},{kind:"guess",word:{ko:"안녕히 계세요",romanization:"annyeonghi gyeseyo",en:"Goodbye (said by the one leaving)",pos:"expression",nuance:"안녕히 계세요 is the mirror image of 안녕히 가세요: you say it when YOU are the one leaving and the other person STAYS. The pivot is the verb — 계시다 is the honorific of 있다 'to be/remain (of a person)', so 계세요 wishes the one staying to 'remain in peace'. Both phrases share the same 안녕(安寧) 'peace' root; the verb alone signals direction. English speakers reliably swap the two because 'goodbye' has no who-moves information — the one-second fix is: if my feet are moving, use 계세요; if their feet are moving, use 가세요. A smooth social move before departing is to add 먼저 갈게요 or 먼저 가 볼게요 ('I'll head off first') so leaving ahead of others doesn't seem abrupt or rude. When leaving a workplace where colleagues are still working, pairing 안녕히 계세요 with 수고하세요 ('keep up the good work') is the natural and considerate exit. Formal register: 안녕히 계십시오."},sentence:{ko:"제가 먼저 갈게요. 안녕히 계세요!",en:"I'll go first. Goodbye!"},target:"안녕히 계세요",options:["Hello / Hi (polite)","Goodbye (said by the one leaving)","Thank you (formal)"],note:"Say 안녕히 계세요 when you are leaving and the other person is staying. Say 안녕히 가세요 to someone who is leaving."},{kind:"guess",word:{ko:"감사합니다",romanization:"gamsahamnida",en:"Thank you (formal)",pos:"expression",nuance:"감사합니다 is the default 존댓말 'thank you' safe with literally anyone — a stranger, a clerk, a teacher, your boss — and never wrong. It comes from Sino-Korean 감사(感謝), giving it a slightly formal, composed feel compared to the warmer native alternative 고맙습니다. The formality ladder runs: 고마워 (반말, friends/juniors) → 고마워요 (gentle polite) → 감사합니다 (standard polite) → 대단히 감사합니다 / 감사드립니다 (격식, speeches, written). The nearest alternative is 고맙습니다, which is pure native Korean and sounds a touch warmer and more personal; both are equally polite, and the choice is mostly about tone rather than rank. The classic English-speaker error is stacking a noun directly: you cannot say '도움 감사합니다' as if words simply pile up — to thank for an action you must attach ~아/어 주셔서 (도와주셔서 감사합니다). Another mistake is using 고마워 with strangers or anyone older, which sounds presumptuous and rude."},sentence:{ko:"도와주셔서 감사합니다.",en:"Thank you for helping me."},target:"감사합니다",options:["Hello / Hi (polite)","Goodbye (said by the one leaving)","Thank you (formal)"],note:"감사합니다 is the safer, more formal option — use it with strangers, in shops, and in any formal setting."},{kind:"guess",word:{ko:"고마워요",romanization:"gomawoyo",en:"Thank you (warm/friendly)",pos:"expression",nuance:"Polite enough for many situations, but 감사합니다 is safer in formal service or business contexts."},sentence:{ko:"선물이에요? 정말 고마워요!",en:"It's a gift? Thank you so much!"},target:"고마워요",options:["Hello / Hi (polite)","Goodbye (said by the one leaving)","Thank you (warm/friendly)"],note:"고마워요 is warmer and more personal than 감사합니다 — great for friends and classmates."},{kind:"guess",word:{ko:"죄송합니다",romanization:"joesonghamnida",en:"I'm sorry / I apologize (formal)",pos:"expression",nuance:"죄송합니다 is the higher-deference 'I'm sorry', from Sino-Korean 죄송(罪悚), literally 'I feel I have committed a fault and am fearful before you'. That deferential weight makes it the correct apology toward strangers, seniors, customers, and your boss — situations where showing you lower yourself is required. The formality ladder: 미안해 (반말, peers/friends) → 미안해요 (gentle polite) → 죄송해요 / 죄송합니다 (polite, upward-safe) → 대단히 죄송합니다 / 죄송스럽습니다 (격식, serious fault). The dividing line versus 미안하다 is deference: 죄송하다 lowers yourself and is always safe upward; 미안하다 is more horizontal and personal, and sounds too casual to a boss. Three concrete English-speaker mistakes: (1) attaching the reason wrong — use X-아/어서 죄송합니다 (늦어서 죄송합니다), not '늦은 것 죄송'; (2) using 미안해 to a boss or stranger; (3) confusing it with 실례합니다, which is 'excuse me' for a small intrusion, not an apology for fault."},sentence:{ko:"늦어서 죄송합니다.",en:"I'm sorry for being late."},target:"죄송합니다",options:["Hello / Hi (polite)","I'm sorry / I apologize (formal)","Goodbye (said by the one leaving)"],note:"죄송합니다 is the formal apology — use it when you've genuinely caused trouble or in professional/service situations."},{kind:"guess",word:{ko:"미안해요",romanization:"mianhaeyo",en:"I'm sorry (friendly)",pos:"expression",nuance:"미안해요/미안하다 is the warmer, more horizontal 'sorry' — used downward or sideways: to friends, peers, your kids, or people close in age and rank. From Sino-Korean 미안(未安), literally 'not at ease (in my heart)', it expresses personal guilt rather than formal deference. The register ladder: 미안해 (반말) → 미안해요 (gently polite) → 미안합니다 (firmer polite) → 죄송합니다 (deferential, upward/격식). The key dividing line versus 죄송하다 is deference: 미안하다 does NOT lower you toward the listener, so it can feel too casual or even presumptuous with a boss or customer — for those situations always choose 죄송합니다. English speakers wrongly treat 미안해요 and 죄송합니다 as interchangeable 'sorry'; using 미안해요 to your boss sounds insufficiently deferential, while using 죄송합니다 to a close friend sounds coldly distant. Also: the small 'sorry, excuse me' to squeeze past a stranger on the street is NOT 미안해요 but 실례합니다 / 잠시만요."},sentence:{ko:"미안해요, 늦었어요.",en:"Sorry, I'm late."},target:"미안해요",options:["I'm sorry (friendly)","Hello / Hi (polite)","Goodbye (said by the one leaving)"],note:"미안해요 is the everyday polite apology — less heavy than 죄송합니다, appropriate for friends and classmates."},{kind:"payoff",line:{speaker:"민준",ko:"안녕하세요! 오늘 처음이에요?",en:"Hello! Is this your first time here?"},hl:"안녕하세요"}],canDo:"Greet, thank, and apologize politely (안녕하세요 · 감사합니다 · 죄송합니다)",id:"chapter-02-b1",chapterId:"chapter-02",index:0},{kind:"pattern",title:"문법 Grammar · N은/는",cards:[{kind:"hunt",name:"N은/는",sub:"topic marker",lines:[{tokens:[{pre:"저",mid:"는",post:"",hit:!0},{pre:"마이클이에요.",mid:"",post:"",hit:!1}],ko:"저는 마이클이에요.",en:"I'm Michael.",romanization:"jeoneun maikeurieyo."},{tokens:[{pre:"이름",mid:"은",post:"",hit:!0},{pre:"뭐예요?",mid:"",post:"",hit:!1}],ko:"이름은 뭐예요?",en:"What's your name?",romanization:"ireumeun mwoyeyo?"}],rule:{name:"N은/는",rows:[{when:"Noun ends in a consonant (받침)",add:"은",ex:"이름 → 이름은 · 선생님 → 선생님은"},{when:"Noun ends in a vowel",add:"는",ex:"저 → 저는 · 어머니 → 어머니는"}]},more:{func:'은/는 marks the topic of a sentence — the thing you single out to talk about ("as for ___"). It is the backbone of introductions and of saying what something is.',funcLead:'은/는 marks the topic of a sentence — the thing you single out to talk about ("as for ___").',keyPoint:{label:"은/는 also hints at a contrast",body:"Besides naming the topic, 은/는 often quietly sets one thing against others. 저는 학생이에요 = 'as for me, I'm a student' (someone else might not be). 오늘은 바빠요 = 'today I'm busy' (other days, maybe not). You don't have to force this nuance — just notice that spotlighting something with 은/는 can imply a comparison."},pronunciation:"이름은 is pronounced [이르믄]: the final ㅁ links into the next vowel (linking, 연음).",pitfall:{wrong:"나는 이름 마이클이에요.",right:"저는 마이클이에요.",explanation:`Don't translate "my name" word for word. 저는 ___이에요 already means "as for me, I'm ___," so there is no separate word for "name" here. Also use 저 (polite I), not 나 (casual), with people you have just met.`}}},{kind:"drill",prompt:"Today I'm busy.",sentence:"오늘___ 바빠요.",options:[{text:"는",ok:!1},{text:"은",ok:!0}],explanation:"Spotlighting 오늘 hints at a contrast — other days may be different."},{kind:"drill",prompt:"My friend is Korean.",sentence:"친구___ 한국 사람이에요.",options:[{text:"은",ok:!1},{text:"는",ok:!0},{text:"예요",ok:!1}],explanation:"친구 ends in a vowel → 는. Everyday topic, everyday words."},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"저는 마이클이에요.",ok:!0},{text:"나는 이름 마이클이에요.",ok:!1}],explanation:`Don't translate "my name" word for word. 저는 ___이에요 already means "as for me, I'm ___," so there is no separate word for "name" here. Also use 저 (polite I), not 나 (casual), with people you have just met.`},{kind:"drill",prompt:"빈칸을 채우세요 · Complete the form — Noun ends in a consonant (받침)",sentence:"이름___",options:[{text:"은",ok:!0},{text:"는",ok:!1}],explanation:"이름 → 이름은 · 선생님 → 선생님은"}],canDo:"Greet, thank, and apologize politely (안녕하세요 · 감사합니다 · 죄송합니다)",id:"chapter-02-b2",chapterId:"chapter-02",index:1},{kind:"words",title:"단어 Words 2 · 네~",cards:[{kind:"guess",word:{ko:"네",romanization:"ne",en:"Yes / I see / okay",pos:"expression",nuance:"네 can also mean “I hear you” or “okay” while listening, not only yes."},sentence:{ko:"네, 알겠어요.",en:"Yes, I understand."},target:"네",options:["Hello / Hi (polite)","Yes / I see / okay","Goodbye (said by the one leaving)"],note:"네 doesn't only mean 'yes' — it's also used as a listening signal ('I hear you') while someone is talking."},{kind:"guess",word:{ko:"아니요",romanization:"aniyo",en:"No (polite)",pos:"expression",nuance:"Use 아니요 as a polite no. 아니 is casual, and 아니요 often sounds softer when followed by a short explanation like 괜찮아요 or 몰라요."},sentence:{ko:"아니요, 저는 학생이 아니에요.",en:"No, I'm not a student."},target:"아니요",options:["Goodbye (said by the one leaving)","Thank you (formal)","No (polite)"],note:"아니요 is the polite 'no' — always softer when followed by a short explanation like 괜찮아요 or 몰라요."},{kind:"guess",word:{ko:"만나서 반가워요",romanization:"mannaseo bangawoyo",en:"Nice to meet you",pos:"expression",nuance:"만나서 반가워요 = 만나서 ('upon meeting / because we've met', from 만나다+ the causal connector -아서) + 반가워요 (반갑다 'to be glad/delighted'). So it literally says 'I am glad because I have met you' — the emotion 반가움 is the point, not just a social formula. Note the grammar: 반갑다 is a ㅂ-irregular adjective, so before -아/어요 the ㅂ drops and becomes 우, giving 반가워요 (not 반갑어요) — the same shift as 춥다→추워요, 돕다→도와요. Register-wise, 반가워요 is warmly friendly; 반갑습니다 is buttoned-up formal for business and ceremonies; the humble 만나 뵙게 되어 반갑습니다 is reserved for high-respect encounters. A crucial situation note: 만나서 반가워요 is essentially a FIRST-MEETING expression. English speakers often reuse 'nice to see you' at subsequent meetings, but at second or third encounters Koreans naturally switch to 오랜만이에요 ('long time no see') or 잘 지냈어요? ('have you been well?'). Reusing the first-meeting phrase can imply you forgot meeting them. The standard reply to 반가워요 is 저도 반가워요."},sentence:{ko:"저는 민준이에요. 만나서 반가워요!",en:"I'm Minjun. Nice to meet you!"},target:"만나서 반가워요",options:["Nice to meet you","Hello / Hi (polite)","Goodbye (said by the one leaving)"],note:"This is the standard 'nice to meet you' — said after exchanging names for the first time."},{kind:"guess",word:{ko:"잠시만요",romanization:"jamsimanyo",en:"One moment, please",pos:"expression",nuance:"More polite than 잠깐만요. Very useful in stores, offices, and classrooms."},sentence:{ko:"잠시만요, 다시 말씀해 주세요.",en:"One moment, please say that again."},target:"잠시만요",options:["Hello / Hi (polite)","One moment, please","Thank you (formal)"],note:"Use 잠시만요 any time you need a pause — at stores, classrooms, or when you haven't heard something clearly."},{kind:"guess",word:{ko:"저",romanization:"jeo",en:"I / me (polite)",pos:"pronoun",nuance:"저 is the humble 'I/me,' the polite counterpart of 나. It does not mean something different from 나 — it encodes DEFERENCE, lowering yourself to raise the listener, so it is the correct choice with elders, strangers, customers, and any formal moment, and it sits naturally with 요-form and -ㅂ니다 speech. Like 나 it has an irregular subject form: 저 + 가 fuses to 제가, not '저가.' Two traps for English speakers: first, the homograph — this 저 (I) is spelled identically to the demonstrative 저 'that (over there),' but sentence position keeps them apart; second, the humble plural 저희 ('we/our'), which has no English equivalent and which learners forget, defaulting to plain 우리 even when politely referring to their own company or family. When in doubt about register, 저 is the safer pronoun."},sentence:{ko:"저는 마이클이에요.",en:"I am Michael."},target:"저",options:["Goodbye (said by the one leaving)","I / me (polite)","Thank you (formal)"],note:"저 is the polite first-person pronoun — always use this until you're on casual terms with the other person."},{kind:"guess",word:{ko:"이름",romanization:"ireum",en:"name",pos:"noun",nuance:"제 이름은 is a safe polite way to introduce your name."},sentence:{ko:"이름이 뭐예요?",en:"What is your name?"},target:"이름",options:["name","student","teacher / instructor"],note:"이름 ends in 'm' (consonant) → 이에요 when you predicate it: 제 이름은 ___이에요."},{kind:"payoff",line:{speaker:"엠마",ko:"네, 처음이에요. 저는 엠마예요.",en:"Yes, it's my first time. I'm Emma."},hl:"저는"}],canDo:"Introduce myself with 저는 ___이에요/예요",id:"chapter-02-b3",chapterId:"chapter-02",index:2},{kind:"pattern",title:"문법 Grammar · N이에요/예요",cards:[{kind:"hunt",name:"N이에요/예요",sub:'polite "to be"',lines:[{tokens:[{pre:"저는",mid:"",post:"",hit:!1},{pre:"학생",mid:"이에요",post:".",hit:!0}],ko:"저는 학생이에요.",en:"I'm a student.",romanization:"jeoneun haksaengieyo."},{tokens:[{pre:"저는",mid:"",post:"",hit:!1},{pre:"하나",mid:"예요",post:".",hit:!0}],ko:"저는 하나예요.",en:"I'm Hana.",romanization:"jeoneun hanayeyo."}],rule:{name:"N이에요/예요",rows:[{when:"Noun ends in a consonant (받침)",add:"이에요",ex:"학생 → 학생이에요 · 선생님 → 선생님이에요"},{when:"Noun ends in a vowel",add:"예요",ex:"의사 → 의사예요 · 하나 → 하나예요"}]},more:{func:`이에요/예요 is the polite present tense of 이다 ("to be"). Attach it to a noun to say what something is: 저는 학생이에요 — "I'm a student."`,funcLead:'이에요/예요 is the polite present tense of 이다 ("to be").',keyPoint:{label:"Polite vs formal, and the negative",body:`이에요/예요 is the everyday polite form — use it in class, with new acquaintances, and in shops. 입니다 (저는 학생입니다) is more formal: presentations, business, announcements. Both are correct, but 이에요/예요 is the natural default in conversation. To say what something is NOT, use N이/가 아니에요: 저는 학생이 아니에요 ("I'm not a student").`},pronunciation:"학생이에요 is pronounced [학쌩이에요]: ㄱ followed by ㅅ tightens the ㅅ to a tense [ㅆ].",pitfall:{wrong:"저는 학생예요.",right:"저는 학생이에요.",explanation:"A consonant ending needs 이에요. 학생 ends in ㅇ (a 받침), so 학생예요 is wrong. Feel the final sound: a consonant takes 이에요, a vowel takes 예요."}}},{kind:"drill",prompt:"This person is a teacher.",sentence:"이분은 선생님___.",options:[{text:"이에요",ok:!0},{text:"예요",ok:!1}],explanation:"It works for other people too — 이분 = 'this person' (polite)."},{kind:"drill",prompt:"This is water.",sentence:"이건 물___.",options:[{text:"예요",ok:!1},{text:"은",ok:!1},{text:"이에요",ok:!0}],explanation:"물 ends in a consonant → 이에요."},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"저는 학생이에요.",ok:!0},{text:"저는 학생예요.",ok:!1}],explanation:"A consonant ending needs 이에요. 학생 ends in ㅇ (a 받침), so 학생예요 is wrong. Feel the final sound: a consonant takes 이에요, a vowel takes 예요."},{kind:"drill",prompt:"빈칸을 채우세요 · Complete the form — Noun ends in a consonant (받침)",sentence:"학생___",options:[{text:"이에요",ok:!0},{text:"예요",ok:!1}],explanation:"학생 → 학생이에요 · 선생님 → 선생님이에요"}],canDo:"Introduce myself with 저는 ___이에요/예요",id:"chapter-02-b4",chapterId:"chapter-02",index:3},{kind:"words",title:"단어 Words 3 · 학생~",cards:[{kind:"guess",word:{ko:"학생",romanization:"haksaeng",en:"student",pos:"noun",nuance:"학생 is a common identity word. Use 이에요 after 학생 because it ends in a consonant."},sentence:{ko:"저는 한국어 학생이에요.",en:"I am a Korean language student."},target:"학생",options:["student","name","Hello / Hi (polite)"],note:"학생 ends in 'ng' (consonant) → 이에요. One of the most-used identity nouns in self-introductions."},{kind:"guess",word:{ko:"선생님",romanization:"seonsaengnim",en:"teacher / instructor",pos:"noun",nuance:"님 makes the word respectful. 선생님 is also used as a polite title."},sentence:{ko:"선생님, 안녕하세요!",en:"Hello, teacher!"},target:"선생님",options:["name","Hello / Hi (polite)","teacher / instructor"],note:"선생님 is both 'teacher' as a noun and the address form used directly — like calling someone 'Teacher' instead of their name."},{kind:"guess",word:{ko:"처음",romanization:"cheoeum",en:"first time",pos:"noun/adverb",nuance:"처음 means 'the first time' or 'the beginning', and it flexibly works as both a noun and a time adverb. As a time word it most often appears as 처음에 'at first' — typically to contrast the early state with how things turn out later (처음에는 어려웠어요 'at first it was hard') — or as 처음으로 'for the first time' for a brand-new experience. Its opposite is 마지막 'the last/final'. The sharp contrast to master is 처음 vs 먼저: 처음 is 'the first TIME / the beginning' (a point in time), whereas 먼저 is 'first in ORDER / ahead of others, beforehand' (먼저 가세요 'go ahead first', 먼저 손을 씻으세요 'wash your hands first'). So 'I'll do this first (before that)' is 먼저, but 'I did this for the first time' is 처음. English 'first' blurs both, which is the trap. You'll meet 처음 early in the set greeting 처음 뵙겠습니다. It pairs with 에, 으로, 부터, and 뵙다/오다/먹다."},sentence:{ko:"처음 뵙겠습니다.",en:"How do you do. / I'm meeting you for the first time."},target:"처음",options:["first time","Hello / Hi (polite)","Goodbye (said by the one leaving)"],note:"처음 뵙겠습니다 is a very formal first-meeting phrase. In everyday language exchange settings, 만나서 반가워요 is more natural."},{kind:"guess",word:{ko:"반갑다",romanization:"bangapda",en:"to be glad / pleased to meet",pos:"adjective",nuance:"반갑다 is the warm rush of gladness at meeting or seeing someone, and it powers Korea's everyday introduction 만나서 반가워요 ('nice to meet you'). It is a ㅂ-irregular adjective: before an 아/어 ending the ㅂ becomes 우 and merges, so 반갑 + 아요 → 반가워요 (formal 반갑습니다, past 반가웠어요). Keep it firmly about PEOPLE (or news/voices tied to people) — you are glad to encounter someone — unlike 기쁘다, which is general happiness about any good thing (passing an exam, a sunny day). A handy contrast: 기쁘다 = happy in general; 반갑다 = specifically happy to see/meet someone; 즐겁다 = enjoyable/having a good time. English-speaker pitfall: 'I'm glad' in English covers everything, but you can't say 반가워요 about an event or an achievement — 시험에 붙어서 반가워요 is wrong; that is 기뻐요. Reserve 반갑다 for the joy of someone's presence, voice, or a welcome reunion."},sentence:{ko:"만나서 정말 반가워요.",en:"I'm so pleased to meet you."},target:"반가워",options:["Hello / Hi (polite)","to be glad / pleased to meet","Goodbye (said by the one leaving)"],note:"반갑다 is an adjective meaning 'glad to see/meet someone.' In 해요 speech it becomes 반가워요 — an irregular adjective (ㅂ irregular: 반갑다 → 반가워요)."},{kind:"guess",word:{ko:"아니에요",romanization:"anieyo",en:"am not / is not / are not",pos:"expression",nuance:"아니에요 negates noun labels. It is not the same as 없어요, which means something does not exist or you do not have it."},sentence:{ko:"저는 학생이 아니에요. 선생님이에요.",en:"I'm not a student. I'm a teacher."},target:"아니에요",options:["Hello / Hi (polite)","Goodbye (said by the one leaving)","am not / is not / are not"],note:"아니에요 is the polite negative of 이에요/예요. Notice the pattern: N이/가 아니에요 — the noun takes 이/가 (subject marker), then 아니에요."},{kind:"payoff",line:{speaker:"민준",ko:"안녕하세요! 오늘 처음이에요?",en:"Hello! Is this your first time here?"},hl:"처음"}],canDo:"Choose 은 or 는 correctly from the 받침",id:"chapter-02-b5",chapterId:"chapter-02",index:4},{kind:"dialogue",title:"대화 Dialogue · 진짜 한국어",cards:[{kind:"chat",setting:"A Korean language exchange meetup in Seoul. Minjun approaches Emma, who is joining for the first time.",lines:[{speaker:"민준",ko:"안녕하세요! 오늘 처음이에요?",en:"Hello! Is this your first time here?",romanization:"Annyeonghaseyo! Oneul cheoeumieyo?"},{speaker:"엠마",ko:"네, 처음이에요. 저는 엠마예요.",en:"Yes, it's my first time. I'm Emma.",romanization:"Ne, cheoeumieyo. Jeoneun emmayeyo."},{speaker:"민준",ko:"만나서 반가워요! 저는 민준이에요.",en:"Nice to meet you! I'm Minjun.",romanization:"Mannaseo bangawoyo! Jeoneun minjunieyo."},{speaker:"엠마",ko:"죄송해요, 이름을 다시 말해 주세요.",en:"Sorry, please say your name again.",romanization:"Joesonghaeyo, ireumeul dasi malhae juseyo."},{speaker:"민준",ko:"네, 민준이에요. 천천히 말할게요. 민-준.",en:"Sure, it is Minjun. I will say it slowly. Min-jun.",romanization:"Ne, minjunieyo. Cheoncheonhi malhalgeyo. Min-jun."},{speaker:"엠마",ko:"아, 민준 씨. 감사합니다.",en:"Ah, Minjun. Thank you.",romanization:"A, Minjun ssi. Gamsahamnida."},{speaker:"민준",ko:"저는 먼저 갈게요. 안녕히 계세요.",en:"I will head out first. Goodbye.",romanization:"Jeoneun meonjeo galgeyo. Annyeonghi gyeseyo."},{speaker:"엠마",ko:"네, 안녕히 가세요. 다음에 또 만나요.",en:"Okay, goodbye. See you again next time.",romanization:"Ne, annyeonghi gaseyo. Daeume tto mannayo."}]},{kind:"order",prompt:"Build: 'I am a student.'",tokens:["저는","학생이에요"],correct:"저는 학생이에요",explanation:"A simple Korean self-introduction starts with the topic 저는. 학생 ends in a consonant, so the polite “am/is” form is 이에요."},{kind:"drill",prompt:"누가 한 말일까요? · Who said this?",sentence:"네, 민준이에요. 천천히 말할게요. 민-준.",options:[{text:"엠마",ok:!1},{text:"민준",ok:!0}],explanation:"Sure, it is Minjun. I will say it slowly. Min-jun."},{kind:"drill",prompt:'무엇이 들어갈까요? · "Hello! Is this your first time here?"',sentence:"___! 오늘 처음이에요?",options:[{text:"안녕히 계세요",ok:!1},{text:"감사합니다",ok:!1},{text:"안녕하세요",ok:!0}],explanation:""}],canDo:"Greet, thank, and apologize politely (안녕하세요 · 감사합니다 · 죄송합니다)",id:"chapter-02-b6",chapterId:"chapter-02",index:5},{kind:"reading",title:"읽기 Reading · 첫 언어 교환 후 메시지 (Text messages after the first language exchange)",cards:[{kind:"read",title:"첫 언어 교환 후 메시지 (Text messages after the first language exchange)",chunks:["민준: 엠마 씨, 오늘 만나서 반가워요. 엠마: 저도 반가워요. 이름을 다시 물어봐서 죄송해요. 민준: 괜찮아요. 한국어 공부는 처음이에요? 엠마: 네, 처음이에요.","천천히 말해 주세요. 민준: 네, 좋아요. 다음 주에 또 만나요? 엠마: 네, 감사합니다. 다음 주에 만나요!"],translation:`Minjun: Emma, nice to meet you today.
Emma: Nice to meet you too. Sorry for asking your name again.
Minjun: It's okay. Is this your first time studying Korean?
Emma: Yes, it is my first time. Please speak slowly.
Minjun: Sure, sounds good. Shall we meet again next week?
Emma: Yes, thank you. See you next week!`,qas:[{q:"What does Emma apologize for in the text exchange?",a:"She apologizes for asking Minjun's name again: 이름을 다시 물어봐서 죄송해요."},{q:"What phrase does Emma use when she needs slower Korean?",a:"천천히 말해 주세요 — Please speak slowly."},{q:"Find all instances of 이에요/예요 in the text. For each one, explain whether the noun ends in a consonant or vowel and why that determines the form used.",a:"처음이에요 appears twice. 처음 ends in the final consonant ㅁ, so it takes 이에요. This demonstrates the phonetic rule: consonant-final noun → 이에요, vowel-final noun → 예요."}]},{kind:"drill",prompt:"지문에서 뭐라고 했어요? · What did the passage say?",sentence:"민준: 엠마 씨, 오늘 ___.",options:[{text:"안녕하세요",ok:!1},{text:"안녕히 계세요",ok:!1},{text:"만나서 반가워요",ok:!0}],explanation:""},{kind:"drill",prompt:"지문에서 뭐라고 했어요? · What did the passage say?",sentence:"___을 다시 물어봐서 죄송해요.",options:[{text:"학생",ok:!1},{text:"이름",ok:!0},{text:"선생님",ok:!1}],explanation:""}],canDo:"Introduce myself with 저는 ___이에요/예요",id:"chapter-02-b7",chapterId:"chapter-02",index:6},{kind:"boss",title:"보스 Boss bite · 다 걸어요",cards:[{kind:"drill",prompt:"Someone asks you 이름이 뭐예요? How do you answer if your name is 지수?",sentence:null,options:[{text:"저는 미국이에요.",ok:!1},{text:"저는 지수예요.",ok:!0},{text:"나는 지수 이름이에요.",ok:!1}],explanation:"Option 1 is wrong because 미국 is a country, not a name — this says 'I am America.' Option 3 is wrong because 이름 (name) is unnecessary in the answer and 나 is too casual for a first meeting. Option 2 is the natural, correct structure: topic (저는) + name + 예요. 지수 ends in a vowel, so use 예요."},{kind:"drill",prompt:"You bump into someone accidentally and want to apologize. Which do you use in this situation?",sentence:null,options:[{text:"감사합니다",ok:!1},{text:"죄송합니다",ok:!0},{text:"만나서 반가워요",ok:!1}],explanation:"감사합니다 means 'thank you' — not an apology. 만나서 반가워요 is 'nice to meet you' — also wrong context. 죄송합니다 is the correct formal apology for causing inconvenience to a stranger. In casual situations with friends, 미안해요 would also work, but 죄송합니다 is the safe formal choice in public."},{kind:"drill",prompt:"저___ 학생이에요. (As for me, I am a student.)",sentence:null,options:[{text:"는",ok:!0},{text:"가",ok:!1},{text:"를",ok:!1}],explanation:'저는 sets "I/me" as the topic for a polite self-introduction. With the subject marker, 저 changes form to 제가 — 저가 does not exist — and 를 would wrongly make 저 an object.'}],canDo:"Choose 은 or 는 correctly from the 받침",id:"chapter-02-b8",chapterId:"chapter-02",index:7}]},{id:"chapter-03",number:3,title:"N이에요/예요 · N은/는",goal:"Use 이에요 after a noun ending in a consonant and 예요 after a noun ending in a vowel",biteCount:8,bites:[{kind:"words",title:"단어 Words 1 · 저~",cards:[{kind:"guess",word:{ko:"저",romanization:"jeo",en:"I / me (humble/polite)",pos:"pronoun",nuance:"저 is the humble 'I/me,' the polite counterpart of 나. It does not mean something different from 나 — it encodes DEFERENCE, lowering yourself to raise the listener, so it is the correct choice with elders, strangers, customers, and any formal moment, and it sits naturally with 요-form and -ㅂ니다 speech. Like 나 it has an irregular subject form: 저 + 가 fuses to 제가, not '저가.' Two traps for English speakers: first, the homograph — this 저 (I) is spelled identically to the demonstrative 저 'that (over there),' but sentence position keeps them apart; second, the humble plural 저희 ('we/our'), which has no English equivalent and which learners forget, defaulting to plain 우리 even when politely referring to their own company or family. When in doubt about register, 저 is the safer pronoun."},sentence:{ko:"저는 학생이에요.",en:"I am a student."},target:"저",options:["name","student","I / me (humble/polite)"],note:"저 ends in a vowel, so the topic marker is 는. Use 저 with strangers and adults; 나 is casual."},{kind:"guess",word:{ko:"이름",romanization:"ireum",en:"name",pos:"noun",nuance:"제 이름은 is a safe polite way to introduce your name."},sentence:{ko:"제 이름은 민수예요.",en:"My name is Minsu."},target:"이름",options:["name","student","teacher"],note:"이름 ends in consonant ㅁ → topic marker 은; 민수 ends in vowel ㅜ → 예요."},{kind:"guess",word:{ko:"학생",romanization:"haksaeng",en:"student",pos:"noun",nuance:"학생 is a common identity word. Use 이에요 after 학생 because it ends in a consonant."},sentence:{ko:"저는 대학생이에요.",en:"I am a university student."},target:"학생",options:["student","name","doctor"],note:"대학생 ends in consonant 받침 ㅇ → 이에요; 대학 (university) + 학생 (student)"},{kind:"guess",word:{ko:"선생님",romanization:"seonsaengnim",en:"teacher",pos:"noun",nuance:"님 makes the word respectful. 선생님 is also used as a polite title."},sentence:{ko:"저는 영어 선생님이에요.",en:"I am an English teacher."},target:"선생님",options:["name","teacher","doctor"],note:"선생님 ends in consonant ㅁ → 이에요; 님 is a respectful suffix — never drop it when addressing a teacher"},{kind:"guess",word:{ko:"의사",romanization:"uisa",en:"doctor",pos:"noun",nuance:"의사 is Sino-Korean 醫師 ('medicine' 醫 + 'master/teacher' 師), so the word literally frames a doctor as a master of medicine — which is why Koreans almost reflexively append 선생님 (의사 선생님) when addressing or referring to one, the way English keeps 'Doctor' as a title. Saying bare 의사 to or about a specific physician can sound flat or even slightly disrespectful, like calling them 'the doc'. Distinguish 의사 (the licensed physician) from 의자 'chair', which differs by a single vowel and trips up beginners constantly, and from 환자 'patient' and 간호사 'nurse', the other people in the room. The natural verb is 환자를 보다 ('see patients') or 진료를 보다/받다, never the English-style '의사를 하다'; a doctor 의사가 되다 ('becomes' a doctor), with the goal marked by 가, not 을."},sentence:{ko:"제 친구는 의사예요.",en:"My friend is a doctor."},target:"의사",options:["name","student","doctor"],note:"의사 ends in vowel ㅏ → 예요; 제 is the possessive form of 저 (my)"},{kind:"guess",word:{ko:"회사원",romanization:"hoesawon",en:"office worker",pos:"noun",nuance:"회사원 is 會社員 ('company-member'), literally a member of a company, and it is the neutral catch-all a salaried employee of a private firm gives when asked 무슨 일 하세요? Contrast it with 직장인, which means 'a working person' in general (anyone with a paid job, including teachers or nurses): every 회사원 is a 직장인, but not every 직장인 is a 회사원. Also separate it from 사업가, the owner who runs the business — a 회사원 is employed by someone else. The pitfall for English speakers is twofold: 회사원 ends in a consonant so the copula is 회사원이에요, never 'office worker'-style 회사원예요; and don't translate 'I work at a company' as a job title — to name the job you simply say 회사원이에요 rather than literally rendering the English sentence."},sentence:{ko:"저는 회사원이에요.",en:"I am an office worker."},target:"회사원",options:["name","office worker","student"],note:"회사원 ends in consonant 받침 ㄴ → 이에요; 회사(company) + 원(member/worker)"},{kind:"payoff",line:{speaker:"지연",ko:"안녕하세요! 저는 지연이에요. 처음 뵙겠습니다.",en:"Hello! I'm Jiyeon. Nice to meet you for the first time."},hl:"저는"}],canDo:"Say what someone or something is with N이에요/예요",id:"chapter-03-b1",chapterId:"chapter-03",index:0},{kind:"pattern",title:"문법 Grammar · N이에요/예요",cards:[{kind:"hunt",name:"N이에요/예요",sub:'the polite copula ("is/am/are")',lines:[{tokens:[{pre:"저는",mid:"",post:"",hit:!1},{pre:"학생",mid:"이에요",post:".",hit:!0}],ko:"저는 학생이에요.",en:"I'm a student.",romanization:"jeo-neun hak-saeng-i-e-yo."},{tokens:[{pre:"이분은",mid:"",post:"",hit:!1},{pre:"제",mid:"",post:"",hit:!1},{pre:"친구",mid:"예요",post:".",hit:!0}],ko:"이분은 제 친구예요.",en:"This (person) is my friend.",romanization:"i-bu-neun je chin-gu-ye-yo."}],rule:{name:"N이에요/예요",rows:[{when:"Noun ends in a consonant (받침)",add:"이에요",ex:"학생 → 학생이에요 · 집 → 집이에요"},{when:"Noun ends in a vowel",add:"예요",ex:"친구 → 친구예요 · 의자 → 의자예요"},{when:'Negative: "is not N" (받침 noun)',add:"이 아니에요",ex:"학생 → 학생이 아니에요"},{when:'Negative: "is not N" (vowel noun)',add:"가 아니에요",ex:"친구 → 친구가 아니에요"}]},more:{func:'N이에요/예요 turns a noun into a polite statement of identity: "X is a/an N." It is the everyday spoken way to say what someone or something is. The negative — "X is not an N" — is N이/가 아니에요.',funcLead:'N이에요/예요 turns a noun into a polite statement of identity: "X is a/an N." It is the everyday spoken way to say what someone or something is.',keyPoint:{label:"이에요/예요 vs 입니다",body:'Both mean "is." 이에요/예요 is the polite-conversational 해요체 you use in everyday talk. 입니다 is the formal 합니다체 used in announcements, presentations, the news, and the military. 입니다 attaches the same way regardless of 받침 — 학생입니다, 친구입니다 (no 이에요/예요 split). They mean the same thing; you choose by setting. This chapter uses 이에요/예요; 입니다 gets its own chapter.'},pronunciation:"After a 받침 noun, 이에요 links onto the consonant: 물이에요 is pronounced [무리에요] and 집이 아니에요 is [지비 아니에요] (연음 — the final consonant slides onto the following vowel).",pitfall:{wrong:"친구이에요 / 학생예요",right:"친구예요 / 학생이에요",explanation:`English has one form, "is," for everything, so learners pick 이에요 or 예요 at random. In Korean the choice is automatic and depends only on the noun's last sound: 받침 → 이에요, vowel → 예요. Check the noun's ending first, then attach the matching form.`}}},{kind:"drill",prompt:"This is water.",sentence:"이건 물___.",options:[{text:"이에요",ok:!0},{text:"예요",ok:!1}],explanation:"물 ends in a consonant (ㄹ) → 이에요; spoken [무리에요] by linking. 이건 = 이것은 (this) shortened."},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "This (person) is my friend."',tokens:["이분은","제","친구예요."],correct:"이분은 제 친구예요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"친구이에요 / 학생예요",ok:!1},{text:"친구예요 / 학생이에요",ok:!0}],explanation:`English has one form, "is," for everything, so learners pick 이에요 or 예요 at random. In Korean the choice is automatic and depends only on the noun's last sound: 받침 → 이에요, vowel → 예요. Check the noun's ending first, then attach the matching form.`},{kind:"drill",prompt:"빈칸을 채우세요 · Complete the form — Noun ends in a consonant (받침)",sentence:"학생___",options:[{text:"예요",ok:!1},{text:"이에요",ok:!0},{text:"이 아니에요",ok:!1}],explanation:"학생 → 학생이에요 · 집 → 집이에요"}],canDo:"Say what someone or something is with N이에요/예요",id:"chapter-03-b2",chapterId:"chapter-03",index:1},{kind:"words",title:"단어 Words 2 · 나라~",cards:[{kind:"guess",word:{ko:"나라",romanization:"nara",en:"country",pos:"noun",nuance:"나라 is the plain NATIVE Korean word for 'country' (not Sino-Korean), and it works for any nation in everyday speech. Its closest synonym is the Sino-Korean 국가 (國家), and the dividing line is register and abstraction: 나라 is warm, everyday, and concrete ('어느 나라?'), while 국가 is formal and institutional, used for the state as a political entity (국가 정책 'national policy', 국가대표 'national team' — note 국가 not 나라 here). So you'd ask a new acquaintance 어느 나라에서 왔어요? but a textbook would write 국가 간의 관계 'relations between states'. The single most important collocation is 우리나라 — written as ONE word (not 우리 나라) when it means 'our country' in the sense of 'Korea, from our shared insider view'. English speakers tend to over-use the literal 'my country' (제 나라), which sounds detached; among Koreans the warm default is 우리나라. Particle behavior is regular: 나라가 많다 (there are many countries), 어느 나라에서 (from which country). Don't reach for 국가 in casual conversation — it sounds stiff and bureaucratic."},sentence:{ko:"어느 나라 사람이에요?",en:"What country are you from?"},target:"나라",options:["country","name","student"],note:"나라 ends in vowel ㅏ → would take 예요 when used as the sentence topic; 어느 = which"},{kind:"guess",word:{ko:"사람",romanization:"saram",en:"person / people",pos:"noun",nuance:"사람 can mean one person or people in general. It is useful for describing crowds, identity, and who someone is."},sentence:{ko:"저는 한국 사람이에요.",en:"I am Korean."},target:"사람",options:["name","student","person / people"],note:"사람 ends in consonant ㅁ → 이에요; [country] + 사람 is the standard pattern for nationality"},{kind:"guess",word:{ko:"이건",romanization:"igeon",en:"this (thing) is / as for this",pos:"pronoun + particle (contraction)",nuance:"Use 이건 when the thing is near you or already visible in the conversation."},sentence:{ko:"이건 뭐예요?",en:"What is this?"},target:"이건",options:["I / me (humble/polite)","this (thing) is / as for this","name"],note:"이건 = 이것 + 은 (contracted); 이것 = this thing, 은 = topic marker; used constantly in real speech — more natural than 이것은"},{kind:"guess",word:{ko:"뭐",romanization:"mwo",en:"what",pos:"question pronoun",nuance:"뭐 is the spoken form of 무엇. It is very common in everyday Korean."},sentence:{ko:"이름이 뭐예요?",en:"What is your name?"},target:"뭐",options:["I / me (humble/polite)","name","what"],note:"뭐 ends in vowel → 예요; 뭐 is the spoken/colloquial form of 무엇 (what)"},{kind:"guess",word:{ko:"아니에요",romanization:"anieyo",en:"is not / no (polite negative copula)",pos:"copula (negative)",nuance:"아니에요 negates noun labels. It is not the same as 없어요, which means something does not exist or you do not have it."},sentence:{ko:"저는 일본 사람이 아니에요.",en:"I am not Japanese."},target:"아니에요",options:["name","is not / no (polite negative copula)","student"],note:"아니에요 is the negative of 이에요/예요; the noun before it takes 이/가 (subject marker): 일본 사람이 아니에요"},{kind:"guess",word:{ko:"제",romanization:"je",en:"my (humble/polite possessive)",pos:"pronoun",nuance:"제 sounds polite and safe. 내 is casual and belongs with close friends or informal speech."},sentence:{ko:"제 이름은 민수예요.",en:"My name is Minsu."},target:"제",options:["my (humble/polite possessive)","name","student"],note:"제 is the possessive form of 저 (polite 'I'); 내 is the possessive of 나 (casual 'I') — use 제 in formal/polite situations"},{kind:"payoff",line:{speaker:"지연",ko:"민호 씨, 어느 나라 사람이에요?",en:"Minho, what country are you from?"},hl:"나라"}],canDo:"Pick 이에요 or 예요 from the noun's final sound (받침 vs vowel)",id:"chapter-03-b3",chapterId:"chapter-03",index:2},{kind:"pattern",title:"문법 Grammar · N은/는",cards:[{kind:"hunt",name:"N은/는",sub:"the topic marker",lines:[{tokens:[{pre:"저",mid:"는",post:"",hit:!0},{pre:"한국어",mid:"",post:"",hit:!1},{pre:"학생이에요.",mid:"",post:"",hit:!1}],ko:"저는 한국어 학생이에요.",en:"I'm a Korean(-language) student.",romanization:"jeo-neun han-gu-geo hak-saeng-i-e-yo."},{tokens:[{pre:"이",mid:"",post:"",hit:!1},{pre:"책",mid:"은",post:"",hit:!0},{pre:"한국어",mid:"",post:"",hit:!1},{pre:"책이에요.",mid:"",post:"",hit:!1}],ko:"이 책은 한국어 책이에요.",en:"This book is a Korean book.",romanization:"i chae-geun han-gu-geo chae-gi-e-yo."}],rule:{name:"N은/는",rows:[{when:"Noun ends in a consonant (받침)",add:"은",ex:"집 → 집은 · 선생님 → 선생님은"},{when:"Noun ends in a vowel",add:"는",ex:"저 → 저는 · 친구 → 친구는"}]},more:{func:'은/는 attaches to a noun to mark it as the topic — the thing you single out to talk about, roughly "as for ___." It is the backbone of introductions (저는…) and of stating what something is, and it can also signal a contrast between two things.',funcLead:'은/는 attaches to a noun to mark it as the topic — the thing you single out to talk about, roughly "as for ___." It is the backbone of introductions (저는…) and of…',keyPoint:{label:"Topic, not subject — 은/는 vs 이/가",body:'은/는 marks the topic ("as for X, …") and often carries a quiet comparison; 이/가 marks the grammatical subject and points to new or specific information (누가 왔어요? — 친구가 왔어요). For now, use 은/는 for introductions and for saying what something is, and use 이/가 when answering "who/what?" The full 은/는 vs 이/가 distinction has its own chapter.'},pronunciation:"After a 받침 noun, 은 links onto the consonant: 책은 is pronounced [채근] and 집은 is [지븐] (연음).",pitfall:{wrong:"저는도 학생이에요.",right:"저도 학생이에요.",explanation:`English keeps the subject the same whether you add "too" or not ("I'm a student" / "I'm a student too"). In Korean, 도 ("also") replaces 은/는 rather than stacking onto it. Drop the 는 and say 저도 — never 저는도.`}}},{kind:"drill",prompt:"The teacher is Korean.",sentence:"선생님___ 한국 사람이에요.",options:[{text:"는",ok:!1},{text:"은",ok:!0}],explanation:"선생님 ends in a consonant → 은; spoken [선생니믄]. 은/는 raises 선생님 as the topic we're describing."},{kind:"drill",prompt:"I'm a student. My friend is a doctor.",sentence:"저___ 학생이에요. 친구는 의사예요.",options:[{text:"은",ok:!1},{text:"는",ok:!0},{text:"이에요요",ok:!1}],explanation:"Two 는 set up a contrast — me vs. my friend — another core job of 은/는."},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "I'm a Korean(-language) student."`,tokens:["저는","한국어","학생이에요."],correct:"저는 한국어 학생이에요.",explanation:""},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "This book is a Korean book."',tokens:["이","책은","한국어","책이에요."],correct:"이 책은 한국어 책이에요.",explanation:""}],canDo:"Pick 이에요 or 예요 from the noun's final sound (받침 vs vowel)",id:"chapter-03-b4",chapterId:"chapter-03",index:3},{kind:"words",title:"단어 Words 3 · 직업~",cards:[{kind:"guess",word:{ko:"직업",romanization:"jigeop",en:"job / occupation / profession",pos:"noun",nuance:"직업 (職業, 'duty-work') is the abstract category of one's profession or line of work — the answer to 'what do you do for a living,' not the daily grind itself. The dividing line you must feel: 직업 is the occupation as an identity (간호사, 교사), 직장 is the specific company you belong to, and 일/업무 is the actual work you perform. So 직업이 뭐예요? asks WHAT you are, while 무슨 일 해요? asks more casually what work you do day to day. Register is neutral-to-formal, perfect for a first meeting; among close friends 무슨 일 해? feels warmer. The classic English-speaker trap is 직업을 해요 to mean 'I work' — Korean never 'does' an occupation; you simply state it with 이에요/예요 (선생님이에요), and the particle after 직업 is 이 (직업이), since the word ends in a consonant."},sentence:{ko:"직업이 뭐예요?",en:"What is your job?"},target:"직업",options:["name","job / occupation / profession","student"],note:"직업 ends in consonant 받침 ㅂ → if the answer uses it as topic: 직업은; as subject in the question: 직업이"},{kind:"guess",word:{ko:"한국어",romanization:"hangugeo",en:"Korean language",pos:"noun",nuance:"한국어 points to the language. 한국 사람 points to a Korean person."},sentence:{ko:"이건 한국어예요.",en:"This is Korean (the language)."},target:"한국어",options:["Korean language","name","student"],note:"한국어 ends in vowel ㅓ → 예요. Use this when identifying a word, sentence, label, or class as Korean."},{kind:"guess",word:{ko:"영어",romanization:"yeongeo",en:"English language",pos:"noun",nuance:"영어 is the language. 미국 사람 means an American person."},sentence:{ko:"저는 영어 선생님이에요.",en:"I am an English teacher."},target:"영어",options:["English language","name","student"],note:"영어 describes the kind of teacher; 선생님 is the final noun, and it ends in ㅁ → 이에요."},{kind:"guess",word:{ko:"반갑습니다",romanization:"bangapseumnida",en:"Nice to meet you",pos:"expression"},sentence:{ko:"저는 민준이에요. 반갑습니다!",en:"I'm Minjun. Nice to meet you!"},target:"반갑습니다",options:["Nice to meet you","I / me (humble/polite)","name"],note:"반갑습니다 is formal; 반가워요 is slightly less formal — both are appropriate when meeting someone for the first time"},{kind:"guess",word:{ko:"어느",romanization:"eoneu",en:"which / what (kind of)",pos:"determiner",nuance:"어느 means 'which' and is a determiner: it ALWAYS sits in front of a noun and selects one option from a limited, often visible set (어느 것, 어느 나라, 어느 쪽). The synonym you must not blur is 무슨: 어느 chooses from a known, bounded group ('which of these?'), while 무슨 asks 'what kind of' from an open field (무슨 음악 좋아해요? 'what kind of music?'). So 어느 영화 leans toward 'which (of the movies we're choosing among)?' and 무슨 영화 toward 'what (kind of) movie?' The English-speaker pitfall is using 어느 like the pronoun 'which one' on its own — but it cannot stand alone; you must attach a noun, and for 'which one' specifically you say 어느 것/어느 거. Learn 어느 정도 as a unit; it idiomatically means 'to what extent / roughly how much.'"},sentence:{ko:"어느 나라 사람이에요?",en:"Which country are you from?"},target:"어느",options:["which / what (kind of)","I / me (humble/polite)","name"],note:"어느 is a modifier — it must be followed by a noun; unlike 어디 (where), 어느 modifies a noun directly"},{kind:"payoff",line:{speaker:"지연",ko:"민호 씨, 어느 나라 사람이에요?",en:"Minho, what country are you from?"},hl:"어느"}],canDo:"Single out a topic with N은/는 (저는, 이름은)",id:"chapter-03-b5",chapterId:"chapter-03",index:4},{kind:"dialogue",title:"대화 Dialogue · 진짜 한국어",cards:[{kind:"chat",setting:"Jiyeon, a Korean office worker, meets Minho, a new foreign colleague, in the break room on his first day",lines:[{speaker:"지연",ko:"안녕하세요! 저는 지연이에요. 처음 뵙겠습니다.",en:"Hello! I'm Jiyeon. Nice to meet you for the first time.",romanization:"Annyeonghaseyo! Jeoneun jiyeonieyo. Cheoeum boepgetseumnida."},{speaker:"민호",ko:"안녕하세요! 저는 민호예요. 저도 반가워요.",en:"Hello! I'm Minho. I'm glad to meet you too.",romanization:"Annyeonghaseyo! Jeoneun minhoyeyo. Jeodo bangawoyo."},{speaker:"지연",ko:"민호 씨, 어느 나라 사람이에요?",en:"Minho, what country are you from?",romanization:"Minho ssi, eoneu nara saramieyo?"},{speaker:"민호",ko:"저는 호주 사람이에요. 제 나라는 호주예요.",en:"I'm Australian. My country is Australia.",romanization:"Jeoneun hoju saramieyo. Je naraneun hojuyeyo."},{speaker:"지연",ko:"아, 그래요? 직업이 뭐예요?",en:"Oh, really? What is your job?",romanization:"A, geuraeyo? Jigeobi mwoyeyo?"},{speaker:"민호",ko:"저는 디자이너예요. 지연 씨는요?",en:"I'm a designer. What about you, Jiyeon?",romanization:"Jeoneun dijaineoyeyo. Jiyeon ssineunyo?"},{speaker:"지연",ko:"저는 회사원이에요. 이건 제 명함이에요.",en:"I'm an office worker. This is my business card.",romanization:"Jeoneun hoesawonieyo. Igeon je myeonghamieyo."},{speaker:"민호",ko:"감사합니다. 이건 제 명함이에요. 잘 부탁드려요!",en:"Thank you. This is my business card. I look forward to working with you!",romanization:"Gamsahamnida. Igeon je myeonghamieyo. Jal butakdeuryeoyo!"}]},{kind:"order",prompt:"Build: 'This is coffee.'",tokens:["이건","커피예요"],correct:"이건 커피예요",explanation:"이건 sets “this thing” as the topic. 커피 ends in a vowel sound, so the natural copula form is 예요."},{kind:"drill",prompt:"누가 한 말일까요? · Who said this?",sentence:"감사합니다. 이건 제 명함이에요. 잘 부탁드려요!",options:[{text:"민호",ok:!0},{text:"지연",ok:!1}],explanation:"Thank you. This is my business card. I look forward to working with you!"},{kind:"drill",prompt:'무엇이 들어갈까요? · "Minho, what country are you from?"',sentence:"민호 씨, 어느 ___ 사람이에요?",options:[{text:"이름",ok:!1},{text:"학생",ok:!1},{text:"나라",ok:!0}],explanation:""}],canDo:"Say what someone or something is with N이에요/예요",id:"chapter-03-b6",chapterId:"chapter-03",index:5},{kind:"reading",title:"읽기 Reading · 새 친구 소개 (Introducing a New Friend)",cards:[{kind:"read",title:"새 친구 소개 (Introducing a New Friend)",chunks:["엄마, 저 오늘 새 친구 생겼어요! 이름은 지수예요. 지수는 대학생이에요. 우리 학교 학생이에요.","지수 씨는 제주도 사람이에요. 저는 서울 사람이에요. 지수 씨의 꿈은 영어 선생님이에요. 정말 좋은 사람이에요!"],translation:"Mom, I made a new friend today! Her name is Jisu. Jisu is a university student. She's a student at our school. Jisu is from Jeju Island. I am from Seoul. Jisu's dream is to be an English teacher. She is a really good person!",qas:[{q:"What is the new friend's name and where is she from?",a:"이름은 지수예요 (Her name is Jisu). 제주도 사람이에요 (She is from Jeju Island)."},{q:"What is Jisu's dream job?",a:"꿈은 영어 선생님이에요 (Her dream is to be an English teacher). 선생님 ends in consonant ㅁ → 이에요."},{q:"Find all the 이에요/예요 forms in the text. For each one, explain why 이에요 or 예요 was chosen based on the noun it follows.",a:"지수예요 — 지수 ends in vowel ㅜ → 예요. 대학생이에요 — 대학생 ends in consonant 받침 ㅇ → 이에요. 학생이에요 — 학생 ends in consonant 받침 ㅇ → 이에요. 제주도 사람이에요 — 사람 ends in consonant ㅁ → 이에요. 서울 사람이에요 — 사람 ends in consonant ㅁ → 이에요. 영어 선생님이에요 — 선생님 ends in consonant ㅁ → 이에요. 좋은 사람이에요 — 사람 ends in consonant ㅁ → 이에요."}]},{kind:"drill",prompt:"지문에서 뭐라고 했어요? · What did the passage say?",sentence:"___은 지수예요.",options:[{text:"이름",ok:!0},{text:"의사",ok:!1},{text:"회사원",ok:!1}],explanation:""},{kind:"drill",prompt:"지문에서 뭐라고 했어요? · What did the passage say?",sentence:"지수는 대___이에요.",options:[{text:"의사",ok:!1},{text:"회사원",ok:!1},{text:"학생",ok:!0}],explanation:""}],canDo:"Pick 이에요 or 예요 from the noun's final sound (받침 vs vowel)",id:"chapter-03-b7",chapterId:"chapter-03",index:6},{kind:"boss",title:"보스 Boss bite · 다 걸어요",cards:[{kind:"drill",prompt:"You want to say 'I am not Japanese.' Which sentence is correct?",sentence:null,options:[{text:"저는 일본 사람이에요.",ok:!1},{text:"저는 일본 사람이 아니에요.",ok:!0},{text:"저는 일본 사람이에요 아니에요.",ok:!1}],explanation:"The careful beginner form is [noun] + 이/가 아니에요. 사람 ends in consonant ㅁ → use 이 before 아니에요. The first option says the opposite: 'I am Japanese.' The third option wrongly stacks 이에요 and 아니에요."},{kind:"drill",prompt:"저___ 민준이에요. (As for me, I am Minjun.)",sentence:null,options:[{text:"는",ok:!0},{text:"를",ok:!1},{text:"가",ok:!1}],explanation:"저는 introduces the topic “as for me” before giving your name. 를 would mark an object, which does not fit an identity sentence."}],canDo:"Single out a topic with N은/는 (저는, 이름은)",id:"chapter-03-b8",chapterId:"chapter-03",index:7}]},{id:"chapter-04",number:4,title:"있어요/없어요 · N이/가",goal:"Use 있어요 and 없어요 to express existence ('there is / there isn't') and possession ('I have / I don't have')",biteCount:8,bites:[{kind:"words",title:"단어 Words 1 · 시간~",cards:[{kind:"guess",word:{ko:"시간",romanization:"sigan",en:"time",pos:"noun",nuance:"시간 works with 있어요/없어요 and is essential for scheduling."},sentence:{ko:"지금 시간이 있어요?",en:"Do you have time right now?"},target:"시간",options:["time","reservation / booking","money"],note:"시간 ends in consonant ㄴ → 시간이. The presence lamp: is time available?"},{kind:"guess",word:{ko:"예약",romanization:"yeyak",en:"reservation / booking",pos:"noun",nuance:"예약 is the noun. 예약하다 is the verb 'to reserve/book.' In this chapter, focus first on the noun with 있어요/없어요."},sentence:{ko:"예약이 있어요?",en:"Do you have a reservation?"},target:"예약",options:["time","money","reservation / booking"],note:"예약 ends in consonant ㄱ → 예약이. Essential phrase at hotels and restaurants."},{kind:"guess",word:{ko:"돈",romanization:"don",en:"money",pos:"noun",nuance:"돈 is money. In stores, 카드 and 현금 are often more specific and useful."},sentence:{ko:"지금 돈이 없어요.",en:"I don't have money right now."},target:"돈",options:["money","time","reservation / booking"],note:"돈 ends in consonant ㄴ → 돈이. A survival phrase for daily life."},{kind:"guess",word:{ko:"문제",romanization:"munje",en:"problem / issue",pos:"noun",nuance:"문제(問題, 'ask + topic') has two everyday senses English keeps apart: a trouble or difficulty ('we have a problem') AND a question on a test or exercise ('problem 3'). Crucially, both are solved with the same verb 풀다 (literally 'to untie/loosen') — 문제를 풀다 works for a math item and for a real-life difficulty alike, where English would switch to 'answer' vs 'solve.' Other key partners: 문제가 생기다 (a problem arises), 문제가 되다 (to become an issue), and the handy one-word 문제없어요 ('no problem'). Contrast 문제 with 질문 (a question you ASK someone to get information) — a test 문제 is a problem to solve, but raising your hand to ask is 질문하다, not 문제하다. The English-speaker pitfall is the subject/object split: existence and arising take 이 (문제가 있다/생기다), but solving takes 를 (문제를 풀다) — learners often say 문제가 풀어요."},sentence:{ko:"문제가 없어요.",en:"There is no problem."},target:"문제",options:["time","reservation / booking","problem / issue"],note:"문제 ends in vowel 에 → 문제가. A very common reassurance phrase."},{kind:"guess",word:{ko:"화장실",romanization:"hwajangsil",en:"bathroom / restroom",pos:"noun",nuance:"화장실 is the normal public word for bathroom/restroom."},sentence:{ko:"여기 화장실이 있어요?",en:"Is there a bathroom here?"},target:"화장실",options:["time","bathroom / restroom","reservation / booking"],note:"화장실 ends in consonant ㄹ → 화장실이. One of the most important travel questions."},{kind:"guess",word:{ko:"친구",romanization:"chingu",en:"friend",pos:"noun",nuance:"친구 can mean friend or same-age peer depending on context."},sentence:{ko:"여기에 친구가 있어요.",en:"My friend is here."},target:"친구",options:["time","reservation / booking","friend"],note:"친구 ends in vowel 구 → 친구가. Spotlight on the friend as the one who exists/is present."},{kind:"payoff",line:{speaker:"직원",ko:"어서 오세요. 예약이 있으세요?",en:"Welcome. Do you have a reservation?"},hl:"예약"}],canDo:"Say something exists or you have it with 있어요",id:"chapter-04-b1",chapterId:"chapter-04",index:0},{kind:"pattern",title:"문법 Grammar · 있어요/없어요",cards:[{kind:"hunt",name:"있어요/없어요",sub:"there is / isn't, have / don't have",lines:[{tokens:[{pre:"물이",mid:"",post:"",hit:!1},{pre:"",mid:"있어요",post:".",hit:!0}],ko:"물이 있어요.",en:"There is water. / I have water.",romanization:"muri isseoyo."},{tokens:[{pre:"친구가",mid:"",post:"",hit:!1},{pre:"",mid:"없어요",post:".",hit:!0}],ko:"친구가 없어요.",en:"I don't have any friends here. / There's no friend.",romanization:"chinguga eopseoyo."}],rule:{name:"있어요/없어요",rows:[{when:"Something exists / is present",add:"있어요",ex:"친구 → 친구가 있어요 · 책 → 책이 있어요"},{when:"Something doesn't exist / you don't have it",add:"없어요",ex:"시간 → 시간이 없어요 · 돈 → 돈이 없어요"},{when:"Asking 'is there…?' / 'do you have…?'",add:"있어요? / 없어요?",ex:"시간 있어요? · 물 없어요?"}]},more:{func:`있어요 says that something exists or is present ("there is"), and also that you have it ("I have ___"). 없어요 is its opposite — "there isn't" / "I don't have ___." One pair of verbs covers both existence and possession, so it's one of the most useful things to learn early.`,funcLead:'있어요 says that something exists or is present ("there is"), and also that you have it ("I have ___").',keyPoint:{label:"있어요 (exists / have) ≠ 이에요/예요 (is / equals)",body:`이에요/예요 says what something IS — its identity: 저는 학생이에요 = "I'm a student." 있어요/없어요 says something EXISTS, or that you HAVE it: 학생이 있어요 = "There's a student." English uses "there is" for both ideas, so beginners grab the wrong one. Quick test: if you can swap in "have" or "there is/exists," use 있어요; if you mean "X equals Y," use 이에요/예요. (The deeper rules of 이에요/예요 are in chapter 03.)`},pronunciation:"있어요 is pronounced [이써요]: the 받침 ㅆ carries over onto the next vowel (linking, 연음).",pitfall:{wrong:'저는 친구예요. (meaning "I have a friend.")',right:"친구가 있어요.",explanation:'예요/이에요 means "to be (equal something)," so 저는 친구예요 says "I AM a friend," not "I have a friend." To say you have something, use 있어요: 친구가 있어요. Korean has no separate verb "to have" — possession is just existence with 있어요/없어요.'}}},{kind:"drill",prompt:"Do you have time?",sentence:"시간 ___?",options:[{text:"있어요",ok:!0},{text:"없어요",ok:!1}],explanation:"In everyday speech the 이/가 is usually dropped — 시간(이) 있어요?"},{kind:"drill",prompt:"There are a lot of books at home.",sentence:"집에 책이 많이 ___.",options:[{text:"있어요",ok:!0},{text:"없어요",ok:!1},{text:"가",ok:!1}],explanation:"집에 = 'at home' (location, 에); the thing that exists, 책, still takes 이/가."},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"친구가 있어요.",ok:!0},{text:'저는 친구예요. (meaning "I have a friend.")',ok:!1}],explanation:'예요/이에요 means "to be (equal something)," so 저는 친구예요 says "I AM a friend," not "I have a friend." To say you have something, use 있어요: 친구가 있어요. Korean has no separate verb "to have" — possession is just existence with 있어요/없어요.'},{kind:"drill",prompt:"빈칸을 채우세요 · Complete the form — Something exists / is present",sentence:"친구___",options:[{text:"가 있어요",ok:!0},{text:"이 없어요",ok:!1}],explanation:"친구 → 친구가 있어요 · 책 → 책이 있어요"}],canDo:"Say something exists or you have it with 있어요",id:"chapter-04-b2",chapterId:"chapter-04",index:1},{kind:"words",title:"단어 Words 2 · 방~",cards:[{kind:"guess",word:{ko:"방",romanization:"bang",en:"room",pos:"noun",nuance:"방 is the Sino-Korean character 房 ('room, chamber') and is the all-purpose word for any enclosed room, and it builds dozens of everyday compounds: 안방 (master/main room), 공부방 (study room), 노래방 (singing room/karaoke), 찜질방 (Korean sauna room), and PC방 (internet cafe). The key contrast to fix in your head is 방 vs 집: 집 is the whole house/home, but 방 is just one room inside it, so 'I'm going home' must be 집에 가요, never 방에 가요. The grammar trap is the 에 vs 에서 split: merely being located in the room uses 에 (방에 있어요 = it's in the room), but any action carried out inside the room uses 에서 (방에서 공부해요 = I study in my room) — English 'in the room' blurs both, and overusing 에 for actions is the #1 beginner error. Collocations: 방을 치우다/정리하다 (tidy the room), 방이 좁다 (the room is cramped). Register is fully neutral, used by everyone."},sentence:{ko:"빈 방이 있어요?",en:"Is there a vacant room?"},target:"방",options:["time","reservation / booking","room"],note:"방 ends in consonant ㅇ → 방이. Essential hotel check-in phrase."},{kind:"guess",word:{ko:"자리",romanization:"jari",en:"seat / spot / space",pos:"noun",nuance:"자리 is the native everyday noun for a seat or a spot you occupy — a seat on a train, a table at a restaurant, a place in a line, even a 'position' in life (좋은 자리 = a good job/standing). The crucial contrast is 자리 vs 의자: 의자 (椅子) is the physical chair as an object, while 자리 is the seat/spot as a space you take or reserve — so you ask 자리 있어요? ('is there a seat/spot?'), not 의자 있어요? (which sounds like 'do you have a chair to sell?'). 자리 collocates richly: 창가 자리 (window seat), 빈자리 (empty seat), 자리에 앉다 (sit down), 자리를 잡다/맡다 (grab/save a spot), 자리를 비우다 (step away from one's seat). Register is neutral and friendly. English-speaker pitfall: with 앉다 ('sit') use the location particle 에 — 자리에 앉아요, not 자리 앉아요; and to choose a seat type use 로/으로 (창가 자리로)."},sentence:{ko:"자리가 있어요?",en:"Is there a seat available?"},target:"자리",options:["seat / spot / space","time","reservation / booking"],note:"자리 ends in vowel 리 → 자리가. Used at restaurants, cafés, cinemas."},{kind:"guess",word:{ko:"물",romanization:"mul",en:"water",pos:"noun",nuance:"물 is essential in restaurants. 물 주세요 is more useful than just knowing “water.”"},sentence:{ko:"물이 없어요.",en:"There is no water."},target:"물",options:["water","time","reservation / booking"],note:"물 ends in consonant ㄹ → 물이. Works for 'there is no water' or 'I don't have water.'"},{kind:"guess",word:{ko:"시간이 있다",romanization:"sigani itda",en:"to have time / be available",pos:"expression",nuance:"시간 works with 있어요/없어요 and is essential for scheduling."},sentence:{ko:"내일 시간이 있어요?",en:"Are you free tomorrow?"},target:null,options:["to have time / be available","reservation / booking","money"],note:"시간이 있다 is the go-to way to ask if someone is available — more natural than direct schedule questions."},{kind:"guess",word:{ko:"있어요",romanization:"isseoyo",en:"there is / have / exists (polite)",pos:"verb",nuance:"있어요 can mean both 'there is' and 'have.' Context tells whether the sentence is about existence or possession."},sentence:{ko:"냉장고에 우유가 있어요.",en:"There is milk in the fridge."},target:"있어요",options:["there is / have / exists (polite)","to reserve / book","time"],note:"있어요 checks the presence lamp: is milk in the fridge? Yes. Note 에 for the location and 이/가 for the thing that exists."},{kind:"guess",word:{ko:"없어요",romanization:"eopseoyo",en:"there isn't / don't have / absent (polite)",pos:"verb",nuance:"없어요 negates existence or possession. It is not the same as 아니에요, which negates a noun identity."},sentence:{ko:"오늘은 시간이 없어요.",en:"I don't have time today."},target:"없어요",options:["there isn't / don't have / absent (polite)","to reserve / book","time"],note:"없어요 is the lamp-OFF version. 오늘은 sets the time as topic with 은/는; 시간이 is the subject of non-existence."},{kind:"payoff",line:{speaker:"민지",ko:"네, 예약이 있어요. 이름은 민지예요.",en:"Yes, I have a reservation. The name is Minji."},hl:"있어요"}],canDo:"Say something is missing or you don't have it with 없어요",id:"chapter-04-b3",chapterId:"chapter-04",index:2},{kind:"pattern",title:"문법 Grammar · N이/가",cards:[{kind:"hunt",name:"N이/가",sub:"the subject particle",lines:[{tokens:[{pre:"친구",mid:"가",post:"",hit:!0},{pre:"와요.",mid:"",post:"",hit:!1}],ko:"친구가 와요.",en:"A friend is coming.",romanization:"chinguga wayo."},{tokens:[{pre:"물",mid:"이",post:"",hit:!0},{pre:"없어요.",mid:"",post:"",hit:!1}],ko:"물이 없어요.",en:"There's no water.",romanization:"muri eopseoyo."}],rule:{name:"N이/가",rows:[{when:"Noun ends in a consonant (받침)",add:"이",ex:"책 → 책이 · 물 → 물이"},{when:"Noun ends in a vowel",add:"가",ex:"친구 → 친구가 · 학교 → 학교가"},{when:"Irregular forms with 가",add:"제가 / 내가 / 누가",ex:"저 → 제가 (not 저가) · 나 → 내가 · 누구 → 누가"}]},more:{func:`이/가 marks the grammatical subject — the doer, or the thing that exists — especially when it's new information or the specific answer to a question. It's the natural partner of 있어요/없어요 (친구가 있어요) and the marker for "who/what" questions and their answers.`,funcLead:"이/가 marks the grammatical subject — the doer, or the thing that exists — especially when it's new information or the specific answer to a question.",keyPoint:{label:"이/가 (subject / new) vs 은/는 (topic / known)",body:`This is the contrast that confuses every learner. 은/는 sets the topic — "as for ___" — known information you want to comment on (저는 학생이에요). 이/가 spotlights the subject as NEW or SPECIFIC — it points and says "this one." The clearest test is a question: 누가 왔어요? ("Who came?") asks for new info, so the answer 친구가 왔어요 takes 이/가 — that's the new piece. Once it's established you can switch to 는: 친구가 왔어요. 그 친구는 미국 사람이에요. Note too that 있어요/없어요 almost always pairs with 이/가. (The full 은/는 vs 이/가 story is its own chapter — here just learn that answers to who/what questions and existence both take 이/가.)`},pronunciation:"책이 is pronounced [채기]: the 받침 ㄱ carries onto the next vowel (linking, 연음).",pitfall:{wrong:"저가 한국 사람이에요.",right:"제가 한국 사람이에요.",explanation:'When 이/가 follows 저 ("I"), the form is the irregular 제가 — never 저가. The same happens with 나 → 내가 and 누구 → 누가. Beginners regularize to 저가 because the rule says "vowel + 가," but these three pronouns are fixed exceptions you just memorize.'}}},{kind:"drill",prompt:"Who is a student?",sentence:"누___ 학생이에요?",options:[{text:"가",ok:!0},{text:"이",ok:!1}],explanation:"누구 + 가 contracts to 누가. 'Who?' questions take 이/가, not 은/는."},{kind:"drill",prompt:"I'm Korean. (answering 'who?')",sentence:"제___ 한국 사람이에요.",options:[{text:"가",ok:!0},{text:"있어요",ok:!1},{text:"없어요",ok:!1}],explanation:"저 + 가 is the irregular 제가, never 저가. Used to pin down 'who.'"},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"저가 한국 사람이에요.",ok:!1},{text:"제가 한국 사람이에요.",ok:!0}],explanation:'When 이/가 follows 저 ("I"), the form is the irregular 제가 — never 저가. The same happens with 나 → 내가 and 누구 → 누가. Beginners regularize to 저가 because the rule says "vowel + 가," but these three pronouns are fixed exceptions you just memorize.'},{kind:"drill",prompt:"빈칸을 채우세요 · Complete the form — Noun ends in a consonant (받침)",sentence:"책___",options:[{text:"가",ok:!1},{text:"이",ok:!0}],explanation:"책 → 책이 · 물 → 물이"}],canDo:"Say something is missing or you don't have it with 없어요",id:"chapter-04-b4",chapterId:"chapter-04",index:3},{kind:"words",title:"단어 Words 3 · 많다~",cards:[{kind:"guess",word:{ko:"많다",romanization:"manta",en:"to be a lot / many",pos:"adjective",nuance:"많다 describes quantity. 많이 is the adverb form “a lot.” Learners should practice both because 많아요 describes a noun, while 많이 describes an action."},sentence:{ko:"오늘 사람이 많아요.",en:"There are a lot of people today."},target:"많아",options:["to hurt / be sick / be in pain","to be good / to like","to be a lot / many"],note:"사람이 많아요 uses 이/가 — the spotlight is on 사람 as the thing that is plentiful. 많다 often pairs with 이/가."},{kind:"guess",word:{ko:"예약하다",romanization:"yeyakada",en:"to reserve / book",pos:"verb",nuance:"예약하다 works for restaurants, hotels, tickets, classes, and appointments."},sentence:{ko:"식당을 예약했어요.",en:"I made a restaurant reservation."},target:"예약",options:["to reserve / book","there is / have / exists (polite)","there isn't / don't have / absent (polite)"],note:"When 예약 is used as a verb (예약하다), the restaurant is the object → 을/를. Compare: 예약이 있어요 (the reservation exists → 이/가)."},{kind:"guess",word:{ko:"아프다",romanization:"apeuda",en:"to hurt / be sick / be in pain",pos:"adjective",nuance:"아프다 covers both a specific body part hurting (배가 아파요 = my stomach hurts) and the whole-body state of being unwell/sick. The crucial point for English speakers: it is a descriptive adjective, not an action verb, so you describe yourself as 아파요, never 아파해요 — that -해요 ending belongs to verbs like 좋아해요. To say WHAT hurts, the hurting part takes the subject particle 이/가, not 을/를: 머리가 아파요, never 머리를 아파요, because nothing is doing an action to the head; the head simply is in a hurting state. The stem 아프- is ㅡ-irregular: before the -아/어 ending the bare ㅡ drops and, because the remaining vowel ㅏ is bright, 아 is chosen, giving 아 + 아 → 아파요 (not 아프어요). Compare 아프다 with 슬프다 (sad): both are emotional/physical states ending in -프다 and both drop ㅡ the same way (슬퍼요), so once you master 아파요 the pattern transfers. Note the polite/respectful form for an elder is 편찮으세요, a separate honorific word you would use instead of 아프세요 for grandparents."},sentence:{ko:"배가 아파요.",en:"My stomach hurts."},target:null,options:["to hurt / be sick / be in pain","to be a lot / many","to be good / to like"],note:"배 ends in vowel 배 → 배가. The body part that hurts takes 이/가 — this is a core pattern for describing symptoms."},{kind:"guess",word:{ko:"좋다",romanization:"jota",en:"to be good / to like",pos:"adjective",nuance:"좋아요 can mean “it is good” or “I like it.” The subject often takes 이/가."},sentence:{ko:"커피가 좋아요.",en:"I like coffee. / Coffee is good."},target:"좋아",options:["to be a lot / many","to be good / to like","to hurt / be sick / be in pain"],note:"In the 'I like X' pattern, X takes 이/가, not 을/를. The spotlight (이/가) is on the thing liked, not the object of an action."}],canDo:"Mark the subject or the thing that exists with N이/가",id:"chapter-04-b5",chapterId:"chapter-04",index:4},{kind:"dialogue",title:"대화 Dialogue · 진짜 한국어",cards:[{kind:"chat",setting:"Minji and Junho are checking in at a hotel in Busan",lines:[{speaker:"직원",ko:"어서 오세요. 예약이 있으세요?",en:"Welcome. Do you have a reservation?",romanization:"Eoseo oseyo. Yeyagi isseuseyo?"},{speaker:"민지",ko:"네, 예약이 있어요. 이름은 민지예요.",en:"Yes, I have a reservation. The name is Minji.",romanization:"Ne, yeyagi isseoyo. Ireumeun minjiyeyo."},{speaker:"직원",ko:"잠깐만요... 죄송합니다, 예약이 없어요.",en:"Just a moment... I'm sorry, there is no reservation.",romanization:"Jamkkanmanyo... Joesonghamnida, yeyagi eopseoyo."},{speaker:"준호",ko:"어? 예약이 있어요. 이름을 다시 확인해 주세요.",en:"Oh? We do have a reservation. Please check the name again.",romanization:"Eo? Yeyagi isseoyo. Ireumeul dasi hwaginhae juseyo."},{speaker:"직원",ko:"다시 확인할게요. 아, 예약이 있어요.",en:"Let me check again. Ah, there is a reservation.",romanization:"Dasi hwaginhalgeyo. A, yeyagi isseoyo."},{speaker:"민지",ko:"다행이에요. 방이 있어요?",en:"That's a relief. Is there a room?",romanization:"Dahaengieyo. Bangi isseoyo?"},{speaker:"직원",ko:"네, 2층에 방이 있어요. 문제가 없어요.",en:"Yes, there's a room on the 2nd floor. No problem.",romanization:"Ne, i-cheunge bangi isseoyo. Munjega eopseoyo."},{speaker:"준호",ko:"감사합니다! 여기 화장실이 있어요?",en:"Thank you! Is there a bathroom here?",romanization:"Gamsahamnida! Yeogi hwajangsiri isseoyo?"}]},{kind:"order",prompt:"Build: 'I do not have time.'",tokens:["시간이","없어요"],correct:"시간이 없어요",explanation:"The thing you do not have is marked with 이/가. 없어요 states non-existence or not having, so 시간이 없어요 is the natural chunk."},{kind:"drill",prompt:"누가 한 말일까요? · Who said this?",sentence:"어? 예약이 있어요. 이름을 다시 확인해 주세요.",options:[{text:"직원",ok:!1},{text:"준호",ok:!0}],explanation:"Oh? We do have a reservation. Please check the name again."},{kind:"drill",prompt:'무엇이 들어갈까요? · "Welcome. Do you have a reservation?"',sentence:"어서 오세요. ___이 있으세요?",options:[{text:"시간",ok:!1},{text:"예약",ok:!0},{text:"돈",ok:!1}],explanation:""}],canDo:"Say something exists or you have it with 있어요",id:"chapter-04-b6",chapterId:"chapter-04",index:5},{kind:"reading",title:"읽기 Reading · 호텔 예약 문자 (Hotel Booking Text Exchange)",cards:[{kind:"read",title:"호텔 예약 문자 (Hotel Booking Text Exchange)",chunks:["유나: 오빠, 내일 시간이 있어요? 준서: 네, 시간이 있어요. 왜요? 유나: 부산에 같이 가요! 호텔 예약이 있어요? 준서: 아직 예약이 없어요. 지금 바로 예약할게요.","유나: 빈 방이 있어요? 준서: 네, 바다 뷰 방이 있어요. 문제가 없어요! 유나: 완전 좋아요! 돈이 있어요? 준서: 네, 돈이 있어요. 걱정하지 마세요."],translation:`Yuna: Oppa, do you have time tomorrow?
Junseo: Yes, I have time. Why?
Yuna: Let's go to Busan together! Do you have a hotel reservation?
Junseo: Not yet, there's no reservation. I'll book it right now.
Yuna: Is there a vacant room?
Junseo: Yes, there's a room with an ocean view. No problem!
Yuna: That's great! Do you have money?
Junseo: Yes, I have money. Don't worry.`,qas:[{q:"Does Junseo already have a hotel reservation when the conversation starts?",a:"No. He says 아직 예약이 없어요 (Not yet, there is no reservation). He books one during the conversation."},{q:"What kind of room does Junseo find?",a:"바다 뷰 방 — a room with an ocean view."},{q:"Find every instance of 이/가 있어요 or 이/가 없어요 in the text. For each, identify the noun, explain why 이 or 가 was chosen, and state whether it expresses existence or possession.",a:"1) 시간이 있어요 (×2) — 시간 ends in ㄴ → 이; possession (I have time). 2) 예약이 있어요 — 예약 ends in ㄱ → 이; possession (has a reservation). 3) 예약이 없어요 — same noun + particle, reversed meaning; absence. 4) 방이 있어요 — 방 ends in ㅇ → 이; existence (a room exists). 5) 문제가 없어요 — 문제 ends in vowel 에 → 가; absence (no problem). 6) 돈이 있어요 — 돈 ends in ㄴ → 이; possession (has money). Pattern: every time, the particle choice follows the consonant/vowel rule — not the meaning."}]},{kind:"drill",prompt:"지문에서 뭐라고 했어요? · What did the passage say?",sentence:"유나: 오빠, 내일 시간이 ___?",options:[{text:"있어요",ok:!0},{text:"예약하다",ok:!1},{text:"화장실",ok:!1}],explanation:""},{kind:"drill",prompt:"지문에서 뭐라고 했어요? · What did the passage say?",sentence:"준서: 아직 예약이 ___.",options:[{text:"예약하다",ok:!1},{text:"화장실",ok:!1},{text:"없어요",ok:!0}],explanation:""}],canDo:"Say something is missing or you don't have it with 없어요",id:"chapter-04-b7",chapterId:"chapter-04",index:6},{kind:"boss",title:"보스 Boss bite · 다 걸어요",cards:[{kind:"drill",prompt:"You want to say 'I like coffee.' Which is correct?",sentence:null,options:[{text:"커피를 좋아요.",ok:!1},{text:"커피가 좋아요.",ok:!0},{text:"커피는 좋아요.",ok:!1}],explanation:"좋아요 (to be good/to like) uses 이/가, not 을/를. The thing you like is the subject of being-good, so it takes the subject spotlight particle 이/가. 커피를 좋아요 is ungrammatical. 커피는 좋아요 is possible but shifts meaning to a general topic statement ('Coffee, in general, is good') rather than expressing personal preference."},{kind:"drill",prompt:"The hotel receptionist has found your reservation. Which sentence would they say?",sentence:null,options:[{text:"예약이 없어요.",ok:!1},{text:"예약을 있어요.",ok:!1},{text:"예약이 있어요.",ok:!0}],explanation:"예약이 있어요 — reservation exists → lamp ON → correct. 예약이 없어요 is the opposite (no reservation found). 예약을 있어요 is ungrammatical — 있어요 can never take 을/를."},{kind:"drill",prompt:"예약___ 있어요? (Do you have a reservation?)",sentence:null,options:[{text:"이",ok:!0},{text:"을",ok:!1},{text:"에서",ok:!1}],explanation:"있어요 uses 이/가 for the thing that exists or is possessed. 을 would wrongly mark 예약 as an object of an action verb."}],canDo:"Mark the subject or the thing that exists with N이/가",id:"chapter-04-b8",chapterId:"chapter-04",index:7}]},{id:"chapter-05",number:5,title:"N을/를 · 안 + verb",goal:"Attach 을 or 를 correctly after the object in any present-tense sentence",biteCount:9,bites:[{kind:"words",title:"단어 Words 1 · 먹다~",cards:[{kind:"guess",word:{ko:"먹다",romanization:"meokda",en:"to eat",pos:"verb",nuance:"먹다 is used for meals and food. For medicine, Korean often uses 약을 먹어요, literally “eat medicine,” which means “take medicine.”"},sentence:{ko:"점심을 먹어요.",en:"I eat lunch."},target:"먹어",options:["to drink","to study","to eat"],note:"점심 ends in consonant ㅁ → 을; eating is directed at lunch"},{kind:"guess",word:{ko:"마시다",romanization:"masida",en:"to drink",pos:"verb",nuance:"마시다 is for liquids. In casual speech, Koreans often drop particles: 커피 마셔요 is natural."},sentence:{ko:"물을 마셔요.",en:"I drink water."},target:"마셔",options:["to eat","to study","to drink"],note:"물 ends in consonant ㄹ → 을; the drinking action hits 물"},{kind:"guess",word:{ko:"공부하다",romanization:"gongbuhada",en:"to study",pos:"verb",nuance:"공부하다 is noun + 하다, so the short negative is often 공부 안 해요."},sentence:{ko:"한국어를 공부해요.",en:"I study Korean."},target:"공부해",options:["to study","to eat","to drink"],note:"한국어 ends in vowel 어 → 를; can also split: 한국어 공부를 해요"},{kind:"guess",word:{ko:"읽다",romanization:"ikda",en:"to read",pos:"verb",nuance:"읽다 has pronunciation changes, but beginners can first memorize 읽어요 as the practical polite form."},sentence:{ko:"책을 읽어요.",en:"I read a book."},target:"읽어",options:["to read","to eat","to drink"],note:"책 ends in consonant ㄱ → 을; reading is directed at the book"},{kind:"guess",word:{ko:"쓰다",romanization:"sseuda",en:"to write",pos:"verb",nuance:"쓰다 can mean write or use. The object tells the meaning: 이름을 쓰다, 카드를 쓰다."},sentence:{ko:"일기를 써요.",en:"I write a diary."},target:"써",options:["to eat","to write","to drink"],note:"일기 ends in vowel 기 → 를; writing is directed at the diary"},{kind:"guess",word:{ko:"듣다",romanization:"deutda",en:"to listen / to hear",pos:"verb",nuance:"듣다 is ㄷ irregular: 듣다 becomes 들어요 in polite speech."},sentence:{ko:"음악을 들어요.",en:"I listen to music."},target:null,options:["to listen / to hear","to eat","to drink"],note:"음악 ends in consonant ㄱ → 을; listening is directed at the music"},{kind:"payoff",line:{speaker:"지희",ko:"민호 씨, 매일 아침을 먹어요?",en:"Minho, do you eat breakfast every day?"},hl:"먹어"}],canDo:"Mark what the action happens to with N을/를 (밥을, 커피를)",id:"chapter-05-b1",chapterId:"chapter-05",index:0},{kind:"pattern",title:"문법 Grammar · N을/를",cards:[{kind:"hunt",name:"N을/를",sub:"the object particle",lines:[{tokens:[{pre:"밥",mid:"을",post:"",hit:!0},{pre:"먹어요.",mid:"",post:"",hit:!1}],ko:"밥을 먹어요.",en:"I eat (a meal of) rice.",romanization:"bab-eul meogeoyo."},{tokens:[{pre:"친구",mid:"를",post:"",hit:!0},{pre:"만나요.",mid:"",post:"",hit:!1}],ko:"친구를 만나요.",en:"I meet a friend.",romanization:"chingu-reul mannayo."}],rule:{name:"N을/를",rows:[{when:"Noun ends in a consonant (받침)",add:"을",ex:"밥 → 밥을 · 책 → 책을 · 물 → 물을"},{when:"Noun ends in a vowel (no 받침)",add:"를",ex:"우유 → 우유를 · 커피 → 커피를 · 친구 → 친구를"}]},more:{func:"을/를 marks the object of a sentence — the thing the action happens to (what you eat, drink, read, watch). It attaches to the noun that receives the verb's action, so it is the partner of every action verb you learn.",funcLead:"을/를 marks the object of a sentence — the thing the action happens to (what you eat, drink, read, watch).",keyPoint:{label:"Object 을/를 vs subject 이/가",body:"을/를 marks WHAT receives the action (the object); 이/가 marks WHO does it (the subject). In 친구가 밥을 먹어요 (A friend eats), 친구 is the doer → 가, and 밥 is the thing eaten → 을. Don't swap them. In casual speech Koreans often drop 을/를 (밥 먹어요), but learn to add it correctly first — the dropping comes naturally later.",when:"",add:"",ex:""},pronunciation:"밥을 is pronounced [바블]: the final ㅂ links into the following vowel (linking, 연음). Likewise 책을 → [채글], 한국어를 → [한구거를].",pitfall:{wrong:"저는 밥 먹어요 treated as the 'correct, complete' textbook form",right:"저는 밥을 먹어요.",explanation:"English has no object particle, so learners forget 을/를 and treat the bare noun as finished. The neutral, fully-formed sentence keeps the particle; dropping it is a casual-speech shortcut, not the default you should write."}}},{kind:"drill",prompt:"I drink water.",sentence:"물___ 마셔요.",options:[{text:"을",ok:!0},{text:"를",ok:!1}],explanation:"물 ends in ㄹ 받침 (a consonant) → 을, not 를."},{kind:"drill",prompt:"I read a book.",sentence:"책___ 봐요.",options:[{text:"를",ok:!1},{text:"안",ok:!1},{text:"을",ok:!0}],explanation:"책 ends in ㄱ 받침 → 을. 보다 here means 'read / look at'."},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"저는 밥 먹어요 treated as the 'correct, complete' textbook form",ok:!1},{text:"저는 밥을 먹어요.",ok:!0}],explanation:"English has no object particle, so learners forget 을/를 and treat the bare noun as finished. The neutral, fully-formed sentence keeps the particle; dropping it is a casual-speech shortcut, not the default you should write."},{kind:"drill",prompt:"빈칸을 채우세요 · Complete the form — Noun ends in a consonant (받침)",sentence:"밥___",options:[{text:"를",ok:!1},{text:"을",ok:!0}],explanation:"밥 → 밥을 · 책 → 책을 · 물 → 물을"}],canDo:"Mark what the action happens to with N을/를 (밥을, 커피를)",id:"chapter-05-b2",chapterId:"chapter-05",index:1},{kind:"words",title:"단어 Words 2 · 보다~",cards:[{kind:"guess",word:{ko:"보다",romanization:"boda",en:"to watch / to see",pos:"verb",nuance:"보다 covers seeing, watching, and looking at something. Context tells which English verb fits."},sentence:{ko:"영화를 봐요.",en:"I watch a movie."},target:"봐",options:["to eat","to watch / to see","to drink"],note:"영화 ends in vowel 아 → 를; watching is directed at the movie"},{kind:"guess",word:{ko:"운동하다",romanization:"undonghada",en:"to exercise",pos:"verb",nuance:"운동하다 = 한자 運動 (運 'move, transport' + 動 'move') + 하다, literally 'movement-movement,' i.e. to physically exercise. The same noun 운동 also means a sports movement or a social campaign, but with 하다 it's working out. A key feature for learners: Korean builds most sports the same way — noun + 하다 (축구하다 play soccer, 수영하다 swim), though racket sports take 치다 'hit' instead (테니스 치다). The contrast with 놀다 ('play, hang out, have fun') matters: 놀다 is unstructured fun, 운동하다 is purposeful physical activity, so don't say 놀다 when you mean training. Natural collocations: 헬스장에서 운동하다, 건강을 위해 운동하다, 운동 부족. As a 하다 verb the negatives split — 운동 안 해요, 운동 못 해요 — and you can swap in 운동을 안 하다 with the object marker for a touch more emphasis."},sentence:{ko:"매일 운동해요.",en:"I exercise every day."},target:"운동해",options:["to exercise","cooked rice / meal","coffee"],note:"운동하다 has no object here — not everything needs 을/를; negative form: 운동 안 해요"},{kind:"guess",word:{ko:"일하다",romanization:"ilhada",en:"to work",pos:"verb",nuance:"Use 에서 for where an action happens: 회사에서 일해요."},sentence:{ko:"오늘 일 안 해요.",en:"I'm not working today."},target:null,options:["cooked rice / meal","to work","coffee"],note:"Noun+하다 split negative: 일 + 안 + 해요 — the stop sign goes between noun and verb"},{kind:"guess",word:{ko:"밥",romanization:"bap",en:"cooked rice / meal",pos:"noun",nuance:"밥 literally is the bowl of cooked white rice, but by extension it is the default word for 'a meal' — which is why 밥 먹었어요? functions as a real greeting like 'how are you?', not a literal question about rice. Contrast it with 식사(食事), the polite Sino-Korean word for 'a meal': you offer an elder 식사하셨어요?, never the blunt 밥 먹었어요?. The verb is 먹다(eat), and to cook rice you say 밥을 하다 or 밥을 짓다, not 밥을 만들다. The big English-speaker pitfall is hearing 밥 only as 'rice' and missing that 밥 먹자 means 'let's grab a bite', and that to a boss you must upgrade to 식사 to stay polite."},sentence:{ko:"밥을 먹어요?",en:"Are you eating? / Do you eat rice?"},target:"밥",options:["coffee","cooked rice / meal","water"],note:"밥 ends in consonant ㅂ → 을; 밥을 먹다 is the most common eating phrase in Korean"},{kind:"guess",word:{ko:"커피",romanization:"keopi",en:"coffee",pos:"noun",nuance:"In speech, 커피 마셔요 without 를 is also natural, but learn the full frame first."},sentence:{ko:"커피를 마셔요.",en:"I drink coffee."},target:"커피",options:["cooked rice / meal","water","coffee"],note:"커피 ends in vowel 이 → 를; 마시다 is directed at the drink."},{kind:"guess",word:{ko:"물",romanization:"mul",en:"water",pos:"noun",nuance:"물 is essential in restaurants. 물 주세요 is more useful than just knowing “water.”"},sentence:{ko:"물을 많이 마셔요.",en:"I drink a lot of water."},target:"물",options:["water","cooked rice / meal","coffee"],note:"물 ends in consonant ㄹ → 을; 많이 = a lot, modifying the verb"},{kind:"payoff",line:{speaker:"지희",ko:"그래요? 저는 매일 밥을 먹어요. 물을 많이 마셔요.",en:"Really? I eat rice every day. I drink a lot of water."},hl:"밥을"}],canDo:"Say everyday actions in the polite present tense (먹어요, 마셔요)",id:"chapter-05-b3",chapterId:"chapter-05",index:2},{kind:"pattern",title:"문법 Grammar · 안 + verb",cards:[{kind:"hunt",name:"안 + verb",sub:"the short negative",lines:[{tokens:[{pre:"저는",mid:"",post:"",hit:!1},{pre:"밥을",mid:"",post:"",hit:!1},{pre:"",mid:"안",post:"",hit:!0},{pre:"먹어요.",mid:"",post:"",hit:!1}],ko:"저는 밥을 안 먹어요.",en:"I don't eat (the meal).",romanization:"jeoneun bab-eul an meogeoyo."},{tokens:[{pre:"물을",mid:"",post:"",hit:!1},{pre:"",mid:"안",post:"",hit:!0},{pre:"마셔요.",mid:"",post:"",hit:!1}],ko:"물을 안 마셔요.",en:"I don't drink water.",romanization:"mul-eul an masyeoyo."}],rule:{name:"안 + verb",rows:[{when:"Ordinary action verb",add:"안 + verb",ex:"먹어요 → 안 먹어요 · 봐요 → 안 봐요 · 마셔요 → 안 마셔요"},{when:"하다 verb (noun + 하다)",add:"안 goes between the noun and 하다",ex:"공부해요 → 공부 안 해요 · 운동해요 → 운동 안 해요"}]},more:{func:"안 makes a verb negative — it means 'do not / does not'. You put 안 directly in front of the verb to say you don't do the action (안 먹어요 = I don't eat).",funcLead:"안 makes a verb negative — it means 'do not / does not'.",keyPoint:{label:"안 (choose not to) vs 못 (can't) — preview",body:"안 means you simply don't / choose not to do something (안 먹어요 = I don't eat it). 못 means you're unable to even though you might want to (못 먹어요 = I can't eat it). Both go in front of the verb, but the meaning differs: 안 = won't / don't, 못 = can't. You'll practice 못 in its own chapter — for now just remember 안 is the everyday negative.",when:"",add:"",ex:""},pronunciation:"안 + verb does not fuse: the ㄴ of 안 stays crisp and there is no tensing on the verb (안 봐요 = [안봐요], not [안뽜요]). Keep them as two clear beats.",pitfall:{wrong:"오늘은 한국어를 안 공부해요.",right:"오늘은 한국어를 공부 안 해요.",explanation:"English puts 'not' before the whole verb, so learners say 안 공부해요. But 공부하다 is noun(공부) + 하다, and 안 must slip between them: 공부 안 해요. This split only happens with 하다 verbs; ordinary verbs take 안 straight in front (안 먹어요)."}}},{kind:"drill",prompt:"My friend doesn't read books.",sentence:"친구가 책을 ___ 봐요.",options:[{text:"를",ok:!1},{text:"안",ok:!0}],explanation:"안 negates the action 보다, not the object 책을."},{kind:"drill",prompt:"Today I don't study Korean.",sentence:"오늘은 한국어를 공부 ___ 해요.",options:[{text:"안",ok:!0},{text:"을",ok:!1}],explanation:"With a 하다 verb, 안 splits in: 공부 안 해요, NOT 안 공부해요."},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "I don't eat (the meal)."`,tokens:["저는","밥을","안","먹어요."],correct:"저는 밥을 안 먹어요.",explanation:""},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "I don't drink water."`,tokens:["물을","안","마셔요."],correct:"물을 안 마셔요.",explanation:""}],canDo:"Say everyday actions in the polite present tense (먹어요, 마셔요)",id:"chapter-05-b4",chapterId:"chapter-05",index:3},{kind:"words",title:"단어 Words 3 · 책~",cards:[{kind:"guess",word:{ko:"책",romanization:"chaek",en:"book",pos:"noun",nuance:"책 is useful with 읽다, 사다, 있다, and 없다. It also helps beginners practice object marker 을 because 책 ends in a consonant."},sentence:{ko:"책을 읽어요.",en:"I read a book."},target:"책",options:["cooked rice / meal","coffee","book"],note:"책 ends in consonant ㄱ → 을; reading is directed at the book."},{kind:"guess",word:{ko:"음악",romanization:"eumak",en:"music",pos:"noun",nuance:"음악 is Sino-Korean, 音樂 ('sound-pleasure/joy'), and is the general word for music. Its everyday partner verb is 듣다 ('hear/listen'), which is a ㄷ-irregular: before a vowel the ㄷ becomes ㄹ, so 듣 + 어요 → 들어요 and 듣 + 으면 → 들으면 — memorize this because beginners often write the wrong ❌들다. Distinguish 음악 from 노래: 노래 is a specific 'song' you can sing (with words and a tune), while 음악 is music as a whole, including instrumental pieces, so background café music is 음악, not 노래. Two near-verbs differ too — 듣다 is to receive sound, but 틀다 is to switch a track on from a device. The English-speaker pitfall is using 보다 ('watch') because you 'watch a music video' in English; for plain audio say 음악을 들어요, and avoid the false stem 들다 — the dictionary form is 듣다."},sentence:{ko:"음악을 들어요.",en:"I listen to music."},target:"음악",options:["cooked rice / meal","music","coffee"],note:"음악 ends in consonant ㄱ → 을; listening is directed at the music."},{kind:"guess",word:{ko:"영화",romanization:"yeonghwa",en:"movie / film",pos:"noun",nuance:"영화 is Sino-Korean, 映畵 ('project-picture'), literally a projected image, and it is the standard word for a movie/film. It pairs with 보다 ('see/watch'), never 듣다 ('listen'), because film is something you view. A single film is counted with the bound noun 편 (영화 두 편 = two movies), not 개. Don't confuse 영화 with 드라마: 드라마 is a serialized TV series, while 영화 is a self-contained cinema film, so a Korean TV soap is a 드라마, not a 영화. The cinema building is 영화관 (or the loanword 극장). The classic English-speaker pitfall is letting 'a movie' steer you to the generic counter 개 (영화 한 개 sounds wrong) — use 편; and don't calque 'go to a movie' as 영화에 가다, since you say 영화(를) 보러 가다, 'go in order to watch a movie'."},sentence:{ko:"영화를 봐요.",en:"I watch a movie."},target:"영화",options:["cooked rice / meal","coffee","movie / film"],note:"영화 ends in vowel 아 → 를; watching is directed at the movie."},{kind:"guess",word:{ko:"매일",romanization:"maeil",en:"every day",pos:"adverb",nuance:"매일 means 'every day' and is the default word for habits and routines. The 매 is Sino-Korean 每 'each/every', and 일 is 日 'day', so it literally reads 'each-day'; swap the second half for 매주 每週 'every week', 매월/매달 'every month', 매년 每年 'every year'. Crucially 매일 is an adverb of frequency, so unlike clock times it takes NO 에 — say 매일 운동해요, never 매일에. English speakers also confuse it with 하루, which is the counter 'one day / a day' (하루 종일 'all day long'); 매일 is the recurring habit, 하루 is a single day. A near rival is 날마다 'each day', which is interchangeable in meaning but feels a touch more literary/measured, while 매일 is the plain everyday choice. It almost always comes before the verb and pairs happily with 거의, 아침/밤, and the emphatic 매일같이."},sentence:{ko:"매일 커피를 마셔요.",en:"I drink coffee every day."},target:"매일",options:["to eat","to drink","every day"],note:"매일 is a time adverb — it doesn't need a particle; it modifies the entire sentence"},{kind:"guess",word:{ko:"많이",romanization:"mani",en:"a lot / many / much",pos:"adverb",nuance:"많이 is the adverb form of the adjective 많다 ('to be many/much') and is the everyday word for 'a lot/much', sitting right in front of the verb it modifies (많이 먹어요, 많이 자요). Its near-synonym is 너무: 많이 just states a large amount neutrally, while 너무 carries an 'excessive, over the line' feeling, so 많이 매워요 is 'quite spicy' but 너무 매워요 is 'too spicy (uncomfortably)'. With feeling-verbs and adjectives 많이 stretches to mean 'very/badly', as in 많이 아파요 ('it hurts a lot'). The classic English-speaker pitfall is reaching for the adjective 많다 directly before a verb — you must use the adverb 많이 (많이 먹어요, never 많다 먹어요) — and remembering that, like all Korean adverbs, it comes before the verb, not after it."},sentence:{ko:"물을 많이 마셔요.",en:"I drink a lot of water."},target:"많이",options:["a lot / many / much","to eat","to drink"],note:"많이 (adverb) modifies the verb directly — no particle needed on the adverb itself"},{kind:"payoff",line:{speaker:"지희",ko:"민호 씨, 매일 아침을 먹어요?",en:"Minho, do you eat breakfast every day?"},hl:"매일"}],canDo:"Make a verb negative with 안 + verb (안 먹어요)",id:"chapter-05-b5",chapterId:"chapter-05",index:4},{kind:"pattern",title:"문법 Grammar · 자연스럽게 말하기",cards:[{kind:"teach",name:"자연스럽게 말하기",sub:"How Korean actually sounds",rows:[{when:"나는 / 저는 (topic)",add:"전 / 난",ex:`전 학생이에요. ("I'm a student.") — 난 is the same squeeze on 나는, but this app sticks to 저/전.`},{when:"너는 (topic) — read only",add:"넌",ex:`넌 어디 가? ("Where are you going?") — 반말. Read it, don't say it: use 전 + 해요체 instead.`},{when:"것이 / 것을 / 것은",add:"게 / 걸 / 건",ex:`먹을 게 없어요. ("There's nothing to eat.") · 이걸 주세요. ("Give me this one.") · 이건 뭐예요? ("What's this?")`},{when:"무엇을 / 무엇이",add:"뭘 / 뭐가",ex:`뭘 먹을까요? ("What shall we eat?") · 뭐가 맛있어요? ("What's tasty?") — 무엇 shrinks to 뭐 first, then 뭐+를 → 뭘; 뭐가 takes 가 because 뭐 ends in a vowel.`},{when:"것 같아요 (speech only)",add:"거 같아요",ex:`좋은 거 같아요. ("I think it's good.") — but write 좋은 것 같습니다 in an email or a report.`},{when:"이것 / 그것 / 저것",add:"이거 / 그거 / 저거",ex:'이거 주세요. ("This one, please.")'},{when:"-지요",add:"-죠",ex:`맛있죠? ("It's tasty, right?")`}],examples:[{ko:"전 커피를 마셔요.",en:"I drink coffee.",romanization:"jeon keopi-reul masyeoyo.",note:"저는 → 전. The topic marker 는 collapses onto 저. Still 해요체, still polite — 전 is not more casual than 저는."},{ko:"뭘 봐요?",en:"What are you watching?",romanization:"mwol bwayo?",note:"무엇을 → 뭘. In everyday conversation 뭘 (or 뭐) is the norm, even when you're being polite. 무엇을 isn't dead — it's just formal: you'll hear it from news anchors and in set service phrases like 무엇을 도와드릴까요?"}],more:{func:"Korean squeezes its most common words the moment people speak, and those short forms are what fill KakaoTalk, subtitles, and everyday conversation. 저는 becomes 전, 것이 becomes 게, 무엇을 becomes 뭘. The meaning stays the same and so does the respect level — what shifts is how formal you sound, so these belong to speech rather than to a business email. You have just learned 은/는 and 을/를, so you can now see exactly what is being squeezed together.",funcLead:"Korean squeezes its most common words the moment people speak, and those short forms are what fill KakaoTalk, subtitles, and everyday conversation.",keyPoint:{label:"Shorter spelling, same politeness — but not the same formality",body:"A contraction changes the spelling, not the meaning and not the level of respect: 전 학생이에요 and 저는 학생이에요 are equally polite, and 이거 주세요 is no ruder than 이것을 주세요. What it does change is how FORMAL you sound. Short forms are speech; the full forms are for writing and for formal rooms — a job interview, a presentation, a business email, an exam. Say 거 같아요 to a friend or a coworker, but write 것 같습니다 in that email. And one warning: none of this rescues 넌. 너 is a 반말 word by itself, so 넌 stays 반말 even with -요 on the end. Politeness lives in the ending (-요, -습니다) and in which words you pick — never in how many syllables they have.",when:"",add:"",ex:""},pronunciation:"These short forms are the spoken sound written down — but watch the actual route. In speech 것 becomes 거, and only then do the particles fuse onto it: 거 + 이 → 게, 거 + 를 → 걸, 거 + 는 → 건. (Don't be fooled by the full forms: 것을 is pronounced [거슬], not [거를].) 뭘 takes the same route: 무엇 shrinks to 뭐 [무어 → 뭐], and then 뭐 + 를 → 뭘. And -지요 squeezes into one syllable as -죠, which is pronounced [조] — there is no 'y' glide in it, and after a 받침 it tightens: 춥죠 = [춥쪼].",pitfall:{wrong:"Avoiding 전 / 거 같아요 / 이거 because they look like slang or 반말",right:"전 학생이에요. · 좋은 거 같아요. · 이거 주세요.",explanation:`English contractions ("I'm", "gonna") really do drop the register, so learners assume Korean works the same way and stick to 저는 / 것 같아요 / 이것 to stay polite. It backfires: in conversation the full forms sound like a textbook being read aloud. Politeness in Korean lives in the ending (-요, -습니다), not in the length of the word. What shortness does signal is informality — so let 전 and 거 같아요 do the talking, and keep 저는 and 것 같습니다 for interviews, emails, and essays.`}}},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "I drink coffee."',tokens:["전","커피를","마셔요."],correct:"전 커피를 마셔요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"전 학생이에요. · 좋은 거 같아요. · 이거 주세요.",ok:!0},{text:"Avoiding 전 / 거 같아요 / 이거 because they look like slang or 반말",ok:!1}],explanation:`English contractions ("I'm", "gonna") really do drop the register, so learners assume Korean works the same way and stick to 저는 / 것 같아요 / 이것 to stay polite. It backfires: in conversation the full forms sound like a textbook being read aloud. Politeness in Korean lives in the ending (-요, -습니다), not in the length of the word. What shortness does signal is informality — so let 전 and 거 같아요 do the talking, and keep 저는 and 것 같습니다 for interviews, emails, and essays.`}],canDo:"Make a verb negative with 안 + verb (안 먹어요)",id:"chapter-05-b6",chapterId:"chapter-05",index:5},{kind:"dialogue",title:"대화 Dialogue · 진짜 한국어",cards:[{kind:"chat",setting:"Jihee (지희) and her coworker Minho (민호) are chatting over lunch about their daily habits",lines:[{speaker:"지희",ko:"민호 씨, 매일 아침을 먹어요?",en:"Minho, do you eat breakfast every day?",romanization:"Minho ssi, maeil achimeul meogeoyo?"},{speaker:"민호",ko:"아니요, 아침을 안 먹어요. 바빠요.",en:"No, I don't eat breakfast. I'm busy.",romanization:"aniyo, achimeul an meogeoyo. bappayo."},{speaker:"지희",ko:"그래요? 저는 매일 밥을 먹어요. 물을 많이 마셔요.",en:"Really? I eat rice every day. I drink a lot of water.",romanization:"Geuraeyo? Jeoneun maeil babeul meogeoyo. Mureul mani masyeoyo."},{speaker:"민호",ko:"커피를 마셔요. 그게 제 아침이에요.",en:"I drink coffee. That's my breakfast.",romanization:"Keopireul masyeoyo. Geuge je achimieyo."},{speaker:"지희",ko:"하하, 한국어를 공부해요?",en:"Haha, do you study Korean?",romanization:"Haha, hangugeoreul gongbuhaeyo?"},{speaker:"민호",ko:"네, 매일 한국어를 공부해요. 그런데 책을 안 읽어요.",en:"Yes, I study Korean every day. But I don't read books.",romanization:"Ne, maeil hangugeoreul gongbuhaeyo. Geureonde chaegeul an ilgeoyo."},{speaker:"지희",ko:"저는 책을 읽어요. 그리고 음악을 들어요.",en:"I read books. And I listen to music.",romanization:"Jeoneun chaegeul ilgeoyo. Geurigo eumageul deureoyo."},{speaker:"민호",ko:"좋아요. 오늘은 영화를 안 봐요. 책을 읽어요.",en:"Good. Today I won't watch a movie. I'll read a book.",romanization:"Joayo. Oneureun yeonghwareul an bwayo. Chaegeul ilgeoyo."}]},{kind:"order",prompt:"Build: 'I drink coffee every morning.'",tokens:["매일 아침","커피를 마셔요"],correct:"매일 아침 커피를 마셔요",explanation:"The time phrase comes before the object and verb. 커피 is what you drink, so 커피를 stays right before 마셔요."},{kind:"drill",prompt:"누가 한 말일까요? · Who said this?",sentence:"네, 매일 한국어를 공부해요. 그런데 책을 안 읽어요.",options:[{text:"민호",ok:!0},{text:"지희",ok:!1}],explanation:"Yes, I study Korean every day. But I don't read books."},{kind:"drill",prompt:'무엇이 들어갈까요? · "Minho, do you eat breakfast every day?"',sentence:"민호 씨, ___ 아침을 먹어요?",options:[{text:"먹다",ok:!1},{text:"마시다",ok:!1},{text:"매일",ok:!0}],explanation:""}],canDo:"Mark what the action happens to with N을/를 (밥을, 커피를)",id:"chapter-05-b7",chapterId:"chapter-05",index:6},{kind:"reading",title:"읽기 Reading · 수빈의 하루 일과 (Subin's Daily Routine)",cards:[{kind:"read",title:"수빈의 하루 일과 (Subin's Daily Routine)",chunks:["저는 매일 아침 밥을 먹어요. 커피를 마셔요. 회사에서 이메일을 써요. 보고서를 읽어요. 점심에는 동료들과 밥을 먹어요.","퇴근 후에는 음악을 들어요. 한국어를 공부해요. 드라마를 봐요. 주말에는 운동 안 해요. 그냥 책을 읽어요."],translation:"Every morning I eat a meal. I drink coffee. At work I write emails. I read reports. At lunch I eat with my coworkers. After work I listen to music. I study Korean. I watch dramas. On weekends I don't exercise. I just read books.",qas:[{q:"What two things does Subin do in the morning?",a:"밥을 먹어요 (eats a meal) and 커피를 마셔요 (drinks coffee)."},{q:"What two things does Subin do after work?",a:"음악을 들어요 (listens to music) and 한국어를 공부해요 (studies Korean)"},{q:"Find all the 을/를 in the text. For each one, explain why 을 or 를 is used — not the other form.",a:"밥을 (ㅂ consonant ending → 을), 커피를 (이 vowel ending → 를), 이메일을 (ㄹ consonant ending → 을), 보고서를 (어 vowel ending → 를), 밥을 (again, ㅂ → 을), 음악을 (ㄱ consonant ending → 을), 한국어를 (어 vowel ending → 를), 드라마를 (아 vowel ending → 를), 책을 (ㄱ consonant ending → 을). The rule: consonant-ending nouns take 을, vowel-ending nouns take 를."}]},{kind:"drill",prompt:"지문에서 뭐라고 했어요? · What did the passage say?",sentence:"저는 ___ 아침 밥을 먹어요.",options:[{text:"먹다",ok:!1},{text:"매일",ok:!0},{text:"마시다",ok:!1}],explanation:""},{kind:"drill",prompt:"지문에서 뭐라고 했어요? · What did the passage say?",sentence:"___를 마셔요.",options:[{text:"물",ok:!1},{text:"영화",ok:!1},{text:"커피",ok:!0}],explanation:""}],canDo:"Say everyday actions in the polite present tense (먹어요, 마셔요)",id:"chapter-05-b8",chapterId:"chapter-05",index:7},{kind:"boss",title:"보스 Boss bite · 다 걸어요",cards:[{kind:"drill",prompt:"Which sentence correctly says 'I don't study' using the 안 negative?",sentence:null,options:[{text:"안 공부해요.",ok:!1},{text:"공부 안 해요.",ok:!0},{text:"공부를 않아요.",ok:!1},{text:"안 공부를 해요.",ok:!1}],explanation:"공부 안 해요 is correct — noun + stop-sign + 해요. '안 공부해요' is wrong because 안 can't go before a noun-verb compound. '공부를 않아요' is missing the -지 needed for the long negative form (공부를 하지 않아요). '안 공부를 해요' mixes up the word order in an unnatural way."},{kind:"drill",prompt:"Your friend says '책을 읽어요.' What is the role of 을 in this sentence?",sentence:null,options:[{text:"It marks 책 as the subject doing the reading.",ok:!1},{text:"It marks 책 as the object receiving the action of reading.",ok:!0},{text:"It marks 책 as a topic being discussed.",ok:!1},{text:"It is a verb ending attached to 책.",ok:!1}],explanation:"을/를 is the object marker — it marks WHAT gets acted upon. 책 is what is being read. Subject markers (이/가) mark who does the action; topic markers (은/는) set what we're talking about. 을/를 is specifically for the thing that receives the verb's action."},{kind:"drill",prompt:"책___ 읽어요. (I read a book.)",sentence:null,options:[{text:"을",ok:!0},{text:"이",ok:!1},{text:"에",ok:!1}],explanation:"읽다 is an action, and 책 is what you read, so it takes the object marker 을. 이 would mark 책 as a subject, not the thing being read."}],canDo:"Make a verb negative with 안 + verb (안 먹어요)",id:"chapter-05-b9",chapterId:"chapter-05",index:8}]},{id:"chapter-06",number:6,title:"N에 · N에서",goal:"Use 에 correctly for destinations and static locations",biteCount:8,bites:[{kind:"words",title:"단어 Words 1 · 학교~",cards:[{kind:"guess",word:{ko:"학교",romanization:"hakgyo",en:"school",pos:"noun",nuance:"학교 is one of the clearest words for practicing 에 vs 에서."},sentence:{ko:"학교에서 한국어를 공부해요.",en:"I study Korean at school."},target:"학교",options:["library","café","school"],note:"에서 — studying is an action"},{kind:"guess",word:{ko:"도서관",romanization:"doseogwan",en:"library",pos:"noun",nuance:"도서관 is Sino-Korean 圖書館, literally 'pictures-books-building' (圖 picture + 書 writing/book + 館 hall), a public place to read, study, and borrow books where quiet is expected. The sharp contrast learners must hold is 도서관 vs 서점: a 도서관 is a LIBRARY where you borrow (빌리다) for free, while a 서점 is a BOOKSTORE where you buy (사다) — English 'library' and Spanish/French false friends like 'librería' push learners to mix these up. Note also 도서관 (the building) vs 도서 (books as items/collection). Register is neutral. Natural collocations: 도서관에서 공부하다, 책을 빌리다/반납하다, 도서관에 자리가 없다. The English-speaker pitfall, beyond the library/bookstore mix-up, is the particle split: study or read AT a library is 에서 (도서관에서), but going TO it is 에 (도서관에 가다)."},sentence:{ko:"도서관에서 책을 읽어요.",en:"I read books at the library."},target:"도서관",options:["school","library","café"],note:"에서 — reading is an active action"},{kind:"guess",word:{ko:"카페",romanization:"kape",en:"café",pos:"noun",nuance:"카페 is a loanword (from French/English 'café') meaning a coffee shop — but in Korea it is as much a social and study space as a place to drink coffee; people sit for hours to chat, work on laptops, or go on a 카페 투어 of photogenic spots. The key contrast learners blur is 카페 vs 커피: 카페 is the *place*, 커피 is the *drink*, so '커피 마시러 카페에 가요' (go to the cafe to drink coffee). It overlaps with 커피숍 and the older 다방 (a dated tea-room), but 카페 is the modern default. Being borrowed, it has no hanja. The English-speaker pitfall is exactly that 카페/커피 mix-up, plus the particles — 카페에 가요 for going there but 카페에서 공부해요 for doing something there — and remember the purpose marker for 'to go drink coffee' is the verb stem + ~(으)러: 커피 마시러 카페에 가요."},sentence:{ko:"카페에서 친구를 기다려요.",en:"I wait for my friend at the café."},target:"카페",options:["café","school","library"],note:"에서 — waiting is an active state/action"},{kind:"guess",word:{ko:"회사",romanization:"hoesa",en:"company / office",pos:"noun",nuance:"회사 often means workplace in daily conversation, not only the company as an organization."},sentence:{ko:"회사에서 8시간 일해요.",en:"I work at the office for 8 hours."},target:"회사",options:["company / office","school","library"],note:"에서 — working is an active action"},{kind:"guess",word:{ko:"식당",romanization:"sikdang",en:"restaurant",pos:"noun",nuance:"식당 is 食堂 — 食 'eat' + 堂 'hall' — an 'eating hall', i.e. an ordinary, everyday place to have a meal: a neighborhood eatery, a noodle shop, or a 구내식당(cafeteria). The register contrast is 레스토랑, the loanword reserved for fancier, often Western, sit-down dining; you'd call a humble 백반집 a 식당, never a 레스토랑, and a candlelit Italian place a 레스토랑, not a plain 식당. The crucial grammar point is particle choice: use 에서 for an action done there (식당에서 먹어요 'eat AT the restaurant') but 에 for it as a destination (식당에 가요 'go TO the restaurant'). The English-speaker pitfall is exactly this 에/에서 split, since English 'at/to' don't map one-to-one; another is reaching for 레스토랑 as the default word for any restaurant when 식당 is the everyday term."},sentence:{ko:"식당에서 비빔밥을 먹어요.",en:"I eat bibimbap at the restaurant."},target:"식당",options:["restaurant","school","library"],note:"에서 — eating is an active action"},{kind:"guess",word:{ko:"집",romanization:"jip",en:"home / house",pos:"noun",nuance:"집 can mean home or house. 집에 often means “home” in movement/location sentences."},sentence:{ko:"집에서 쉬고 싶어요.",en:"I want to rest at home."},target:"집",options:["school","home / house","library"],note:"에서 — resting is an action at a location"},{kind:"guess",word:{ko:"공원",romanization:"gongwon",en:"park",pos:"noun",nuance:"공원 (公園, 'public-garden', 公 'public' + 園 'garden') is a public green space for walking, exercise, picnics and rest — found in every Korean neighborhood, from small 근린공원 to huge ones like 한강공원 or 올림픽공원. The near-synonym to distinguish is 정원 (庭園), a private *garden* attached to a home or building: 공원 is open to everyone, 정원 is someone's own landscaped yard, so don't call a public park a 정원. It is also not 놀이공원 (an amusement park with rides) — that compound needs 놀이. The collocations are scenic: 공원에서 산책하다 (stroll), 운동하다 (exercise), 돗자리를 깔다 (spread a picnic mat). The English-speaker pitfall is again 공원에 가요 (destination, 에) versus 공원에서 산책해요 (action location, 에서); and the static verb 앉다 takes 에 — 벤치에 앉다 'sit on the bench', not 에서."},sentence:{ko:"공원에서 운동해요.",en:"I exercise at the park."},target:"공원",options:["park","school","library"],note:"에서 — exercising is an action"},{kind:"payoff",line:{speaker:"소라",ko:"저는 회사에 있어요. 왜요?",en:"I'm at the office. Why?"},hl:"회사"}],canDo:"Mark a destination or time with N에 (학교에 가요)",id:"chapter-06-b1",chapterId:"chapter-06",index:0},{kind:"pattern",title:"문법 Grammar · N에",cards:[{kind:"hunt",name:"N에",sub:"where you go, when it happens, where it is",lines:[{tokens:[{pre:"저는",mid:"",post:"",hit:!1},{pre:"학교",mid:"에",post:"",hit:!0},{pre:"가요.",mid:"",post:"",hit:!1}],ko:"저는 학교에 가요.",en:"I go to school.",romanization:"jeo-neun hak-gyo-e ga-yo."},{tokens:[{pre:"친구가",mid:"",post:"",hit:!1},{pre:"집",mid:"에",post:"",hit:!0},{pre:"있어요.",mid:"",post:"",hit:!1}],ko:"친구가 집에 있어요.",en:"My friend is at home.",romanization:"chin-gu-ga ji-be i-sseo-yo."}],rule:{name:"N에",rows:[{when:"Destination (with 가다/오다)",add:"에 가다 / 에 오다",ex:"학교 → 학교에 가요 · 집 → 집에 와요"},{when:"Where something is (with 있다/없다)",add:"에 있다 / 에 없다",ex:"집 → 집에 있어요 · 학교 → 학교에 없어요"},{when:"A point in time (clock time, day, date)",add:"에",ex:"세 시 → 세 시에 · 월요일 → 월요일에"},{when:"Time words that take NO 에",add:"(no 에)",ex:"오늘 · 어제 · 내일 · 지금 (오늘에 ✗)"}]},more:{func:'에 attaches to a noun to mark a destination (with 가다/오다), a point in time ("at/on"), or the place where someone or something simply exists (with 있다/없다). One way to keep it straight: 에 is for going there, being there, or when — never for an action you actually do at a place.',funcLead:'에 attaches to a noun to mark a destination (with 가다/오다), a point in time ("at/on"), or the place where someone or something simply exists (with 있다/없다).',keyPoint:{label:"에 vs 에서 — being there vs doing there",body:`Use 에 for where something IS or where you're GOING (있다/없다/가다/오다): 집에 있어요 (I'm at home), 학교에 가요 (I go to school). Use 에서 for where you DO something (먹다/공부하다/일하다 …): 집에서 밥을 먹어요 (I eat at home). Quick test: 있다/없다/가다/오다 → 에; any "doing" verb → 에서. The 에서 note below drills the full contrast.`},pronunciation:"After a 받침 noun, 에 slides onto the final consonant (연음): 집에 → [지베]. After a vowel there's nothing to link, so 학교에 stays [학꾜에] (and note 학교 itself is [학꾜]).",pitfall:{wrong:"오늘에 학교에 가요.",right:"오늘 학교에 가요.",explanation:'Because of "at three / on Monday," learners stick 에 onto every time word. But 에 only goes on clock times, days, and dates (세 시에, 월요일에) — the words 오늘 (today), 어제 (yesterday), 내일 (tomorrow), and 지금 (now) never take it. Just memorize that short list.'}}},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "I go to school." (저는 시작 · Start with 저는.)',tokens:["저는","학교에","가요."],correct:"저는 학교에 가요.",explanation:""},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "My friend is at home." (친구가 시작 · Start with 친구가.)',tokens:["친구가","집에","있어요."],correct:"친구가 집에 있어요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"오늘에 학교에 가요.",ok:!1},{text:"오늘 학교에 가요.",ok:!0}],explanation:'Because of "at three / on Monday," learners stick 에 onto every time word. But 에 only goes on clock times, days, and dates (세 시에, 월요일에) — the words 오늘 (today), 어제 (yesterday), 내일 (tomorrow), and 지금 (now) never take it. Just memorize that short list.'},{kind:"drill",prompt:"빈칸을 채우세요 · Complete the form — Destination (with 가다/오다)",sentence:"학교___",options:[{text:"에 있어요",ok:!1},{text:"에 가요",ok:!0}],explanation:"학교 → 학교에 가요 · 집 → 집에 와요"}],canDo:"Mark a destination or time with N에 (학교에 가요)",id:"chapter-06-b2",chapterId:"chapter-06",index:1},{kind:"words",title:"단어 Words 2 · 가다~",cards:[{kind:"guess",word:{ko:"가다",romanization:"gada",en:"to go",pos:"verb",nuance:"Use 에 for destination: 학교에 가요, 집에 가요. Do not use 에서 for destination."},sentence:{ko:"내일 학교에 가요.",en:"I go to school tomorrow."},target:"가요",options:["to come","to go","to be / to exist / to have"],note:"가다 = movement → destination takes 에, never 에서"},{kind:"guess",word:{ko:"오다",romanization:"oda",en:"to come",pos:"verb",nuance:"오다 is from the speaker’s point of view. If someone moves toward you or your place, 오다 is usually right."},sentence:{ko:"우리 집에 와요.",en:"Come to my place."},target:"와",options:["to come","to go","to be / to exist / to have"],note:"오다 = movement → destination takes 에"},{kind:"guess",word:{ko:"있다",romanization:"itda",en:"to be / to exist / to have",pos:"verb"},sentence:{ko:"지금 카페에 있어요.",en:"I'm at the café right now."},target:"있어",options:["to go","to be / to exist / to have","to come"],note:"있다 = static existence → ALWAYS takes 에, never 에서"},{kind:"guess",word:{ko:"공부하다",romanization:"gongbuhada",en:"to study",pos:"verb",nuance:"공부하다 is noun + 하다, so the short negative is often 공부 안 해요."},sentence:{ko:"도서관에서 공부해요.",en:"I study at the library."},target:"공부해",options:["to study","to go","to come"],note:"Active verb → location takes 에서"},{kind:"guess",word:{ko:"일하다",romanization:"ilhada",en:"to work",pos:"verb",nuance:"Use 에서 for where an action happens: 회사에서 일해요."},sentence:{ko:"카페에서 아르바이트해요.",en:"I do a part-time job at a café."},target:null,options:["to go","to work","to come"],note:"Action verb → 에서"},{kind:"guess",word:{ko:"만나다",romanization:"mannada",en:"to meet",pos:"verb",nuance:"만나다 takes a person as the object: 친구를 만나요, 선생님을 만나요."},sentence:{ko:"어디에서 만나요?",en:"Where shall we meet?"},target:"만나",options:["to go","to meet","to come"],note:"Meeting is an action → 에서"},{kind:"guess",word:{ko:"기다리다",romanization:"gidarida",en:"to wait",pos:"verb",nuance:"기다려 주세요 is one of the most useful service and classroom requests."},sentence:{ko:"카페에서 기다릴게요.",en:"I'll wait at the café."},target:"기다릴",options:["to go","to come","to wait"],note:"Waiting = active state → 에서"},{kind:"payoff",line:{speaker:"지훈",ko:"소라 씨, 지금 어디에 있어요?",en:"Sora, where are you right now?"},hl:"있어"}],canDo:"Mark where an action happens with N에서 (집에서 일해요)",id:"chapter-06-b3",chapterId:"chapter-06",index:2},{kind:"pattern",title:"문법 Grammar · N에서",cards:[{kind:"hunt",name:"N에서",sub:'where you do something, and "from"',lines:[{tokens:[{pre:"집",mid:"에서",post:"",hit:!0},{pre:"밥을",mid:"",post:"",hit:!1},{pre:"먹어요.",mid:"",post:"",hit:!1}],ko:"집에서 밥을 먹어요.",en:"I eat at home.",romanization:"ji-be-seo ba-beul meo-geo-yo."},{tokens:[{pre:"학교",mid:"에서",post:"",hit:!0},{pre:"한국어를",mid:"",post:"",hit:!1},{pre:"공부해요.",mid:"",post:"",hit:!1}],ko:"학교에서 한국어를 공부해요.",en:"I study Korean at school.",romanization:"hak-gyo-e-seo han-gu-geo-reul gong-bu-hae-yo."}],rule:{name:"N에서",rows:[{when:'Where an action happens (with "doing" verbs)',add:"에서",ex:"집 → 집에서 먹어요 · 학교 → 학교에서 공부해요"},{when:'Starting point: "from" (with 오다)',add:"에서",ex:"한국 → 한국에서 왔어요 · 집 → 집에서 나와요"},{when:"Spoken short form (어디/여기/거기 + 에서)",add:"서",ex:"어디에서 → 어디서 · 여기에서 → 여기서"},{when:"Same form after 받침 or vowel",add:"에서",ex:"집 → 집에서 · 학교 → 학교에서"}]},more:{func:`에서 attaches to a place noun to mark where an action happens ("at/in"): 집에서 밥을 먹어요 (I eat at home). The same 에서 also marks a starting point — where something comes "from": 한국에서 왔어요 (I'm from Korea). Same particle, two jobs: where you do something, and where it starts from.`,funcLead:'에서 attaches to a place noun to mark where an action happens ("at/in"): 집에서 밥을 먹어요 (I eat at home).',keyPoint:{label:"에서 vs 에 — the action test",body:`Both sit on a place noun, but the verb decides which. 에서 + a "doing" verb = where you DO something: 도서관에서 책을 읽어요 (I read at the library). 에 + 있다/없다/가다/오다 = where you ARE or GO: 도서관에 있어요 (I'm at the library), 도서관에 가요 (I go to the library). Lock in the pair: 학교에 가요 (go to school) vs 학교에서 공부해요 (study at school).`},pronunciation:"After a 받침 noun, 에서 slides onto the final consonant (연음): 집에서 → [지베서], 한국에서 → [한구게서]. After a vowel there's nothing to link, so 학교에서 stays [학꾜에서].",pitfall:{wrong:"학교에 한국어를 공부해요.",right:"학교에서 한국어를 공부해요.",explanation:`English uses one word, "at," for both "I'm at school" and "I study at school," so learners grab 에 for both. Korean splits them: 에 is only for existence and destination (있다/없다/가다/오다), while anything you DO at a place needs 에서. If there's a real verb of doing — eating, studying, meeting, watching — use 에서.`}}},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "I eat at home." (집에서 시작 · Start with 집에서.)',tokens:["집에서","밥을","먹어요."],correct:"집에서 밥을 먹어요.",explanation:""},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "I study Korean at school." (학교에서 시작 · Start with 학교에서.)',tokens:["학교에서","한국어를","공부해요."],correct:"학교에서 한국어를 공부해요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"학교에 한국어를 공부해요.",ok:!1},{text:"학교에서 한국어를 공부해요.",ok:!0}],explanation:`English uses one word, "at," for both "I'm at school" and "I study at school," so learners grab 에 for both. Korean splits them: 에 is only for existence and destination (있다/없다/가다/오다), while anything you DO at a place needs 에서. If there's a real verb of doing — eating, studying, meeting, watching — use 에서.`},{kind:"drill",prompt:'빈칸을 채우세요 · Complete the form — Where an action happens (with "doing" verbs)',sentence:"집___",options:[{text:"에서 왔어요",ok:!1},{text:"에서 먹어요",ok:!0}],explanation:"집 → 집에서 먹어요 · 학교 → 학교에서 공부해요"}],canDo:"Mark where an action happens with N에서 (집에서 일해요)",id:"chapter-06-b4",chapterId:"chapter-06",index:3},{kind:"words",title:"단어 Words 3 · 먹다~",cards:[{kind:"guess",word:{ko:"먹다",romanization:"meokda",en:"to eat",pos:"verb",nuance:"먹다 is used for meals and food. For medicine, Korean often uses 약을 먹어요, literally “eat medicine,” which means “take medicine.”"},sentence:{ko:"식당에서 같이 먹어요.",en:"Let's eat together at the restaurant."},target:"먹어",options:["to go","to come","to eat"],note:"Eating is an action → 에서"},{kind:"guess",word:{ko:"시간",romanization:"sigan",en:"time",pos:"noun",nuance:"시간 works with 있어요/없어요 and is essential for scheduling."},sentence:{ko:"몇 시에 만나요?",en:"What time shall we meet?"},target:null,options:["time","school","library"],note:"Clock time takes 에 when you mark when something happens"},{kind:"guess",word:{ko:"아침",romanization:"achim",en:"morning",pos:"noun",nuance:"아침 is a native Korean word that does double duty: the early part of the day (roughly sunrise to mid-morning) and the breakfast meal — the same way English 'morning' differs from the meal but Korean merges the breakfast sense into the time word. The grammar disambiguates: with 에 (아침에) it's the time, with 을 (아침을 먹다) it's the food. Contrast 아침 vs 오전: 아침 is the felt, lived early morning, while 오전 午前 is the neutral clock-AM you put on timetables — so 아침에 일어나요 (waking life) but 오전 9시 회의 (a scheduled item). Habitual partners: 아침에 일어나다/운동하다, 아침을 먹다/거르다 ('skip breakfast'), 아침 일찍, 매일 아침. The big English-speaker pitfall is using 오전 for the breakfast meal — 오전 is only the clock period and can never name food, so 'eat breakfast' must be 아침을 먹다, never 오전을 먹다. Also don't force 에 onto the meal sense: you eat 아침을, you don't 'eat at morning'."},sentence:{ko:"아침에 학교에 가요.",en:"I go to school in the morning."},target:"아침",options:["morning","school","library"],note:"아침에 sets the time; 학교에 marks the destination"},{kind:"guess",word:{ko:"오후",romanization:"ohu",en:"afternoon / PM",pos:"noun",nuance:"오후 is the Sino-Korean PM label, literally 午後 'after noon' (午 noon, 後 after), the exact counterpart of 오전 午前. It covers every PM hour from 12:00 until evening, where it hands off to 저녁. The contrast to watch is 오후 vs 저녁: 오후 is the neutral clock-PM you write on schedules (오후 3시 회의), while 저녁 is the lived early-evening AND the dinner meal; so a 6 p.m. plan can be 오후 6시 on a timetable but 저녁 when you talk about eating. 오후 collocates with clock times (오후 3시), 수업/회의/근무, and the fixed 오후 늦게 'late in the afternoon'. The number-one English-speaker pitfall is order: 'PM' follows the number in English but the period LEADS in Korean — say 오후 5시, never 5시 오후. A second trap is treating 오후 as a greeting-time word like 'good afternoon'; Korean has no clock-based greeting, so you still say 안녕하세요, not anything built on 오후."},sentence:{ko:"오후에 도서관에서 공부해요.",en:"I study at the library in the afternoon."},target:"오후",options:["school","afternoon / PM","library"],note:"오후에 marks time; 도서관에서 marks the action place"},{kind:"guess",word:{ko:"저녁",romanization:"jeonyeok",en:"evening",pos:"noun",nuance:"저녁 is a native Korean word covering the early-night period AND the dinner meal, mirroring 아침/점심: 저녁을 먹다 is the food, 저녁에 is the time. The fine line is 저녁 vs 밤: 저녁 is the social early evening — dusk through dinner, when people are still out — whereas 밤 is true late night when it's dark and quiet; so a 7 p.m. dinner is 저녁, but 11 p.m. is 밤. 저녁 also contrasts with the clock label 오후, which ends as 저녁 begins. Habitual partners: 저녁을 먹다, 저녁 식사, 저녁 약속, 저녁 메뉴, 저녁에 만나다. The main English-speaker pitfall is using 밤 for the dinner meal because 'night' feels close — but 'eat dinner' is 저녁을 먹다, never 밤을 먹다 (밤 can't name a meal, and 밤 also happens to mean 'chestnut'). A second trap: don't mark the dinner-meal with 에; you eat 저녁을, while 저녁에 means 'in the evening (do something)'."},sentence:{ko:"저녁에 집에 와요.",en:"I come home in the evening."},target:"저녁",options:["evening","school","library"],note:"저녁에 marks time; 집에 marks the destination of 오다"},{kind:"guess",word:{ko:"병원",romanization:"byeongwon",en:"hospital / clinic",pos:"noun",nuance:"병원 can mean hospital or clinic in everyday Korean."},sentence:{ko:"병원에 가요.",en:"I go to the hospital."},target:"병원",options:["school","hospital / clinic","library"],note:"가다 is movement, so 병원 takes 에 as the destination"},{kind:"payoff",line:{speaker:"지훈",ko:"점심 같이 먹어요! 어디에서 먹을까요?",en:"Let's have lunch together! Where should we eat?"},hl:"먹어"}],canDo:"Keep 에 and 에서 apart by going there vs doing there",id:"chapter-06-b5",chapterId:"chapter-06",index:4},{kind:"dialogue",title:"대화 Dialogue · 진짜 한국어",cards:[{kind:"chat",setting:"Jihoon texts his coworker Sora to plan their lunch break",lines:[{speaker:"지훈",ko:"소라 씨, 지금 어디에 있어요?",en:"Sora, where are you right now?",romanization:"Sora ssi, jigeum eodie isseoyo?"},{speaker:"소라",ko:"저는 회사에 있어요. 왜요?",en:"I'm at the office. Why?",romanization:"Jeoneun hoesae isseoyo. waeyo?"},{speaker:"지훈",ko:"점심 같이 먹어요! 어디에서 먹을까요?",en:"Let's have lunch together! Where should we eat?",romanization:"Jeomsim gachi meogeoyo! Eodieseo meogeulkkayo?"},{speaker:"소라",ko:"회사 근처 식당에서 먹어요. 거기 음식이 맛있어요.",en:"Let's eat at the restaurant near the office. The food there is good.",romanization:"Hoesa geuncheo sikdangeseo meogeoyo. Geogi eumsigi massisseoyo."},{speaker:"지훈",ko:"좋아요! 몇 시에 가요?",en:"Great! What time do we go?",romanization:"Joayo! Myeot sie gayo?"},{speaker:"소라",ko:"12시에 식당에 가요.",en:"We go to the restaurant at 12.",romanization:"Yeoldu sie sikdange gayo."},{speaker:"지훈",ko:"저는 지금 카페에서 일해요. 12시에 식당 앞에서 만나요.",en:"I'm working at a café right now. Let's meet in front of the restaurant at 12.",romanization:"Jeoneun jigeum kapeeseo ilhaeyo. Yeoldu sie sikdang apeseo mannayo."},{speaker:"소라",ko:"알겠어요! 그럼 12시에 봐요.",en:"Got it! See you at twelve then.",romanization:"Algesseoyo! Geureom yeoldu sie bwayo."}]},{kind:"order",prompt:"Build: 'I go to school.'",tokens:["학교에","가요"],correct:"학교에 가요",explanation:"가요 is movement toward a destination, so the place takes 에. 에서 would wrongly make 학교 the action place."},{kind:"drill",prompt:"누가 한 말일까요? · Who said this?",sentence:"저는 지금 카페에서 일해요. 12시에 식당 앞에서 만나요.",options:[{text:"소라",ok:!1},{text:"지훈",ok:!0}],explanation:"I'm working at a café right now. Let's meet in front of the restaurant at 12."},{kind:"drill",prompt:`무엇이 들어갈까요? · "I'm at the office. Why?"`,sentence:"저는 ___에 있어요. 왜요?",options:[{text:"학교",ok:!1},{text:"도서관",ok:!1},{text:"회사",ok:!0}],explanation:""}],canDo:"Mark a destination or time with N에 (학교에 가요)",id:"chapter-06-b6",chapterId:"chapter-06",index:5},{kind:"reading",title:"읽기 Reading · 수진의 하루 (Sujin's Day)",cards:[{kind:"read",title:"수진의 하루 (Sujin's Day)",chunks:["오늘 아침 7시에 일어나요. 그리고 집에서 아침을 먹어요. 9시에 학교에 가요. 학교에서 한국어를 공부해요.","점심에 학교 식당에서 친구를 만나요. 오후에 도서관에서 숙제를 해요. 저녁 6시에 집에 와요. 집에서 쉬어요."],translation:"This morning I wake up at 7. Then I eat breakfast at home. At 9 I go to school. At school I study Korean. At lunch I meet a friend at the school cafeteria. In the afternoon I do homework at the library. At 6 in the evening I come home. I rest at home.",qas:[{q:"What time did Sujin wake up?",a:"7시에 (at 7 o'clock)"},{q:"Where did Sujin meet her friend?",a:"학교 식당에서 (at the school cafeteria)"},{q:"Find all the 에서 in the text. Why does each one use 에서 and not 에?",a:"집에서 먹어요 (eating is an action), 학교에서 공부해요 (studying is an action), 식당에서 만나요 (meeting is an action), 도서관에서 해요 (doing homework is an action), 집에서 쉬어요 (resting is an action at home)."}]},{kind:"drill",prompt:"지문에서 뭐라고 했어요? · What did the passage say?",sentence:"오늘 ___ 7시에 일어나요.",options:[{text:"카페",ok:!1},{text:"아침",ok:!0},{text:"회사",ok:!1}],explanation:""},{kind:"drill",prompt:"지문에서 뭐라고 했어요? · What did the passage say?",sentence:"9시에 ___에 가요.",options:[{text:"카페",ok:!1},{text:"학교",ok:!0},{text:"회사",ok:!1}],explanation:""}],canDo:"Mark where an action happens with N에서 (집에서 일해요)",id:"chapter-06-b7",chapterId:"chapter-06",index:6},{kind:"boss",title:"보스 Boss bite · 다 걸어요",cards:[{kind:"drill",prompt:"Your friend asks '어디에서 왔어요?' You want to say 'I came from England.' Which is correct?",sentence:null,options:[{text:"영국에 왔어요.",ok:!1},{text:"영국에서 왔어요.",ok:!0},{text:"영국을 왔어요.",ok:!1}],explanation:"에서 has a second meaning: FROM (a starting point). 영국에서 왔어요 = I came from England. If you said 영국에 왔어요, that means 'I came TO England' — the opposite!"},{kind:"drill",prompt:"카페___ 만나요. (We meet at a cafe.)",sentence:null,options:[{text:"에서",ok:!0},{text:"에",ok:!1},{text:"를",ok:!1}],explanation:"Meeting is an action happening at the cafe, so use 에서. 에 would fit going to the cafe or being there, not doing the meeting action."}],canDo:"Keep 에 and 에서 apart by going there vs doing there",id:"chapter-06-b8",chapterId:"chapter-06",index:7}]},{id:"chapter-07",number:7,title:"도 vs 만 · (으)로",goal:"Use 도 to add one more item to an order ('and this too, please')",biteCount:8,bites:[{kind:"words",title:"단어 Words 1 · 주세요~",cards:[{kind:"guess",word:{ko:"주세요",romanization:"juseyo",en:"please give me / please do",pos:"verb ending"},sentence:{ko:"아메리카노 두 잔 주세요.",en:"Two Americanos, please."},target:"주세요",options:["how much is it?","card (credit/debit)","please give me / please do"],note:"N + 주세요 = the single most useful ordering pattern in Korea"},{kind:"guess",word:{ko:"얼마예요",romanization:"eolmayeyo",en:"how much is it?",pos:"expression"},sentence:{ko:"이거 얼마예요?",en:"How much is this?"},target:"얼마예요",options:["please give me / please do","how much is it?","card (credit/debit)"],note:"이거 (this) + 얼마예요 — the go-to price question in any market, convenience store, or café"},{kind:"guess",word:{ko:"카드",romanization:"kadeu",en:"card (credit/debit)",pos:"noun",nuance:"카드로 is the method “by card.” 카드 돼요? is short but very common."},sentence:{ko:"카드로 결제할 수 있어요?",en:"Can I pay by card?"},target:"카드",options:["card (credit/debit)","receipt","menu"],note:"카드 ends in a vowel → 로 (not 으로)"},{kind:"guess",word:{ko:"현금",romanization:"hyeongeum",en:"cash",pos:"noun",nuance:"현금(現金) is Sino-Korean — 現 'present/actual' + 金 'gold/money' — literally 'actual money', i.e. physical notes and coins you hand over, as opposed to 카드 (card) or 계좌이체 (bank transfer). The crucial grammar point is the particle: payment method takes 으로/로 ('by means of'), so 'pay with cash' is 현금으로 내다/계산하다 — English speakers reach for 'with' and wrongly grab 와/하고 (which mean 'together with a person/thing') or 에 (location/time). 현금 is more specific than the umbrella word 돈 (money): 돈 covers wealth in general, but 현금 specifically means money in hand right now (you can have lots of 돈 in the bank but no 현금 in your wallet). A very useful real-life phrase is 현금 영수증 ('cash receipt') — a registered receipt for tax deduction that clerks routinely offer with 현금 영수증 해 드릴까요? Collocations: 현금으로 내다/계산하다/결제하다, 현금만 받다, 현금이 모자라다."},sentence:{ko:"현금으로 낼게요.",en:"I'll pay in cash."},target:"현금",options:["cash","receipt","menu"],note:"현금 ends in a consonant (ㅁ) → 으로"},{kind:"guess",word:{ko:"결제하다",romanization:"gyeoljekhada",en:"to pay / to process payment",pos:"verb"},sentence:{ko:"카드로 결제하면 돼요?",en:"Is it okay to pay by card?"},target:"결제하",options:["to order","to pay / to process payment","it's okay / it works / available"],note:"결제하다 is the formal word for payment processing; 내다 or 계산하다 are more casual"},{kind:"guess",word:{ko:"영수증",romanization:"yeongsujeung",en:"receipt",pos:"noun",nuance:"영수증(領收證) is Sino-Korean — 領 'receive' + 收 'collect' + 證 'proof/certificate' — literally a 'proof of receiving (payment)', the printed slip showing the shop got your money. Distinguish it from 계산서(計算書) 'the bill/check', which is the itemized statement of what you OWE (you read a 계산서 before paying, mostly at restaurants), whereas the 영수증 is issued AFTER you pay as proof. Also keep 영수증 apart from 현금 영수증, a specifically Korean tax-deduction receipt tied to your phone number that clerks ask about separately. Because clerks routinely offer it, you'll constantly hear the polite 영수증 드릴까요? ('shall I give you the receipt?', humble 드리다 raising you the customer), and the practical answer is 네, 주세요 or 아니요, 괜찮아요. The English-speaker pitfall is mislabeling: don't call the receipt a 계산서 — that's the pre-payment bill — and remember a refund hinges on it (환불하려면 영수증이 필요해요). Collocations: 영수증을 주다/받다, 영수증이 필요하다, 영수증을 챙기다 (keep the receipt), 현금 영수증, 영수증을 버리다."},sentence:{ko:"영수증 주세요.",en:"Receipt, please."},target:"영수증",options:["card (credit/debit)","receipt","cash"],note:"Direct N 주세요 request — no extra particles needed"},{kind:"payoff",line:{speaker:"민준",ko:"아메리카노 한 잔 주세요.",en:"One Americano, please."},hl:"주세요"}],canDo:"Add one more thing with N도 and limit to one with N만",id:"chapter-07-b1",chapterId:"chapter-07",index:0},{kind:"pattern",title:"문법 Grammar · 도 vs 만",cards:[{kind:"hunt",name:"도 vs 만",sub:"also / too vs only",lines:[{tokens:[{pre:"저",mid:"도",post:"",hit:!0},{pre:"학생이에요.",mid:"",post:"",hit:!1}],ko:"저도 학생이에요.",en:"I'm a student too.",romanization:"jeo-do hak-saeng-i-e-yo."},{tokens:[{pre:"물",mid:"만",post:"",hit:!0},{pre:"주세요.",mid:"",post:"",hit:!1}],ko:"물만 주세요.",en:"Just water, please.",romanization:"mul-man ju-se-yo."}],rule:{name:"도 vs 만",rows:[{when:"Any noun (받침 or not) + 도",add:"+ 도",ex:"저 → 저도, 물 → 물도, 친구 → 친구도"},{when:"Any noun (받침 or not) + 만",add:"+ 만",ex:"물 → 물만, 밥 → 밥만, 학생 → 학생만"},{when:"Replaces 은/는/이/가 (never 저는도 / 친구가만)",add:"drop the marker, add 도/만",ex:"저는 → 저도 (NOT 저는도), 친구가 → 친구만"},{when:"Replaces 을/를 too",add:"drop 을/를, add 도/만",ex:"밥을 → 밥도 / 밥만, 책을 → 책도 / 책만"}]},more:{func:'도 means "also / too" and adds this noun to others; 만 means "only" and shuts out everything else. Both attach straight to a noun and take the place of the topic/subject/object marker (은/는/이/가/을/를) instead of sitting on top of it.',funcLead:'도 means "also / too" and adds this noun to others; 만 means "only" and shuts out everything else.',keyPoint:{label:"도 vs 만",body:'도 includes (this AND the rest); 만 excludes (this and NOTHING else). Quick test: if "too" fits, use 도; if "just / nothing but" fits, use 만. Either way you drop 은/는/이/가/을/를 first — 저도, never 저는도; 밥만, never 밥을만.'},pronunciation:"만 after a 받침 nasalizes the consonant before it: 밥만 sounds like [밤만] (ㅂ → ㅁ before ㅁ).",pitfall:{wrong:"저는도 학생이에요. / 밥을만 먹어요.",right:"저도 학생이에요. / 밥만 먹어요.",explanation:'In English you keep the subject and just bolt on "too," so learners want to hold onto 는/을 and add 도/만 after it. In Korean, 도/만 replace 은/는/이/가/을/를 — strip the old marker off completely, then add 도 or 만.'}}},{kind:"drill",prompt:"My friend is coming too.",sentence:"친구___ 같이 가요.",options:[{text:"도",ok:!0},{text:"만",ok:!1}],explanation:"도 adds 친구 to the people already going; it replaces 가 in 친구가."},{kind:"drill",prompt:"I only eat rice.",sentence:"저는 밥___ 먹어요.",options:[{text:"도",ok:!1},{text:"으로",ok:!1},{text:"만",ok:!0}],explanation:"만 stands in for the object marker 을 in 밥을 — rice and nothing else. (밥만 sounds like [밤만].)"},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"저는도 학생이에요. / 밥을만 먹어요.",ok:!1},{text:"저도 학생이에요. / 밥만 먹어요.",ok:!0}],explanation:'In English you keep the subject and just bolt on "too," so learners want to hold onto 는/을 and add 도/만 after it. In Korean, 도/만 replace 은/는/이/가/을/를 — strip the old marker off completely, then add 도 or 만.'},{kind:"drill",prompt:"빈칸을 채우세요 · Complete the form — Any noun (받침 or not) + 도",sentence:"저___",options:[{text:"도, 물 → 물도, 친구 → 친구도",ok:!0},{text:"만, 밥 → 밥만, 학생 → 학생만",ok:!1}],explanation:"저 → 저도, 물 → 물도, 친구 → 친구도"}],canDo:"Add one more thing with N도 and limit to one with N만",id:"chapter-07-b2",chapterId:"chapter-07",index:1},{kind:"words",title:"단어 Words 2 · 주문하다~",cards:[{kind:"guess",word:{ko:"주문하다",romanization:"jumunhada",en:"to order",pos:"verb",nuance:"주문하다 is used for ordering food, drinks, products, or services."},sentence:{ko:"주문해도 돼요?",en:"May I order now?"},target:"주문해",options:["to order","it's okay / it works / available","please give me / please do"],note:"주문하다 + 아/어도 돼요? = polite permission request; 받다 (receive) is often said by staff: 주문받겠습니다"},{kind:"guess",word:{ko:"메뉴",romanization:"menyu",en:"menu",pos:"noun",nuance:"메뉴 (loanword from 'menu') carries two senses Koreans switch between freely: (1) the printed list of offerings, and (2) an individual dish/order — so 무슨 메뉴 먹을까? means 'which dish shall we get?', and 메뉴 정했어? means 'have you decided what to order?'. When you specifically mean the physical card you hand over, Koreans often say 메뉴판 (menu-board) to disambiguate. The dish sense overlaps with 음식(food in general) and 요리(a cooked dish), but 메뉴 frames it as a selectable option on offer. Common partners: 메뉴를 정하다/고르다(decide/choose a dish), 메뉴가 다양하다(varied), 오늘의 메뉴(today's special). The English-speaker pitfall is locking 메뉴 to the printed-list meaning only, then being confused by 이 집은 메뉴가 맛있어요 — which praises the dishes, not the paper."},sentence:{ko:"메뉴 주세요.",en:"Menu, please."},target:"메뉴",options:["menu","card (credit/debit)","cash"],note:"메뉴 is a loanword from English; in practice many Korean cafés have menus only on boards, so this is more useful than it sounds"},{kind:"guess",word:{ko:"하나",romanization:"hana",en:"one (native Korean number)",pos:"number",nuance:'하나 is the native-Korean (고유어) word for "one," the counting system Koreans use for tangible things, people, age, and the clock hour — as opposed to its Sino-Korean twin 일, which rules dates, money, minutes, and phone numbers. The single biggest fact to internalize: when 하나 sits directly in front of a counter (개, 명, 시, 살, 마리), it loses its last syllable and becomes 한 — 한 개, 한 명, 한 시 — while the full 하나 only stands alone (as in counting "하나, 둘" or taking a particle, 하나만). English speakers reliably trip here by saying 하나 개 or, worse, importing the Sino number and saying 일 개; both sound clearly wrong to a Korean ear. There is no hanja because it is purely native, so do not look for one.'},sentence:{ko:"아메리카노 하나 주세요.",en:"One Americano, please."},target:"하나",options:["please give me / please do","one (native Korean number)","how much is it?"],note:"Quantities in ordering use native Korean numbers (하나, 둘, 셋), not Sino-Korean (일, 이, 삼)"},{kind:"guess",word:{ko:"좀",romanization:"jom",en:"a little / please (softener)",pos:"adverb",nuance:"좀 is the contracted, spoken form of 조금 and is everywhere in daily conversation. Its key second life — the part that trips up English speakers — is as a request softener: in 물 좀 주세요 or 좀 도와주세요, 좀 is not measuring a 'little' amount at all but functioning like 'please/if you would', taking the bluntness off a command. So 물 주세요 is grammatically fine but can feel abrupt, whereas 물 좀 주세요 sounds warm and natural. Compared with the full 조금, 좀 is purely conversational and a touch more casual; in formal writing or stiff announcements you revert to 조금 or a fuller polite request form. Collocates constantly with request verbs (좀 주세요, 좀 해 주세요, 좀 보여 주세요) and with mild complaints (좀 춥다, 좀 그렇다). The pitfall is over-literal reading: don't try to translate the 'softener' 좀 as 'a little', and don't drop it from requests — Koreans add it precisely to sound polite."},sentence:{ko:"물 좀 주세요.",en:"Some water, please."},target:"좀",options:["how much is it?","card (credit/debit)","a little / please (softener)"],note:"좀 softens the request; 좀 주세요 sounds more polite and natural than 주세요 alone"},{kind:"guess",word:{ko:"더",romanization:"deo",en:"more",pos:"adverb",nuance:"더 is the basic comparative marker meaning 'more,' and crucially Korean has no '-er/more...than' suffix — you simply put 더 before the adjective and (optionally) mark the standard of comparison with the particle 보다: A가 B보다 더 크다 = 'A is bigger than B.' Its direct antonym is 덜 ('less'). A common booster is 훨씬 ('by far, much'), which stacks in front: 훨씬 더 좋다 = 'much better.' Watch two set phrases: 더 이상 + negative = 'no longer / not anymore' (더 이상 못 참아 = 'I can't take it anymore'), and 더 ~ -ㄹ수록 patterns for 'the more...'. The English-speaker pitfall: learners often drop 더 entirely because they expect the adjective itself to change form ('big' → 'bigger'), but 크다 never inflects for comparison — without 더 the sentence just says 'is big,' not 'is bigger.' Another trap is the 보다 direction: 보다 attaches to the thing you compare AGAINST (the 'than' item), so '내가 너보다 커' = 'I'm taller than you,' which feels backwards to English ears. Also don't confuse spoken 더 with the homophone-ish 덜; they are opposites."},sentence:{ko:"물 좀 더 주세요.",en:"A little more water, please."},target:"더",options:["please give me / please do","how much is it?","more"],note:"더 = more quantity; often combined with 좀 for a polite, natural request for a refill"},{kind:"guess",word:{ko:"됩니다 / 돼요",romanization:"doemnida / dwaeyo",en:"it's okay / it works / available",pos:"verb"},sentence:{ko:"카드 돼요?",en:"Is card okay?"},target:"돼요",options:["to pay / to process payment","it's okay / it works / available","to order"],note:"카드 돼요? is a spoken shortcut — grammatically incomplete but perfectly natural in shops"},{kind:"payoff",line:{speaker:"민준",ko:"빵도 하나 주세요.",en:"Bread too, please."},hl:"하나"}],canDo:"Say the payment method or means with N(으)로 (카드로, 현금으로)",id:"chapter-07-b3",chapterId:"chapter-07",index:2},{kind:"pattern",title:"문법 Grammar · (으)로",cards:[{kind:"hunt",name:"(으)로",sub:"by / with, and which way",lines:[{tokens:[{pre:"카드",mid:"로",post:"",hit:!0},{pre:"계산할게요.",mid:"",post:"",hit:!1}],ko:"카드로 계산할게요.",en:"I'll pay by card.",romanization:"ka-deu-ro gye-san-hal-ge-yo."},{tokens:[{pre:"젓가락",mid:"으로",post:"",hit:!0},{pre:"먹어요.",mid:"",post:"",hit:!1}],ko:"젓가락으로 먹어요.",en:"I eat with chopsticks.",romanization:"jeot-ga-ra-geu-ro meo-geo-yo."}],rule:{name:"(으)로",rows:[{when:"Noun ends in a vowel",add:"+ 로",ex:"카드 → 카드로, 버스 → 버스로, 한국어 → 한국어로"},{when:"Noun ends in a 받침 (consonant)",add:"+ 으로",ex:"손 → 손으로, 젓가락 → 젓가락으로, 현금 → 현금으로"},{when:"Noun ends in ㄹ 받침 (special case)",add:"+ 로 (not 으로)",ex:"지하철 → 지하철로, 연필 → 연필로"},{when:'Direction "toward / to"',add:"+ (으)로",ex:"집 → 집으로, 학교 → 학교로, 이쪽 → 이쪽으로"}]},more:{func:`(으)로 marks how you do something — the tool, language, payment method, or transport ("by / with / in") — and also the direction you head ("toward / to"). You'll reach for it constantly when paying and ordering.`,funcLead:'(으)로 marks how you do something — the tool, language, payment method, or transport ("by / with / in") — and also the direction you head ("toward / to").',keyPoint:{label:"(으)로 vs 에 (direction)",body:`For where you're going, 에 marks the destination you arrive at (집에 가요 = go home), while (으)로 stresses the direction you head (집으로 가요 = head toward home) — at this level either is fine for "go home." Mostly you'll use the "by / with" sense: 카드로, 현금으로, 한국어로. Just watch the ㄹ rule — 지하철로, not 지하철으로.`,add:"",ex:"",when:""},pronunciation:"으로 after a 받침 pulls the consonant into 으: 손으로 sounds like [소느로], 집으로 like [지브로].",pitfall:{wrong:"지하철으로 가요. / 카드으로 계산해요.",right:"지하철로 가요. / 카드로 계산해요.",explanation:"Learners stretch the 받침 → 으로 rule too far. Vowel-final nouns just take 로 (카드로), and ㄹ-final words are a special case that also take plain 로, not 으로 (지하철로, 연필로). Only non-ㄹ 받침 nouns get 으로."}}},{kind:"drill",prompt:"Please speak in Korean.",sentence:"한국어___ 말해 주세요.",options:[{text:"로",ok:!0},{text:"으로",ok:!1}],explanation:"한국어 ends in a vowel → 로; here 로 marks the language you're using."},{kind:"drill",prompt:"I'm heading home.",sentence:"집___ 가요.",options:[{text:"도",ok:!1},{text:"만",ok:!1},{text:"으로",ok:!0}],explanation:"집 ends in 받침 ㅂ → 으로; here 로 marks direction, not a means."},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"지하철으로 가요. / 카드으로 계산해요.",ok:!1},{text:"지하철로 가요. / 카드로 계산해요.",ok:!0}],explanation:"Learners stretch the 받침 → 으로 rule too far. Vowel-final nouns just take 로 (카드로), and ㄹ-final words are a special case that also take plain 로, not 으로 (지하철로, 연필로). Only non-ㄹ 받침 nouns get 으로."},{kind:"drill",prompt:"빈칸을 채우세요 · Complete the form — Noun ends in a vowel",sentence:"카드___",options:[{text:"으로, 젓가락 → 젓가락으로, 현금 → 현금으로",ok:!1},{text:"로, 연필 → 연필로",ok:!1},{text:"로, 버스 → 버스로, 한국어 → 한국어로",ok:!0}],explanation:"카드 → 카드로, 버스 → 버스로, 한국어 → 한국어로"}],canDo:"Say the payment method or means with N(으)로 (카드로, 현금으로)",id:"chapter-07-b4",chapterId:"chapter-07",index:3},{kind:"words",title:"단어 Words 3 · 이거 / 이것~",cards:[{kind:"guess",word:{ko:"이거 / 이것",romanization:"igeo / igeot",en:"this (one)",pos:"pronoun",nuance:"이거 is the casual, mouth-friendly version of 이것 — 'this thing' near the speaker — and it is overwhelmingly the form you HEAR and USE in real life: shopping, ordering food, pointing things out. Meaning is identical to 이것; the only difference is register, with 이거 being conversational and 이것 belonging to writing or formal speech. It contracts naturally with particles into 이게 (subject), 이걸 (object), 이건 (topic), and 이걸로 ('with this'). The number-one English-speaker error is grafting English particle habits onto it: 이거가 sounds clumsy because Koreans fuse it to 이게, and the same goes for 이거를 → 이걸. Like 이것, it cannot sit before a noun (that job belongs to 이: 이 가방), and it should never label a person."},sentence:{ko:"이것도 주세요.",en:"This too, please."},target:"이것",options:["please give me / please do","how much is it?","this (one)"],note:"이거 is the spoken form, 이것 is written/formal; both work at a café or shop counter"},{kind:"guess",word:{ko:"포장",romanization:"pojang",en:"takeout / to go",pos:"noun / verb stem"},sentence:{ko:"포장해 주세요.",en:"To go, please."},target:"포장",options:["please give me / please do","how much is it?","takeout / to go"],note:"포장 (packing) = takeout in Korean. 포장이요? is how staff ask if you want it to go"},{kind:"guess",word:{ko:"추천",romanization:"chucheon",en:"recommendation",pos:"noun"},sentence:{ko:"추천 메뉴가 뭐예요?",en:"What's the recommended menu item?"},target:"추천",options:["card (credit/debit)","recommendation","cash"],note:"추천 없어요? or 추천 메뉴요? are very natural ways to ask a café or restaurant what's good"},{kind:"guess",word:{ko:"할인",romanization:"halin",en:"discount",pos:"noun",nuance:"할인(割引) is Sino-Korean — 割 'cut' + 引 'pull (down)' — literally 'cut and pull down', i.e. knock money off a price. The key contrast for learners is 할인 vs 세일: 할인 is the abstract act/amount of reducing a price on an item ('10% off', a discount), while 세일 (from English 'sale') names a store-wide selling event (백화점 세일 a department-store sale). So a 세일 contains many 할인s. Watch the voice carefully: from the price's point of view you say 할인이 되다/할인되다 ('it gets discounted'); from your point of view as buyer you say 할인을 받다 ('I receive a discount'); and to actively ask for one you say 할인해 주세요 ('please discount it for me'). The English-speaker pitfall is firing 할인해요 at a clerk hoping it means 'give me a discount' — bare 할인해요 just states 'someone discounts', so it lands as a flat description, not a request. Add 주세요/돼요 to make it work. Common partners: 할인되다, 할인받다, 할인 행사 (discount event), 할인 쿠폰."},sentence:{ko:"학생 할인 돼요?",en:"Is there a student discount?"},target:"할인",options:["card (credit/debit)","discount","cash"],note:"할인 + 돼요? is the pattern to ask about discounts; 학생 할인, 앱 할인, 포인트 할인 all work the same way"},{kind:"guess",word:{ko:"맵다",romanization:"maepda",en:"to be spicy",pos:"adjective",nuance:"맵다 is ㅂ irregular: 매워요, 매운 음식. It is especially useful for food restrictions, because 매운 음식은 못 먹어요 is a survival sentence."},sentence:{ko:"안 맵게 해 주세요.",en:"Please make it not spicy."},target:"맵게",options:["please give me / please do","to be spicy","how much is it?"],note:"맵게 is the adverbial form (spicily); 안 맵게 해 주세요 = make it in a not-spicy way — practical for dietary restrictions"}],canDo:"Make a simple request with 주세요 (커피 하나 주세요)",id:"chapter-07-b5",chapterId:"chapter-07",index:4},{kind:"dialogue",title:"대화 Dialogue · 진짜 한국어",cards:[{kind:"chat",setting:"Minjun and his coworker Yuna go to a café. Minjun orders for both of them.",lines:[{speaker:"직원",ko:"어서 오세요! 뭐 드릴까요?",en:"Welcome! What can I get you?",romanization:"Eoseo oseyo! Mwo deurilkkayo?"},{speaker:"민준",ko:"아메리카노 한 잔 주세요.",en:"One Americano, please.",romanization:"Amerikano han jan juseyo."},{speaker:"직원",ko:"다른 거 더 필요하세요?",en:"Do you need anything else?",romanization:"Dareun geo deo piryohaseyo?"},{speaker:"민준",ko:"빵도 하나 주세요.",en:"Bread too, please.",romanization:"Ppangdo hana juseyo."},{speaker:"유나",ko:"저는 물만 주세요. 커피는 안 마셔요.",en:"Just water for me, please. I don't drink coffee.",romanization:"Jeoneun mulman juseyo. Keopineun an masyeoyo."},{speaker:"직원",ko:"알겠습니다. 결제는 어떻게 하시겠어요?",en:"Got it. How would you like to pay?",romanization:"Algesseumnida. Gyeoljeneun eotteoke hashigesseoyo?"},{speaker:"민준",ko:"카드로 결제해도 돼요?",en:"Can I pay by card?",romanization:"Kadeuro gyeoljehaedo dwaeyo?"},{speaker:"직원",ko:"네, 카드 됩니다. 영수증은 필요하세요?",en:"Yes, card is fine. Do you need a receipt?",romanization:"Ne, kadeu doemnida. Yeongsujeungeun piryohaseyo?"}]},{kind:"order",prompt:"Build: 'Water too, please.'",tokens:["물도","주세요"],correct:"물도 주세요",explanation:"도 adds “too/also” to 물. 주세요 makes it a polite ordering request."},{kind:"drill",prompt:"누가 한 말일까요? · Who said this?",sentence:"네, 카드 됩니다. 영수증은 필요하세요?",options:[{text:"직원",ok:!0},{text:"민준",ok:!1}],explanation:"Yes, card is fine. Do you need a receipt?"},{kind:"drill",prompt:'무엇이 들어갈까요? · "One Americano, please."',sentence:"아메리카노 한 잔 ___.",options:[{text:"얼마예요",ok:!1},{text:"주세요",ok:!0},{text:"카드",ok:!1}],explanation:""}],canDo:"Add one more thing with N도 and limit to one with N만",id:"chapter-07-b6",chapterId:"chapter-07",index:5},{kind:"reading",title:"읽기 Reading · 편의점에서 (At the Convenience Store)",cards:[{kind:"read",title:"편의점에서 (At the Convenience Store)",chunks:["오늘 편의점에 가요. 과자를 하나 사요. 직원에게 '이거 얼마예요?'라고 물어요. 삼천 원이에요. 현금이 없어요.","그래서 카드로 결제해요. 영수증도 받아요. 음료는 안 사요. 이것만 사요. 다음에는 할인도 확인해요."],translation:"Today I go to a convenience store. I buy one snack. I ask the staff, 'How much is this?' It is 3,000 won. I don't have cash, so I pay by card. I get a receipt too. I don't buy a drink. I buy only this. Next time I check discounts too.",qas:[{q:"How did the speaker pay, and why?",a:"카드로 결제해요 — they pay by card because they have no cash (현금이 없어요. 그래서...)"},{q:"What does the speaker buy, and what do they not buy?",a:"과자를 하나 사요. 음료는 안 사요 — they buy one snack and do not buy a drink."},{q:"Find every 도 and 만 in the text. For each one, explain whether it is adding something or limiting something.",a:"영수증도 받아요 — 도 adds the receipt to the list of things that happen (CART: one more item); 이것만 사요 — 만 limits the purchase to only this item (SPOTLIGHT: nothing else); 할인도 확인해요 — 도 adds checking discounts to the plan (CART: another thing to do)"}]},{kind:"drill",prompt:"지문에서 뭐라고 했어요? · What did the passage say?",sentence:"과자를 ___ 사요.",options:[{text:"주세요",ok:!1},{text:"결제하다",ok:!1},{text:"하나",ok:!0}],explanation:""},{kind:"drill",prompt:"지문에서 뭐라고 했어요? · What did the passage say?",sentence:"직원에게 '이거 ___?'라고 물어요.",options:[{text:"얼마예요",ok:!0},{text:"주세요",ok:!1},{text:"결제하다",ok:!1}],explanation:""}],canDo:"Say the payment method or means with N(으)로 (카드로, 현금으로)",id:"chapter-07-b7",chapterId:"chapter-07",index:6},{kind:"boss",title:"보스 Boss bite · 다 걸어요",cards:[{kind:"drill",prompt:"The staff asks how you want to pay. You want to ask 'Is it okay if I pay by card?' Which is the most natural?",sentence:null,options:[{text:"카드에 결제해도 돼요?",ok:!1},{text:"카드로 결제해도 돼요?",ok:!0},{text:"카드를 결제해도 돼요?",ok:!1}],explanation:"로/으로 marks the method of payment — the card is the CHANNEL. 카드에 would mean 'at the card' (card as a location — doesn't work). 카드를 would mean 'pay the card' — as if the card itself is the thing being paid, not the payment method."},{kind:"drill",prompt:"카드___ 결제할게요. (I will pay by card.)",sentence:null,options:[{text:"로",ok:!0},{text:"도",ok:!1},{text:"만",ok:!1}],explanation:"카드로 means by card or using a card as the method. 도 means also and 만 means only, so neither marks the payment method."}],canDo:"Make a simple request with 주세요 (커피 하나 주세요)",id:"chapter-07-b8",chapterId:"chapter-07",index:7}]},{id:"chapter-08",number:8,title:"-고 싶어요 · -(으)ㄹ 수 있어요 / 없어요",goal:"Use 고 싶어요 correctly to express what you want or desire to do",biteCount:8,bites:[{kind:"words",title:"단어 Words 1 · 먹다~",cards:[{kind:"guess",word:{ko:"먹다",romanization:"meokda",en:"to eat",pos:"verb",nuance:"먹다 is used for meals and food. For medicine, Korean often uses 약을 먹어요, literally “eat medicine,” which means “take medicine.”"},sentence:{ko:"맵지 않은 것을 먹고 싶어요.",en:"I want to eat something that isn't spicy."},target:"먹고",options:["to drink","to go","to eat"],note:"먹고 싶어요 — desire form; essential at Korean restaurants for dietary preferences"},{kind:"guess",word:{ko:"마시다",romanization:"masida",en:"to drink",pos:"verb",nuance:"마시다 is for liquids. In casual speech, Koreans often drop particles: 커피 마셔요 is natural."},sentence:{ko:"커피를 마시고 싶어요.",en:"I want to drink coffee."},target:"마시",options:["to eat","to go","to drink"],note:"마시 + 고 싶어요 — the stem ends in a vowel so 고 attaches cleanly"},{kind:"guess",word:{ko:"가다",romanization:"gada",en:"to go",pos:"verb",nuance:"Use 에 for destination: 학교에 가요, 집에 가요. Do not use 에서 for destination."},sentence:{ko:"오늘은 못 가요. 내일 갈 수 있어요.",en:"I can't go today. I can go tomorrow."},target:"가요",options:["to eat","to go","to drink"],note:"Two patterns in one sentence: 못 가요 (blocked today) vs 갈 수 있어요 (open tomorrow)"},{kind:"guess",word:{ko:"하다",romanization:"hada",en:"to do",pos:"verb",nuance:"하다 combines with many nouns: 공부하다, 일하다, 운동하다. It is one of the most important Korean verbs."},sentence:{ko:"한국어를 잘하고 싶어요.",en:"I want to get better at Korean."},target:"하고",options:["to eat","to do","to drink"],note:"잘하 + 고 싶어요 — long-term aspiration; note that 못 for 하다 = 못 해요, NOT 못 하해요"},{kind:"guess",word:{ko:"말하다",romanization:"malhada",en:"to speak / to say",pos:"verb",nuance:"Use 로 for language: 한국어로 말해요, 영어로 말해요. 말하다 can mean both “speak” and “say,” so the object or quote decides the English translation."},sentence:{ko:"한국어로 말할 수 있어요.",en:"I can speak in Korean."},target:"말할",options:["to eat","to drink","to speak / to say"],note:"말하다 → stem 말하 + ㄹ 수 있어요 → 말할 수 있어요; often used to express language ability"},{kind:"guess",word:{ko:"먹을 수 있다",romanization:"meogeul su itda",en:"to be able to eat / can eat",pos:"verb phrase"},sentence:{ko:"저는 매운 음식을 먹을 수 있어요.",en:"I can eat spicy food."},target:"먹을 수 있",options:["to have time (lit. time exists)","to be able to eat / can eat","to drink"],note:"먹 (consonant ending stem) + 을 수 있어요 — consonant stems take 을 수, vowel stems take ㄹ 수"},{kind:"payoff",line:{speaker:"지혜",ko:"민수 씨, 오늘 저녁에 삼겹살 먹고 싶어요?",en:"Minsu, do you want to eat samgyeopsal this evening?"},hl:"먹고"}],canDo:"Say what you want to do with V-고 싶어요 (가고 싶어요)",id:"chapter-08-b1",chapterId:"chapter-08",index:0},{kind:"pattern",title:"문법 Grammar · -고 싶어요",cards:[{kind:"hunt",name:"-고 싶어요",sub:'saying what you want to do ("I want to…")',lines:[{tokens:[{pre:"저는",mid:"",post:"",hit:!1},{pre:"물을",mid:"",post:"",hit:!1},{pre:"마시",mid:"고",post:"",hit:!0},{pre:"",mid:"싶어요",post:".",hit:!0}],ko:"저는 물을 마시고 싶어요.",en:"I want to drink water.",romanization:"jeoneun mureul masigo sipeoyo."},{tokens:[{pre:"오늘",mid:"",post:"",hit:!1},{pre:"친구를",mid:"",post:"",hit:!1},{pre:"만나",mid:"고",post:"",hit:!0},{pre:"",mid:"싶어요",post:".",hit:!0}],ko:"오늘 친구를 만나고 싶어요.",en:"I want to meet a friend today.",romanization:"oneul chingureul mannago sipeoyo."}],rule:{name:"-고 싶어요",rows:[{when:"Verb stem ends in a vowel",add:"stem + 고 싶어요",ex:"가다 → 가고 싶어요 (want to go)"},{when:"Verb stem ends in a consonant (받침)",add:"stem + 고 싶어요 (no change)",ex:"먹다 → 먹고 싶어요 (want to eat)"},{when:"Past and negative go on 싶다, not the main verb",add:"…고 싶었어요 (wanted to) / …고 싶지 않아요 (don't want to)",ex:"보다 → 보고 싶었어요 / 보고 싶지 않아요"}]},more:{func:"Add -고 싶어요 to a verb stem to say what you want to do. It's for your own wants; talking about what someone else wants uses -고 싶어 하다, which comes in a later chapter.",funcLead:"Add -고 싶어요 to a verb stem to say what you want to do.",keyPoint:{label:"Keep 을/를 on the thing you want",body:"With -고 싶어요 the thing you want is still the object, so use 을/를: 밥을 먹고 싶어요 (I want to eat). You'll also hear 밥이 먹고 싶어요 in casual speech, but 밥을 먹고 싶어요 is the safe, standard choice for now."},pronunciation:"싶어요 links across the boundary and sounds like [시퍼요]; 먹고 tenses the ㄱ, so 먹고 싶어요 sounds like [먹꼬 시퍼요].",pitfall:{wrong:"저는 행복하고 싶어요.",right:"저는 행복해지고 싶어요. / 행복하면 좋겠어요.",explanation:'"I want to be happy" tempts you to stick -고 싶어요 on 행복하다. But -고 싶어요 only goes on action verbs, not on adjectives (descriptive verbs). For a state, use 행복해지다 (become happy) or the wish pattern -으면 좋겠다.'}}},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "I want to drink water."',tokens:["저는","물을","마시고","싶어요."],correct:"저는 물을 마시고 싶어요.",explanation:""},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "I want to meet a friend today."',tokens:["오늘","친구를","만나고","싶어요."],correct:"오늘 친구를 만나고 싶어요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"저는 행복해지고 싶어요. / 행복하면 좋겠어요.",ok:!0},{text:"저는 행복하고 싶어요.",ok:!1}],explanation:'"I want to be happy" tempts you to stick -고 싶어요 on 행복하다. But -고 싶어요 only goes on action verbs, not on adjectives (descriptive verbs). For a state, use 행복해지다 (become happy) or the wish pattern -으면 좋겠다.'}],canDo:"Say what you want to do with V-고 싶어요 (가고 싶어요)",id:"chapter-08-b2",chapterId:"chapter-08",index:1},{kind:"words",title:"단어 Words 2 · 맵다~",cards:[{kind:"guess",word:{ko:"맵다",romanization:"maepda",en:"spicy / hot (taste)",pos:"adjective",nuance:"맵다 is ㅂ irregular: 매워요, 매운 음식. It is especially useful for food restrictions, because 매운 음식은 못 먹어요 is a survival sentence."},sentence:{ko:"이 음식은 너무 매워서 못 먹어요.",en:"This food is too spicy so I can't eat it."},target:"매워",options:["spicy / hot (taste)","to be okay / fine / alright","to be busy"],note:"맵다 is a ㅂ-irregular adjective: 매워서 (not 맵어서) — important for describing food limitations"},{kind:"guess",word:{ko:"괜찮다",romanization:"gwaenchanta",en:"to be okay / fine / alright",pos:"adjective",nuance:"괜찮아요 can mean okay, fine, no thanks, or not bad. Context decides."},sentence:{ko:"조금 매워도 괜찮아요.",en:"It's okay even if it's a little spicy."},target:"괜찮",options:["to be okay / fine / alright","spicy / hot (taste)","to be busy"],note:"괜찮아요 alone works as 'it's fine'; combined with 먹을 수 있어요 context it reassures the other person"},{kind:"guess",word:{ko:"알다",romanization:"alda",en:"to know",pos:"verb",nuance:"알다 means 'to know / be aware of / be acquainted with' and takes the object marker 을/를: 저 사람을 알아요. It is a ㄹ-irregular verb: the stem ㄹ drops before ㅂ, ㄴ, and the honorific ㅅ, giving 압니다 (not 알습니다) and 아세요 (not 알으세요), but the ㄹ stays before vowel endings, so the everyday polite form is 알아요. Two contrasts are essential. First, its opposite is not the negative 안 알아요 — that is wrong — but the separate verb 모르다, so 'I don't know' is 몰라요. Second, 알다 vs 알겠다: 알아요 claims knowledge you already hold ('I know that'), while 알겠어요 signals you have just understood or accepted something ('I see / got it / will do'), which is why a polite 'understood' is 알겠습니다, never 압니다. The English-speaker pitfall is twofold: forming 'don't know' as 안 알아요 instead of 몰라요, and keeping the ㄹ to say 알습니다 instead of 압니다."},sentence:{ko:"한국어를 조금 알아요.",en:"I know a little Korean."},target:"알아",options:["to know","to eat","to drink"],note:"알다 is ㄹ-irregular: 알 + 아요 = 알아요. For ability: 알 수 있어요 (stem already ends in ㄹ so no extra ㄹ added)"},{kind:"guess",word:{ko:"오다",romanization:"oda",en:"to come",pos:"verb",nuance:"오다 is from the speaker’s point of view. If someone moves toward you or your place, 오다 is usually right."},sentence:{ko:"오늘 파티에 올 수 있어요?",en:"Can you come to the party today?"},target:"올",options:["to come","to eat","to drink"],note:"오다 → stem 오 (vowel) → 올 수 있어요? A common social question — the ㄹ is added to the vowel stem"},{kind:"guess",word:{ko:"쉬다",romanization:"swida",en:"to rest / take a break",pos:"verb",nuance:"쉬다 is used for taking a break, resting, or being off work/school."},sentence:{ko:"오늘은 좀 쉬고 싶어요.",en:"I want to rest a bit today."},target:"쉬고",options:["to rest / take a break","spicy / hot (taste)","to be okay / fine / alright"],note:"쉬 + 고 싶어요 — expressing the very human desire for rest; common in daily conversation"},{kind:"guess",word:{ko:"운동하다",romanization:"undonghada",en:"to exercise",pos:"verb",nuance:"운동하다 = 한자 運動 (運 'move, transport' + 動 'move') + 하다, literally 'movement-movement,' i.e. to physically exercise. The same noun 운동 also means a sports movement or a social campaign, but with 하다 it's working out. A key feature for learners: Korean builds most sports the same way — noun + 하다 (축구하다 play soccer, 수영하다 swim), though racket sports take 치다 'hit' instead (테니스 치다). The contrast with 놀다 ('play, hang out, have fun') matters: 놀다 is unstructured fun, 운동하다 is purposeful physical activity, so don't say 놀다 when you mean training. Natural collocations: 헬스장에서 운동하다, 건강을 위해 운동하다, 운동 부족. As a 하다 verb the negatives split — 운동 안 해요, 운동 못 해요 — and you can swap in 운동을 안 하다 with the object marker for a touch more emphasis."},sentence:{ko:"요즘 바빠서 운동 못 해요.",en:"Lately I'm busy so I can't exercise."},target:"운동",options:["to exercise","spicy / hot (taste)","to be okay / fine / alright"],note:"운동하다 is a 하다 verb: 못 + 해요 = 못 해요. The noun 운동 and 못 해요 can be separated: 운동 못 해요."},{kind:"payoff",line:{speaker:"지혜",ko:"괜찮아요. 거기서 맵지 않은 것도 먹을 수 있어요.",en:"That's okay. You can also eat non-spicy things there."},hl:"맵지"}],canDo:"Say what you're able to do with V-(으)ㄹ 수 있어요",id:"chapter-08-b3",chapterId:"chapter-08",index:2},{kind:"pattern",title:"문법 Grammar · -(으)ㄹ 수 있어요 / 없어요",cards:[{kind:"hunt",name:"-(으)ㄹ 수 있어요 / 없어요",sub:"can and can't",lines:[{tokens:[{pre:"저는",mid:"",post:"",hit:!1},{pre:"한국어를",mid:"",post:"",hit:!1},{pre:"조금",mid:"",post:"",hit:!1},{pre:"할",mid:"",post:"",hit:!1},{pre:"",mid:"수",post:"",hit:!0},{pre:"",mid:"있어요",post:".",hit:!0}],ko:"저는 한국어를 조금 할 수 있어요.",en:"I can speak a little Korean.",romanization:"jeoneun hangugeoreul jogeum hal su isseoyo."},{tokens:[{pre:"이",mid:"",post:"",hit:!1},{pre:"책은",mid:"",post:"",hit:!1},{pre:"너무",mid:"",post:"",hit:!1},{pre:"어려워서",mid:"",post:"",hit:!1},{pre:"읽을",mid:"",post:"",hit:!1},{pre:"수",mid:"",post:"",hit:!1},{pre:"",mid:"없어요",post:".",hit:!0}],ko:"이 책은 너무 어려워서 읽을 수 없어요.",en:"This book is too hard, so I can't read it.",romanization:"i chaegeun neomu eoryeowoseo ilgeul su eopseoyo."}],rule:{name:"-(으)ㄹ 수 있어요 / 없어요",rows:[{when:"Stem ends in a vowel",add:"stem + ㄹ 수 있어요/없어요",ex:"가다 → 갈 수 있어요 (can go) / 갈 수 없어요 (can't go)"},{when:"Stem ends in a consonant (받침)",add:"stem + 을 수 있어요/없어요",ex:"먹다 → 먹을 수 있어요 (can eat) / 먹을 수 없어요 (can't eat)"},{when:"Stem already ends in ㄹ",add:"stem + 수 있어요 (that ㄹ is the ending, add nothing)",ex:"만들다 → 만들 수 있어요 (can make)"},{when:`Using 못 for "can't"`,add:"못 + verb",ex:"먹다 → 못 먹어요 (can't eat) / 가다 → 못 가요 (can't go)"}]},more:{func:`Add -(으)ㄹ 수 있어요 to a verb stem for "can / be able to," and -(으)ㄹ 수 없어요 for "can't." Putting 못 right before the verb is a shorter, more everyday way to say "can't."`,funcLead:`Add -(으)ㄹ 수 있어요 to a verb stem for "can / be able to," and -(으)ㄹ 수 없어요 for "can't." Putting 못 right before the verb is a shorter, more everyday way to say "can…`,keyPoint:{label:"못 (can't) vs 안 (don't / won't)",body:`Both sit right before the verb but mean different things. 못 = can't — you're unable, even if you'd like to (시간이 없어서 못 자요, I can't sleep because I have no time). 안 = a choice not to (피곤하지만 안 자요, I'm tired but I'm not going to sleep). So "can't eat" is 못 먹어요; "don't eat (by choice)" is 안 먹어요.`},pronunciation:"수 있어요 links to [수 이써요]; 못 changes before the next sound — 못 가요 sounds like [몯까요] and 못 먹어요 like [몬머거요].",pitfall:{wrong:"저는 수영을 안 할 수 있어요.",right:"저는 수영을 못 해요. / 수영을 할 수 없어요.",explanation:`For "I can't swim," learners try to negate 할 수 있어요 by adding 안. Korean doesn't do that — switch the whole phrase to 없어요 (할 수 없어요), or more naturally say 못 해요. Save 안 for choosing not to do something.`}}},{kind:"drill",prompt:"I can make kimchi.",sentence:"저는 김치를 만들 ___.",options:[{text:"수 있어요",ok:!0},{text:"없어요",ok:!1}],explanation:"만들다 already ends in ㄹ, so add nothing → 만들 수 있어요."},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "I can speak a little Korean."',tokens:["저는","한국어를","조금","할","수","있어요."],correct:"저는 한국어를 조금 할 수 있어요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"저는 수영을 안 할 수 있어요.",ok:!1},{text:"저는 수영을 못 해요. / 수영을 할 수 없어요.",ok:!0}],explanation:`For "I can't swim," learners try to negate 할 수 있어요 by adding 안. Korean doesn't do that — switch the whole phrase to 없어요 (할 수 없어요), or more naturally say 못 해요. Save 안 for choosing not to do something.`}],canDo:"Say what you're able to do with V-(으)ㄹ 수 있어요",id:"chapter-08-b4",chapterId:"chapter-08",index:3},{kind:"words",title:"단어 Words 3 · 시간이 있다~",cards:[{kind:"guess",word:{ko:"시간이 있다",romanization:"sigani itda",en:"to have time (lit. time exists)",pos:"verb phrase",nuance:"시간 works with 있어요/없어요 and is essential for scheduling."},sentence:{ko:"오늘 시간이 있어요? 같이 밥 먹고 싶어요.",en:"Do you have time today? I want to eat together."},target:"시간이 있",options:["to be able to eat / can eat","to have time (lit. time exists)","to eat"],note:"시간이 있어요 is the natural Korean way to say 'have time' — pairs perfectly with 고 싶어요 for invitations"},{kind:"guess",word:{ko:"바쁘다",romanization:"bappuda",en:"to be busy",pos:"adjective",nuance:"바쁘다 becomes 바빠요 in polite speech. It is a high-frequency reason word because 바빠서 못 가요 politely explains why a plan is impossible."},sentence:{ko:"오늘 너무 바빠서 못 가요.",en:"I'm too busy today so I can't go."},target:null,options:["spicy / hot (taste)","to be busy","to be okay / fine / alright"],note:"바쁘다 is ㅡ-irregular: 바빠서 (not 바쁘어서). Used constantly as a reason for 못 + verb"},{kind:"guess",word:{ko:"주문하다",romanization:"jumunhada",en:"to order (food/items)",pos:"verb",nuance:"주문하다 is used for ordering food, drinks, products, or services."},sentence:{ko:"뭐 주문하고 싶어요?",en:"What do you want to order?"},target:"주문하",options:["to eat","to order (food/items)","to drink"],note:"주문하 + 고 싶어요 — essential restaurant phrase; 주문하다 is a 하다 verb"},{kind:"guess",word:{ko:"이해하다",romanization:"ihaehada",en:"to understand",pos:"verb",nuance:"이해하다 is Sino-Korean: 理解 means 'untie/loosen (解) the logic (理)', so it pictures a tangled idea coming apart in your head — it covers both intellectual comprehension AND emotional sympathy ('I understand how you feel'). The dividing line versus 알다 is crucial: 알다 is to KNOW a fact ('I know his name', 이름을 알아요), while 이해하다 is to make sense of WHY or HOW something works. As a 하다-verb it conjugates regularly (이해해요, past 이해했어요). The big English-speaker pitfall is the particle in the negative: 'I don't understand' is almost always 이해가 안 돼요 (subject 가 + 되다, lit. 'understanding doesn't form'), not the literal 이해를 안 해요, which sounds like you're refusing to understand on purpose. Also resist translating 'understand my feelings' as 내 감정 — Koreans say 내 마음을 이해하다."},sentence:{ko:"아직 한국어를 다 이해할 수 없어요.",en:"I can't understand all Korean yet."},target:"이해할",options:["to eat","to drink","to understand"],note:"이해하다 → 이해할 수 없어요 — a humble and accurate self-assessment for language learners"},{kind:"guess",word:{ko:"못",romanization:"mot",en:"cannot (inability marker, pre-verb)",pos:"adverb",nuance:"못은 망치로 벽이나 나무에 두드려 박는 금속 핀입니다. 같은 도구류라도 '못'은 두드려서 고정하고 '나사(screw)'는 돌려서 고정한다는 점이 핵심 차이라, 못에는 '박다/빼다', 나사에는 '조이다/풀다'를 씁니다. 영어 화자가 잘 틀리는 점은 두 가지입니다. 첫째, 'put a nail in'을 직역해 '못을 넣다'라고 하기 쉬운데, 못은 '넣다(put in)'가 아니라 '박다(drive in)'와 어울립니다. 둘째, 부정 부사 '못'(못 가요 = can't go)과 글자가 똑같아 헷갈리지만, 명사 못은 '못이, 못을'처럼 조사가 붙고 부사 못은 동사 앞에 홀로 옵니다. 자주 쓰는 짝은 '못을 박다, 못을 빼다, 못 자국, 못이 박히다(get driven in, 피동)'입니다."},sentence:{ko:"오늘은 못 가요. 다음에 갈 수 있어요.",en:"I can't go today. I can go next time."},target:"못",options:["cannot (inability marker, pre-verb)","to eat","to drink"],note:"못 always goes BEFORE the verb. It's not a sentence ending — it's a pre-verb blocker. 못 가요, 못 먹어요, 못 마셔요."}],canDo:"Say what you can't do with V-(으)ㄹ 수 없어요 or 못 + verb",id:"chapter-08-b5",chapterId:"chapter-08",index:4},{kind:"dialogue",title:"대화 Dialogue · 진짜 한국어",cards:[{kind:"chat",setting:"Jihye invites her coworker Minsu to dinner at a Korean BBQ restaurant",lines:[{speaker:"지혜",ko:"민수 씨, 오늘 저녁에 삼겹살 먹고 싶어요?",en:"Minsu, do you want to eat samgyeopsal this evening?",romanization:"Minsu ssi, oneul jeonyeoge samgyeopsal meokgo sipeoyo?"},{speaker:"민수",ko:"네, 먹고 싶어요! 어디에서 먹을 수 있어요?",en:"Yes, I want to eat it! Where can we eat it?",romanization:"Ne, meokgo sipeoyo! Eodieseo meogeul su isseoyo?"},{speaker:"지혜",ko:"회사 근처에 좋은 식당이 있어요. 7시에 갈 수 있어요?",en:"There's a good restaurant near the office. Can you go at 7?",romanization:"Hoesa geuncheoe joeun sikdangi isseoyo. Ilgop sie gal su isseoyo?"},{speaker:"민수",ko:"7시는 좀... 오늘 회의가 있어서 7시까지 못 가요.",en:"7 o'clock is a bit... I have a meeting today so I can't get there by 7.",romanization:"Ilgop sineun jom... oneul hoeuiga isseoseo ilgop sikkaji mot gayo."},{speaker:"지혜",ko:"그럼 8시는요? 기다릴 수 있어요.",en:"Then how about 8 o'clock? I can wait.",romanization:"Geureom yeodeol-ssineun-yo? Gidaril su isseoyo."},{speaker:"민수",ko:"고마워요! 그런데 저는 너무 매운 것은 못 먹어요.",en:"Thank you! But I can't eat things that are too spicy.",romanization:"Gomawoyo! Geureonde jeoneun neomu maeun geoseun mot meogeoyo."},{speaker:"지혜",ko:"괜찮아요. 거기서 맵지 않은 것도 먹을 수 있어요.",en:"That's okay. You can also eat non-spicy things there.",romanization:"Gwaenchanayo. Geogieseo maepji aneun geotdo meogeul su isseoyo."},{speaker:"민수",ko:"완전 좋아요! 8시에 식당 앞에서 만나요.",en:"Sounds perfect! Let's meet in front of the restaurant at 8.",romanization:"Wanjeon joayo! Yeodeol sie sikdang apeseo mannayo."}]},{kind:"order",prompt:"Build: 'I cannot eat spicy food.'",tokens:["매운 음식을","못 먹어요"],correct:"매운 음식을 못 먹어요",explanation:"못 before the verb marks inability. 매운 음식 is the thing you cannot eat, so it takes 을."},{kind:"drill",prompt:"누가 한 말일까요? · Who said this?",sentence:"회사 근처에 좋은 식당이 있어요. 7시에 갈 수 있어요?",options:[{text:"민수",ok:!1},{text:"지혜",ok:!0}],explanation:"There's a good restaurant near the office. Can you go at 7?"}],canDo:"Say what you want to do with V-고 싶어요 (가고 싶어요)",id:"chapter-08-b6",chapterId:"chapter-08",index:5},{kind:"reading",title:"읽기 Reading · 단체 채팅방 — 이번 주말에 뭐 할 수 있어요? (Group Chat — What can everyone do this weekend?)",cards:[{kind:"read",title:"단체 채팅방 — 이번 주말에 뭐 할 수 있어요? (Group Chat — What can everyone do this weekend?)",chunks:["지은: 이번 주말에 같이 한강에 가고 싶어요. 다들 어때요? 유진: 저도 가고 싶어요! 토요일에 갈 수 있어요. 다니엘: 저는 토요일에 일이 있어서 못 가요. 일요일은 갈 수 있어요. 지은: 그럼 일요일에 가요!","자전거도 탈 수 있어요? 유진: 저는 자전거를 탈 수 있어요. 재미있겠다! 다니엘: 저는 자전거를 잘 못 타요. 천천히 가도 돼요? 지은: 물론이죠! 천천히 갈 수 있어요."],translation:`Jieun: I want to go to the Han River together this weekend. What does everyone think?
Yujin: I want to go too! I can go on Saturday.
Daniel: I have work on Saturday so I can't go. I can go on Sunday.
Jieun: Then let's go on Sunday! Can you also ride bikes?
Yujin: I can ride a bike. That sounds fun!
Daniel: I can't ride a bike well. Is it okay if we go slowly?
Jieun: Of course! We can go slowly.`,qas:[{q:"Why can't Daniel go on Saturday?",a:"일이 있어서 못 가요 — he has work, so something is blocking him (못 = locked door)."},{q:"What does Daniel say about bike riding, and how does he express it?",a:"자전거를 잘 못 타요 — he can't ride a bike well. He uses 못 before 타요 (ride) to express inability. 잘 못 = 'not well' (not exactly the same as 전혀 못 = 'can't at all')."},{q:"Find every instance of 고 싶어요, ㄹ/을 수 있어요, and 못 in the text. For each one, identify which grammar pattern it is and explain why that specific pattern is used instead of the others.",a:"고 싶어요 (desire): 한강에 가고 싶어요 (Jieun wants to go — her desire), 저도 가고 싶어요 (Yujin shares the desire). | 수 있어요 (ability/possibility): 토요일에 갈 수 있어요 (Yujin: the door is open Saturday), 일요일은 갈 수 있어요 (Daniel: Sunday door is open), 자전거도 탈 수 있어요? (is the door open for biking?), 자전거를 탈 수 있어요 (Yujin: yes, open door), 천천히 갈 수 있어요 (the slow pace is possible). | 못 (inability): 토요일에 못 가요 (Daniel: work blocks Saturday — locked door), 자전거를 잘 못 타요 (Daniel: skill gap blocks him)."}]},{kind:"order",prompt:"지문 문장을 다시 조립하세요 · Rebuild a line from the passage (이번 시작 · Start with 이번.)",tokens:["이번","주말에","같이","한강에","가고","싶어요."],correct:"이번 주말에 같이 한강에 가고 싶어요.",explanation:""}],canDo:"Say what you're able to do with V-(으)ㄹ 수 있어요",id:"chapter-08-b7",chapterId:"chapter-08",index:6},{kind:"boss",title:"보스 Boss bite · 다 걸어요",cards:[{kind:"drill",prompt:"You want to say 'I can speak a little Korean.' Which is correct?",sentence:null,options:[{text:"한국어를 조금 말하고 싶어요.",ok:!1},{text:"한국어로 조금 말할 수 있어요.",ok:!0},{text:"한국어를 조금 못 말해요.",ok:!1}],explanation:"한국어로 marks the language used as the means of speaking, and 말할 수 있어요 = ability/capability (open door). Option A (말하고 싶어요) = 'I want to speak Korean' — desire, not ability. Option C (못 말해요) = 'I can't speak Korean' — the opposite of what you want to say."},{kind:"drill",prompt:"Your Korean friend says '술 마시고 싶어요?' You can't drink alcohol. What's the most natural reply?",sentence:null,options:[{text:"아니요, 술을 마시고 싶지 않아요.",ok:!1},{text:"아니요, 저는 술을 못 마셔요.",ok:!0},{text:"아니요, 술을 마실 수 없어요.",ok:!1}],explanation:"못 마셔요 is the most natural, socially smooth way to decline — it signals inability/circumstances rather than personal rejection, which is more polite in Korean culture. 마시고 싶지 않아요 (don't want to) sounds blunt. 마실 수 없어요 is grammatically fine but sounds formal/stiff in casual conversation. 못 마셔요 is the everyday go-to for dietary or health limitations."},{kind:"drill",prompt:"한국어___ 조금 말할 수 있어요. (I can speak a little Korean.)",sentence:null,options:[{text:"를",ok:!0},{text:"가",ok:!1},{text:"에",ok:!1}],explanation:"한국어 is what you speak, so it takes the object marker 를. 가 would make Korean the subject, which changes the sentence logic."}],canDo:"Say what you can't do with V-(으)ㄹ 수 없어요 or 못 + verb",id:"chapter-08-b8",chapterId:"chapter-08",index:7}]},{id:"chapter-09",number:9,title:"V아/어 주세요 vs V아/어도 돼요? · V지 마세요 & V아/어야 돼요",goal:"Ask someone to do something with V아/어 주세요 (please do)",biteCount:8,bites:[{kind:"words",title:"단어 Words 1 · 도와주다~",cards:[{kind:"guess",word:{ko:"도와주다",romanization:"dowajuda",en:"to help",pos:"verb",nuance:"도와주다 means 'to help (for someone's benefit)' and is built from 돕다 ('to help') + 주다 ('to give'), so the 주다 already bakes in the warm sense of doing the help for another person. The base 돕다 is a ㅂ-irregular (돕 + 아요 → 도와요), which is why the compound surfaces as 도와- and the polite present is 도와줘요, past 도와줬어요. The person helped takes the object marker 을/를: 친구를 도와줘요. The most useful register fact is the request form: because 주다 is inside the verb, 'please help me' is simply 도와주세요 — adding a second giving verb to make 도와줘 주세요 is redundant and wrong. Contrast plain 돕다 (which feels more neutral/written, 어려운 이웃을 돕다 'help a struggling neighbor') with 도와주다 (the warm, conversational everyday form). The English-speaker pitfall is exactly that double 주세요, plus marking the helped person with 에게 by analogy to 'give to' — but help is done to a person directly, so it is 저를 도와줘요, not 저에게 도와줘요."},sentence:{ko:"도와주세요!",en:"Please help me!"},target:"도와주",options:["to take (a photo) / to stamp","to sit","to help"],note:"주다 (give) fused into a request — asking someone to give you the action of helping"},{kind:"guess",word:{ko:"사진",romanization:"sajin",en:"photo / picture",pos:"noun",nuance:"사진 is usually paired with 찍다 for taking photos."},sentence:{ko:"사진 찍어도 돼요?",en:"May I take a photo?"},target:"사진",options:["admission ticket","food","photo / picture"],note:"사진 as object — permission asked using 도 돼요?"},{kind:"guess",word:{ko:"찍다",romanization:"jjikda",en:"to take (a photo) / to stamp",pos:"verb"},sentence:{ko:"여기서는 사진을 찍지 마세요.",en:"Please do not take photos here."},target:"찍지",options:["to take (a photo) / to stamp","to help","to sit"],note:"찍지 마세요 = RED X SIGN — prohibition on the action of taking photos"},{kind:"guess",word:{ko:"앉다",romanization:"anda",en:"to sit",pos:"verb",nuance:"앉아 주세요 is a polite request; 앉으세요 is also common and a little more direct."},sentence:{ko:"여기 앉아도 돼요?",en:"May I sit here?"},target:"앉아",options:["to help","to take (a photo) / to stamp","to sit"],note:"앉아도 돼요? — vowel ending stem: 앉 + 아도 돼요?"},{kind:"guess",word:{ko:"들어가다",romanization:"deureogada",en:"to go in / enter",pos:"verb",nuance:"들어가다 combines 들다 (to enter) + 가다 (to go), so it literally means 'enter-and-go' — to move into an enclosed space in a direction AWAY from where the speaker stands. The crucial paired contrast is 들어가다 vs 들어오다: 들어오다 ('enter-and-come') is the same entering motion but TOWARD the speaker. So if you are inside a room and want someone to come in, you say 들어오세요 (come in), but if you are heading into a room over there, you 들어가요. English 'go in / come in' splits the same way, yet learners default to 들어가다 for both and tell a guest at their own door 들어가세요, which oddly means 'go away in / head on home'. Beyond the literal, 들어가다 idiomatically means to get home (집에 들어가다), to enter a school or job (대학·회사에 들어가다), and even 'to fit' (이 옷이 가방에 안 들어가요). It is a plain native compound, regular, neutral register. The destination takes 에 or 안에 (방에/방 안에 들어가다). Common collocations: 방·집에 들어가다, 학교·회사에 들어가다, 안으로 들어가다, 잘 안 들어가다(won't fit)."},sentence:{ko:"들어가도 돼요?",en:"May I go in?"},target:"들어가",options:["to help","to take (a photo) / to stamp","to go in / enter"],note:"가 + 아도 → 가도 is absorbed into 들어가도 — entering is checked with permission form"},{kind:"guess",word:{ko:"열다",romanization:"yeolda",en:"to open",pos:"verb",nuance:"열다 is ㄹ irregular in some formal forms: 엽니다. Memorize 열어요 first."},sentence:{ko:"창문 좀 열어 주세요.",en:"Please open the window a bit."},target:"열어",options:["to open","to help","to take (a photo) / to stamp"],note:"열다 + 어 주세요 — asking someone else to perform the opening action"},{kind:"payoff",line:{speaker:"지훈",ko:"소라 씨, 저 사진 찍어도 돼요?",en:"Sora, may I take a photo?"},hl:"사진"}],canDo:"Ask someone to do something for you with V아/어 주세요 (도와주세요)",id:"chapter-09-b1",chapterId:"chapter-09",index:0},{kind:"pattern",title:"문법 Grammar · V아/어 주세요 vs V아/어도 돼요?",cards:[{kind:"hunt",name:"V아/어 주세요 vs V아/어도 돼요?",sub:"Asking Someone to DO vs Asking IF You May",lines:[{tokens:[{pre:"천천히",mid:"",post:"",hit:!1},{pre:"말해",mid:"",post:"",hit:!1},{pre:"",mid:"주세요",post:".",hit:!0}],ko:"천천히 말해 주세요.",en:"Please speak slowly (for me).",romanization:"cheoncheonhi malhae juseyo."},{tokens:[{pre:"여기",mid:"",post:"",hit:!1},{pre:"앉",mid:"아도",post:"",hit:!0},{pre:"",mid:"돼요",post:"?",hit:!0}],ko:"여기 앉아도 돼요?",en:"Is it okay if I sit here?",romanization:"yeogi anjado dwaeyo?"}],rule:{name:"V아/어 주세요 vs V아/어도 돼요?",rows:[{when:"Stem's last vowel is ㅏ or ㅗ (bright)",add:"stem + 아 주세요 / 아도 돼요?",ex:"받다 → 받아 주세요 (please take it) · 앉다 → 앉아도 돼요? (may I sit?)"},{when:"Stem's last vowel is anything else (dark)",add:"stem + 어 주세요 / 어도 돼요?",ex:"읽다 → 읽어 주세요 (please read it) · 먹다 → 먹어도 돼요? (may I eat?)"},{when:"하다 verbs",add:"하 → 해 + 주세요 / 도 돼요?",ex:"말하다 → 말해 주세요 (please say it) · 전화하다 → 전화해도 돼요? (may I call?)"},{when:"Stem ends in ㅡ (the ㅡ drops)",add:"ㅡ → 어/아 form, then attach",ex:"쓰다 → 써 주세요 (please write it) · 끄다 → 꺼도 돼요? (may I turn it off?)"}]},more:{func:"Use V아/어 주세요 to politely ask someone to DO something for you ('please do X'). Use V아/어도 돼요? to ask whether YOU are allowed to do something ('is it okay if I do X?'). One asks the listener to act; the other asks the listener for permission.",funcLead:"Use V아/어 주세요 to politely ask someone to DO something for you ('please do X').",keyPoint:{label:"주세요 + noun vs 아/어 주세요 + verb",body:"주세요 alone follows a NOUN to ask for the thing: 물 주세요 (water, please), 메뉴 주세요 (the menu, please). To ask someone to DO an action, the verb must take its 아/어 form first: 도와주세요 (please help), 기다려 주세요 (please wait). Beginners often stick a plain dictionary verb in front of 주세요 (돕다 주세요 is wrong; 도와주세요 is right) — change the verb to its 아/어 form first."},pronunciation:"돼 is one syllable with a single [dwae] glide. 돼요 has two syllables, 돼-요 [dwae-yo] — keep 돼 together, then give 요 its own light beat.",pitfall:{wrong:"여기 앉아 주세요? (when you mean 'May I sit here?')",right:"여기 앉아도 돼요?",explanation:"English uses 'can/may' for both 'please do this' and 'may I do this,' so learners mix the two Korean forms. 앉아 주세요 means 'please sit (for me)' — you're telling THEM to sit. To ask permission for yourself, add 도 돼요?: 앉아도 돼요? Remember: 아/어 주세요 = you act; 아/어도 돼요? = I'm allowed."}}},{kind:"drill",prompt:"Can I take a photo?",sentence:"사진 찍___?",options:[{text:"주세요",ok:!1},{text:"아도 돼요",ok:!1},{text:"어도 돼요",ok:!0}],explanation:"찍다 has ㅣ (dark), so 찍어 + 도 돼요? Said with rising intonation, it's a real permission question."},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "Please speak slowly (for me)."',tokens:["천천히","말해","주세요."],correct:"천천히 말해 주세요.",explanation:""},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "Is it okay if I sit here?"',tokens:["여기","앉아도","돼요?"],correct:"여기 앉아도 돼요?",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"여기 앉아도 돼요?",ok:!0},{text:"여기 앉아 주세요? (when you mean 'May I sit here?')",ok:!1}],explanation:"English uses 'can/may' for both 'please do this' and 'may I do this,' so learners mix the two Korean forms. 앉아 주세요 means 'please sit (for me)' — you're telling THEM to sit. To ask permission for yourself, add 도 돼요?: 앉아도 돼요? Remember: 아/어 주세요 = you act; 아/어도 돼요? = I'm allowed."}],canDo:"Ask someone to do something for you with V아/어 주세요 (도와주세요)",id:"chapter-09-b2",chapterId:"chapter-09",index:1},{kind:"words",title:"단어 Words 2 · 닫다~",cards:[{kind:"guess",word:{ko:"닫다",romanization:"datda",en:"to close",pos:"verb",nuance:"닫다 is the opposite of 열다. Use it for doors, windows, stores, apps, and lids."},sentence:{ko:"문 닫아 주세요.",en:"Please close the door."},target:"닫아",options:["to help","to close","to take (a photo) / to stamp"],note:"닫다 + 아 주세요 — the ㄷ stem is regular here; asking another person to close it"},{kind:"guess",word:{ko:"말하다",romanization:"malhada",en:"to speak / say",pos:"verb",nuance:"Use 로 for language: 한국어로 말해요, 영어로 말해요. 말하다 can mean both “speak” and “say,” so the object or quote decides the English translation."},sentence:{ko:"천천히 말해 주세요.",en:"Please speak slowly."},target:"말해",options:["to help","to take (a photo) / to stamp","to speak / say"],note:"말하다 + 여 주세요 → 말해 주세요 — classic classroom and daily-life request"},{kind:"guess",word:{ko:"기다리다",romanization:"gidarida",en:"to wait",pos:"verb",nuance:"기다려 주세요 is one of the most useful service and classroom requests."},sentence:{ko:"잠깐 기다려 주세요.",en:"Please wait a moment."},target:"기다려",options:["to help","to take (a photo) / to stamp","to wait"],note:"기다리다 + 어 주세요 — 리 contracts to 려; asking someone to hold on"},{kind:"guess",word:{ko:"뛰다",romanization:"ttwida",en:"to run",pos:"verb",nuance:"뛰다 is a regular verb whose stem ends in the vowel 위, so it simply adds 어 without contracting: 뛰어요, 뛰었어요. Before the formal ㅂ/ㄴ endings the stem shortens in the usual way to 뜁니다 and 뛸 거예요. Its key synonym is 달리다: 달리다 is the neutral, 'sporty' word for running over distance (마라톤을 달리다, 100미터를 달리다), while 뛰다 is the everyday word for dashing, rushing, or even jumping, so a child rushing across a room 뛰어다녀요 rather than 달려다녀요. Crucially 뛰다 also means 'to jump/leap' (제자리에서 뛰다 = jump in place; 심장이 뛰다 = the heart beats/pounds), so context decides between 'run' and 'jump'. The English-speaker pitfall is spelling: don't confuse 뛰다 (run) with 띄다 ('be visible / catch the eye', as in 눈에 띄다) — they sound close but are different verbs. Also note the polite-warning 뛰지 마세요 is the fixed phrase you'll see posted everywhere."},sentence:{ko:"복도에서 뛰지 마세요.",en:"Please do not run in the hallway."},target:"뛰지",options:["to help","to take (a photo) / to stamp","to run"],note:"뛰다 + 지 마세요 — common school/museum prohibition sign"},{kind:"guess",word:{ko:"걱정하다",romanization:"geokjeonghada",en:"to worry",pos:"verb",nuance:"걱정하다 (걱정 = 'worry/anxiety' + 하다) is the everyday verb for being anxious or concerned about someone or something. Distinguish it sharply from 고민하다: 걱정하다 is feeling ANXIOUS about how things will turn out ('I'm worried about my grades'), whereas 고민하다 is actively DELIBERATING over a hard choice ('I'm agonizing over which job to take'). As a 하다-verb it splits in the negative — 걱정 안 해요 (separating the noun) or 걱정하지 않아요 — and the favor form 걱정해 주다 means 'to worry on someone's behalf', a kind gesture. The natural way to say 'I feel worried' is 걱정이 돼요 (걱정 + 이 + 되다), not 걱정을 해요, which sounds like deliberate worrying. The single most useful phrase in the whole language family is 걱정하지 마세요 ('don't worry') — memorize it. English 'I'm worried about you' is 네가 걱정돼 or 너를 걱정해, not 너에 대해 걱정해."},sentence:{ko:"걱정하지 마세요.",en:"Please do not worry."},target:"걱정하",options:["to worry","to help","to take (a photo) / to stamp"],note:"지 마세요 used not as a rule sign but as warm reassurance between people"},{kind:"guess",word:{ko:"가야 해요",romanization:"gaya haeyo",en:"have to go / must go",pos:"pattern"},sentence:{ko:"지금 가야 해요. 늦었어요.",en:"I have to go now. I'm late."},target:"가야 해요",options:["to help","have to go / must go","photo / picture"],note:"가다 + 아야 해요 — MUST-DO CHECKLIST: non-negotiable obligation"}],canDo:"Ask or give permission with V아/어도 돼요? (앉아도 돼요?)",id:"chapter-09-b3",chapterId:"chapter-09",index:2},{kind:"pattern",title:"문법 Grammar · V지 마세요 & V아/어야 돼요",cards:[{kind:"hunt",name:"V지 마세요 & V아/어야 돼요",sub:"Telling Someone Not To, and Saying You Have To",lines:[{tokens:[{pre:"여기에서",mid:"",post:"",hit:!1},{pre:"담배를",mid:"",post:"",hit:!1},{pre:"피우",mid:"지",post:"",hit:!0},{pre:"",mid:"마세요",post:".",hit:!0}],ko:"여기에서 담배를 피우지 마세요.",en:"Please don't smoke here.",romanization:"yeogieseo dambaereul piuji maseyo."},{tokens:[{pre:"내일",mid:"",post:"",hit:!1},{pre:"일찍",mid:"",post:"",hit:!1},{pre:"일어나야",mid:"",post:"",hit:!1},{pre:"",mid:"돼요",post:".",hit:!0}],ko:"내일 일찍 일어나야 돼요.",en:"I have to get up early tomorrow.",romanization:"naeil iljjik ireonaya dwaeyo."}],rule:{name:"V지 마세요 & V아/어야 돼요",rows:[{when:"Prohibition: any verb stem",add:"stem + 지 마세요",ex:"들어가다 → 들어가지 마세요 (don't go in) · 먹다 → 먹지 마세요 (don't eat it)"},{when:"Have to: stem vowel ㅏ/ㅗ",add:"stem + 아야 돼요",ex:"가다 → 가야 돼요 (have to go) · 자다 → 자야 돼요 (have to sleep)"},{when:"Have to: other stem vowels",add:"stem + 어야 돼요",ex:"먹다 → 먹어야 돼요 (have to eat) · 기다리다 → 기다려야 돼요 (have to wait)"},{when:"하다 verbs (have to)",add:"하 → 해 + 야 돼요",ex:"공부하다 → 공부해야 돼요 (have to study) · 일하다 → 일해야 돼요 (have to work)"}]},more:{func:"Use V지 마세요 to politely tell someone NOT to do something ('please don't do X'). Use V아/어야 돼요 to say something must be done ('have to do X'). Together they cover both sides of a rule: what's not allowed and what's required.",funcLead:"Use V지 마세요 to politely tell someone NOT to do something ('please don't do X').",keyPoint:{label:"지 마세요 (don't!) vs 안 + verb (doesn't/isn't)",body:"지 마세요 is a COMMAND telling someone NOT to do something: 뛰지 마세요 (don't run). It is not how you say YOU don't do something — for that, use 안: 저는 안 뛰어요 (I don't run). So 지 마세요 is only for telling other people what not to do."},pronunciation:"In 먹어야 the ㄱ links into the next vowel, so it flows as [meo-geo-ya], one smooth piece rather than 먹+어야.",pitfall:{wrong:"먹지 않으세요 (when you mean 'please don't eat it')",right:"먹지 마세요",explanation:"Learners build prohibition from the negative 지 않다 ('does not'), getting 먹지 않으세요, which sounds like an odd statement, not a command. Negative commands ('don't') use the special verb 말다: 먹지 마세요. Keep 안 먹어요 / 먹지 않아요 ('I don't eat it') for plain negatives, and 지 마세요 for telling someone not to do it."}}},{kind:"drill",prompt:"Please don't take photos.",sentence:"사진을 찍___.",options:[{text:"지 마세요",ok:!0},{text:"돼요",ok:!1},{text:"어야 돼요",ok:!1}],explanation:"찍다 → 찍 + 지 마세요. A common sign you'll see; the form is the same no matter the final consonant."},{kind:"drill",prompt:"I have to take the medicine.",sentence:"약을 먹___.",options:[{text:"어야 돼요",ok:!0},{text:"지 마세요",ok:!1}],explanation:"먹다 (dark vowel) → 먹어 + 야 돼요. In Korean you 'eat' (먹다) medicine, not 'take' it."},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "Please don't smoke here." (여기에서 시작 · Start with 여기에서.)`,tokens:["여기에서","담배를","피우지","마세요."],correct:"여기에서 담배를 피우지 마세요.",explanation:""},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "I have to get up early tomorrow."',tokens:["내일","일찍","일어나야","돼요."],correct:"내일 일찍 일어나야 돼요.",explanation:""}],canDo:"Ask or give permission with V아/어도 돼요? (앉아도 돼요?)",id:"chapter-09-b4",chapterId:"chapter-09",index:3},{kind:"words",title:"단어 Words 3 · 좀~",cards:[{kind:"guess",word:{ko:"좀",romanization:"jom",en:"a bit / please (softener)",pos:"adverb",nuance:"좀 is the contracted, spoken form of 조금 and is everywhere in daily conversation. Its key second life — the part that trips up English speakers — is as a request softener: in 물 좀 주세요 or 좀 도와주세요, 좀 is not measuring a 'little' amount at all but functioning like 'please/if you would', taking the bluntness off a command. So 물 주세요 is grammatically fine but can feel abrupt, whereas 물 좀 주세요 sounds warm and natural. Compared with the full 조금, 좀 is purely conversational and a touch more casual; in formal writing or stiff announcements you revert to 조금 or a fuller polite request form. Collocates constantly with request verbs (좀 주세요, 좀 해 주세요, 좀 보여 주세요) and with mild complaints (좀 춥다, 좀 그렇다). The pitfall is over-literal reading: don't try to translate the 'softener' 좀 as 'a little', and don't drop it from requests — Koreans add it precisely to sound polite."},sentence:{ko:"좀 도와주세요.",en:"Please help me (softened)."},target:"좀",options:["to help","photo / picture","a bit / please (softener)"],note:"좀 before a request softens it — like 'kindly' or 'if you could'; almost always present in polite Korean requests"},{kind:"guess",word:{ko:"죄송하지만",romanization:"joesonghajiman",en:"I'm sorry but / I apologize but",pos:"conjunction"},sentence:{ko:"죄송하지만 여기서 음식을 드시면 안 돼요.",en:"I'm sorry but you cannot eat here."},target:"죄송하지만",options:["I'm sorry but / I apologize but","to help","photo / picture"],note:"죄송하지만 softens a refusal or prohibition — staff use this before giving bad news"},{kind:"guess",word:{ko:"입장권",romanization:"ipjanggwon",en:"admission ticket",pos:"noun",nuance:"입장권 is the ticket that lets you ENTER a venue — a museum, park, exhibition, or show. The hanja 入場券 is 入 (enter) + 場 (place/venue) + 券 (ticket), literally an 'enter-the-venue ticket'. Distinguish it sharply from 표 and 티켓: 표 is the everyday word for transport tickets (기차표 train ticket, 버스표), 티켓 (loanword) is common for concerts and movies, while 입장권 specifically grants entry to a place. The natural verbs are 입장권을 사다 and the idiomatic 입장권을 끊다 ('cut a ticket', a fixed expression for buying one), plus 예매하다 to book ahead. Count them with the flat-object counter 장: 입장권 한 장. English-speaker pitfall: don't default to 표 for a museum entry — a train ticket is 표/기차표, but entrance to a venue is the 입장권."},sentence:{ko:"입장권을 보여줘야 해요.",en:"You have to show your admission ticket."},target:"입장권",options:["photo / picture","admission ticket","food"],note:"입장권 + 어야 해요 — obligation before entry at museums and event spaces"},{kind:"guess",word:{ko:"음식",romanization:"eumsik",en:"food",pos:"noun",nuance:"음식 is the general word for food or cuisine. It combines naturally with Korean, spicy, delicious, and eat."},sentence:{ko:"여기서 음식을 먹지 마세요.",en:"Please do not eat food here."},target:"음식",options:["food","photo / picture","admission ticket"],note:"Common museum/gallery prohibition — 지 마세요 as RED X SIGN"},{kind:"guess",word:{ko:"만지다",romanization:"manjida",en:"to touch",pos:"verb",nuance:"만지다 is the plain verb for touching something with your hand to feel its texture, temperature, or shape; the thing touched takes 을/를 (천을 만지다). The 요-form is regular: stem 만지- + -어요 contracts 지+어 into 져, giving 만져요 / past 만졌어요. The nearest neighbor is 건드리다, but the dividing line is intent: 만지다 is neutral, even affectionate exploration ('feel, handle'), while 건드리다 carries 'mess with / disturb / poke' and often a nuisance nuance (남의 물건을 건드리다 = mess with someone's stuff). The classic English-speaker pitfall is reaching for 'touch' emotionally: 'that movie touched me' is NOT 만지다 but 감동받다 / 감동적이다 — 만지다 is strictly physical contact. Also keep 만지다 (touch) apart from the look-alike 만나다 (meet); they share only the first syllable."},sentence:{ko:"전시품을 만지지 마세요.",en:"Please do not touch the exhibits."},target:"만지",options:["to help","to take (a photo) / to stamp","to touch"],note:"만지다 + 지 마세요 — classic museum rule you will definitely encounter"},{kind:"payoff",line:{speaker:"직원",ko:"죄송하지만 이 구역에서는 사진 찍지 마세요. 저쪽은 괜찮아요.",en:"I'm sorry, but please do not take photos in this section. That area over there is fine."},hl:"죄송하지만"}],canDo:"Tell someone not to do something with V지 마세요 (찍지 마세요)",id:"chapter-09-b5",chapterId:"chapter-09",index:4},{kind:"dialogue",title:"대화 Dialogue · 진짜 한국어",cards:[{kind:"chat",setting:"Jihoon visits a traditional craft museum with his friend Sora. They encounter signs and staff along the way.",lines:[{speaker:"지훈",ko:"소라 씨, 저 사진 찍어도 돼요?",en:"Sora, may I take a photo?",romanization:"Sora ssi, jeo sajin jjigeodo dwaeyo?"},{speaker:"소라",ko:"저도 잘 모르겠어요. 직원한테 물어봐요.",en:"I'm not sure either. Let's ask a staff member.",romanization:"Jeodo jal moreugesseoyo. Jigwonhante mureobwayo."},{speaker:"지훈",ko:"저기요! 여기서 사진 찍어도 돼요?",en:"Excuse me! May I take photos here?",romanization:"Jeogiyo! Yeogiseo sajin jjigeodo dwaeyo?"},{speaker:"직원",ko:"죄송하지만 이 구역에서는 사진 찍지 마세요. 저쪽은 괜찮아요.",en:"I'm sorry, but please do not take photos in this section. That area over there is fine.",romanization:"Joesonghajiman i guyeogeseoneun sajin jjikji maseyo. Jeotjjogeun gwaenchanayo."},{speaker:"소라",ko:"알겠어요. 그리고 저 전시품 만져도 돼요?",en:"Got it. And may I touch that exhibit?",romanization:"Algesseoyo. Geurigo jeo jeonsipum manjyeodo dwaeyo?"},{speaker:"직원",ko:"아니요, 만지지 마세요. 그리고 음식도 안에서 드시면 안 돼요.",en:"No, please do not touch them. And food is also not allowed inside.",romanization:"Aniyo, manjiji maseyo. Geurigo eumsikdo aneseo deusimyeon an dwaeyo."},{speaker:"지훈",ko:"감사합니다. 소라 씨, 저기 사진 구역에서 사진 찍어 주세요!",en:"Thank you. Sora, please take a photo of me in that photo zone!",romanization:"Gamsahamnida. Sora ssi, jeogi sajin guyeogeseo sajin jjigeo juseyo!"},{speaker:"소라",ko:"네, 찍어 줄게요! 여기 서 보세요.",en:"Sure, I'll take it for you! Try standing here.",romanization:"Ne, jjigeo julgeyo! Yeogi seo boseyo."}]},{kind:"order",prompt:"Build: 'Please do not touch this.'",tokens:["이것을","만지지 마세요"],correct:"이것을 만지지 마세요",explanation:'-지 마세요 is the polite "please do not" form. 이것 is the thing being touched, so 이것을 comes before the verb.'},{kind:"drill",prompt:"누가 한 말일까요? · Who said this?",sentence:"아니요, 만지지 마세요. 그리고 음식도 안에서 드시면 안 돼요.",options:[{text:"지훈",ok:!1},{text:"직원",ok:!0}],explanation:"No, please do not touch them. And food is also not allowed inside."},{kind:"drill",prompt:'무엇이 들어갈까요? · "Sora, may I take a photo?"',sentence:"소라 씨, 저 ___ 찍어도 돼요?",options:[{text:"입장권",ok:!1},{text:"음식",ok:!1},{text:"사진",ok:!0}],explanation:""}],canDo:"Ask someone to do something for you with V아/어 주세요 (도와주세요)",id:"chapter-09-b6",chapterId:"chapter-09",index:5},{kind:"reading",title:"읽기 Reading · 국립 한국 문화 박물관 관람 안내 (National Korean Culture Museum Visitor Guide)",cards:[{kind:"read",title:"국립 한국 문화 박물관 관람 안내 (National Korean Culture Museum Visitor Guide)",chunks:["박물관에 오신 것을 환영합니다. 즐거운 관람을 위해 다음 사항을 지켜 주세요. 전시실 내에서는 사진을 찍지 마세요. 전시품은 만지지 마세요. 음식이나 음료는 드시면 안 됩니다.","어린이는 보호자와 함께해야 해요. 박물관 안에서는 조용히 해 주세요. 입장 전에 가방을 검사받아야 해요. 궁금한 것이 있으면 직원한테 물어보세요."],translation:"Welcome to the museum. Please observe the following for an enjoyable visit. Please do not take photos inside the exhibition hall. Please do not touch the exhibits. You may not eat food or drink beverages. Children must be accompanied by a guardian. Please be quiet inside the museum. You must have your bag inspected before entering. If you have any questions, please ask a staff member.",qas:[{q:"What two things does the notice say you must NOT do with exhibits?",a:"사진을 찍지 마세요 (do not take photos) and 전시품은 만지지 마세요 (do not touch the exhibits)"},{q:"What must children do according to the notice?",a:"보호자와 함께해야 해요 — children must be with a guardian (해야 해요 = must/have to)"},{q:"Find all 지 마세요 and 아/어야 해요 forms in the text. For each one, say whether it is a prohibition (RED X SIGN) or an obligation (MUST-DO CHECKLIST), and explain why that form is used rather than the other.",a:"지 마세요 forms (RED X SIGN — stopping an action): 찍지 마세요 (don't take photos — prohibition on visitor action), 만지지 마세요 (don't touch — prohibition). 아/어야 해요 forms (MUST-DO CHECKLIST — requiring an action): 함께해야 해요 (children must be with guardian — positive obligation), 검사받아야 해요 (must have bag inspected — required step). The distinction is key: 지 마세요 blocks an action the visitor might want to do; 아/어야 해요 requires an action the visitor must perform."}]},{kind:"drill",prompt:"지문에서 뭐라고 했어요? · What did the passage say?",sentence:"전시실 내에서는 ___을 찍지 마세요.",options:[{text:"입장권",ok:!1},{text:"사진",ok:!0},{text:"도와주다",ok:!1}],explanation:""},{kind:"drill",prompt:"지문에서 뭐라고 했어요? · What did the passage say?",sentence:"___이나 음료는 드시면 안 됩니다.",options:[{text:"입장권",ok:!1},{text:"도와주다",ok:!1},{text:"음식",ok:!0}],explanation:""}],canDo:"Ask or give permission with V아/어도 돼요? (앉아도 돼요?)",id:"chapter-09-b7",chapterId:"chapter-09",index:6},{kind:"boss",title:"보스 Boss bite · 다 걸어요",cards:[{kind:"drill",prompt:"A museum staff member walks up and says something. Which sentence means 'Please do not run in the hallway'?",sentence:null,options:[{text:"복도에서 뛰어도 돼요?",ok:!1},{text:"복도에서 뛰지 마세요.",ok:!0},{text:"복도에서 뛰어야 해요.",ok:!1}],explanation:"뛰지 마세요 = RED X SIGN — prohibition. 뛰어도 돼요? is a permission question (may I run?). 뛰어야 해요 is an obligation (you have to run). Only 지 마세요 delivers the prohibition instruction you see on signs."},{kind:"drill",prompt:"Your friend says '가지 마세요!' and you reply that you must go. What do you say?",sentence:null,options:[{text:"네, 가지 않아도 돼요.",ok:!1},{text:"미안해요, 가야 해요.",ok:!0},{text:"미안해요, 가지 마세요.",ok:!1}],explanation:"가야 해요 = MUST-DO CHECKLIST — I have to go, it's an obligation. 가지 않아도 돼요 means 'I don't have to go' (no obligation), which contradicts your intention. 가지 마세요 would mean 'please don't go' — you'd be repeating your friend's prohibition back to them."},{kind:"drill",prompt:"사진___ 찍어도 돼요? (May I take a photo?)",sentence:null,options:[{text:"을",ok:!0},{text:"이",ok:!1},{text:"에",ok:!1}],explanation:"사진 is what you take, so it takes the object marker 을. 이 would make the photo the subject instead of the object."}],canDo:"Tell someone not to do something with V지 마세요 (찍지 마세요)",id:"chapter-09-b8",chapterId:"chapter-09",index:7}]},{id:"chapter-10",number:10,title:"N부터 / N까지 · V아/어 주세요",goal:"Ask where something is using 이/가 어디예요? and 이/가 있어요?",biteCount:8,bites:[{kind:"words",title:"단어 Words 1 · 화장실~",cards:[{kind:"guess",word:{ko:"화장실",romanization:"hwajangsil",en:"bathroom / restroom",pos:"noun",nuance:"화장실 is the normal public word for bathroom/restroom."},sentence:{ko:"화장실이 어디예요?",en:"Where is the bathroom?"},target:"화장실",options:["subway station","bathroom / restroom","exit"],note:"이 follows consonant-ending 실 — subject particle, not topic particle"},{kind:"guess",word:{ko:"지하철역",romanization:"jihacheollyeok",en:"subway station",pos:"noun"},sentence:{ko:"지하철역까지 얼마나 걸려요?",en:"How long does it take to the subway station?"},target:"지하철역",options:["subway station","bathroom / restroom","exit"],note:"까지 = as far as / to — the end-point of a distance range"},{kind:"guess",word:{ko:"출구",romanization:"chulgu",en:"exit",pos:"noun",nuance:"출구 is 出口 — 出 (go out) + 口 (opening), literally the 'exit-mouth', the way you leave a building or station; in the subway each is numbered (몇 번 출구), so 'meet at exit 7' is everyday Korean. It is the exact opposite of 입구 (入口, entrance), and the shared 口 'opening' character ties the 出/入 pair together. Distinguish 출구 from 비상구 (非常口, 'emergency exit'), the marked fire-escape door — a normal way out is a 출구, the emergency one is a 비상구. To leave through it you say 출구로 나가다, where 으로 marks the exit as your route. English speakers blur 출구 and 입구 because both end in 구; fix the memory with 출 = out, 입 = in. And note exits are counted with the native-Sino number + 번 (삼 번 출구), not with English ordinals."},sentence:{ko:"몇 번 출구예요?",en:"Which exit number is it?"},target:"출구",options:["exit","bathroom / restroom","subway station"],note:"몇 번 = which number — essential for subway navigation"},{kind:"guess",word:{ko:"안내소",romanization:"annaeso",en:"information desk / help desk",pos:"noun",nuance:"안내소 is a place, so use 에 for location and 에서 for asking or receiving help there."},sentence:{ko:"안내소가 어디예요?",en:"Where is the information desk?"},target:"안내소",options:["bathroom / restroom","information desk / help desk","subway station"],note:"A practical travel question when you need staff help, directions, or opening hours"},{kind:"guess",word:{ko:"2호선",romanization:"i hoseon",en:"Line 2 (subway)",pos:"noun",nuance:"Koreans often give subway directions by line number plus exit number or direction."},sentence:{ko:"2호선 타는 곳이 어디예요?",en:"Where is the Line 2 boarding area?"},target:"2호선",options:["Line 2 (subway)","bathroom / restroom","exit"],note:"타는 곳 = the place where you board; more natural than saying the line itself is an exit"},{kind:"guess",word:{ko:"부터",romanization:"buteo",en:"from (starting point)",pos:"particle"},sentence:{ko:"오늘부터 열심히 공부할게요.",en:"I'll study hard starting from today."},target:"부터",options:["bathroom / restroom","subway station","from (starting point)"],note:"부터 attaches to the start-point — 오늘부터 means 'from today onward'"},{kind:"guess",word:{ko:"까지",romanization:"kkaji",en:"to / until / as far as (end point)",pos:"particle"},sentence:{ko:"몇 시까지 열어요?",en:"Until what time are you open?"},target:"까지",options:["to / until / as far as (end point)","bathroom / restroom","subway station"],note:"까지 after a time = 'until' — perfect for asking business hours"},{kind:"payoff",line:{speaker:"지민",ko:"저기요, 화장실이 어디예요?",en:"Excuse me, where is the bathroom?"},hl:"화장실"}],canDo:"Give a time or place range with N부터 N까지 (아홉 시부터 여섯 시까지)",id:"chapter-10-b1",chapterId:"chapter-10",index:0},{kind:"pattern",title:"문법 Grammar · N부터 / N까지",cards:[{kind:"hunt",name:"N부터 / N까지",sub:"from … to … (ranges in time and space)",lines:[{tokens:[{pre:"아홉",mid:"",post:"",hit:!1},{pre:"시",mid:"부터",post:"",hit:!0},{pre:"여섯",mid:"",post:"",hit:!1},{pre:"시",mid:"까지",post:"",hit:!0},{pre:"일해요.",mid:"",post:"",hit:!1}],ko:"아홉 시부터 여섯 시까지 일해요.",en:"I work from nine to six.",romanization:"a-hop si-bu-teo yeo-seot si-kka-ji il-hae-yo."},{tokens:[{pre:"내일",mid:"까지",post:"",hit:!0},{pre:"책을",mid:"",post:"",hit:!1},{pre:"읽어요.",mid:"",post:"",hit:!1}],ko:"내일까지 책을 읽어요.",en:"I'll read the book by tomorrow.",romanization:"nae-il-kka-ji chae-geul il-geo-yo."}],rule:{name:"N부터 / N까지",rows:[{when:"Start point of a range (attaches to any noun)",add:"부터",ex:"아침 → 아침부터 · 한 시 → 한 시부터"},{when:"End point of a range (attaches to any noun)",add:"까지",ex:"저녁 → 저녁까지 · 여섯 시 → 여섯 시까지"},{when:"Place: from here to there",add:"부터 … 까지",ex:"집 → 집부터 · 학교 → 학교까지"},{when:'까지 used alone = a deadline, "by"',add:"까지",ex:"내일 → 내일까지 · 다섯 시 → 다섯 시까지"}]},more:{func:'부터 marks where a range starts and 까지 marks where it ends — "from A to B." They work for time (아홉 시부터 여섯 시까지, from 9 to 6) and for place (집부터 학교까지, from home to school), and each can appear alone too (부터 = "starting from," 까지 = "up until / by").',funcLead:'부터 marks where a range starts and 까지 marks where it ends — "from A to B." They work for time (아홉 시부터 여섯 시까지, from 9 to 6) and for place (집부터 학교까지, from home to…',keyPoint:{label:'부터 vs 에서 (both can mean "from")',body:`For a starting point you measure a stretch from — especially time — use 부터: 아침부터 (from morning). For a physical place you set out from, native speakers usually say 에서: 집에서 학교까지 (from home to school). So time ranges lean on 부터…까지, while place ranges usually use 에서…까지. You'll still hear 집부터 학교까지, so it's not wrong — just know that 에서…까지 is the more common "place-to-place" frame. The full location particle 에서 gets its own chapter; for now just remember: time → 부터, place → often 에서, and 까지 marks the end either way.`},pronunciation:"까지 starts with the tense consonant ㄲ, so keep it crisp — [kka-ji], not a soft [ga-ji]. After a 받침 like ㅂ/ㄱ/ㄷ, 부터 tenses a little: 집부터 sounds like [집뿌터].",pitfall:{wrong:"아홉 시까지 여섯 시부터 일해요. / 집까지 학교부터 멀어요.",right:"아홉 시부터 여섯 시까지 일해요. / 집부터 학교까지 멀어요.",explanation:'English says "from … to …," and learners often reach for 까지 first or swap the two particles. Tie each particle to its meaning, not to word order: 부터 always sits on the START point and 까지 always sits on the END point.'}}},{kind:"drill",prompt:"It's far from home to school.",sentence:"집___ 학교까지 멀어요.",options:[{text:"부터",ok:!0},{text:"까지",ok:!1}],explanation:"Place range with 부터…까지. You'll also often hear 집에서 학교까지 — see the key point below."},{kind:"drill",prompt:"From what time is the movie?",sentence:"몇 시___ 영화를 봐요?",options:[{text:"까지",ok:!1},{text:"주세요",ok:!1},{text:"부터",ok:!0}],explanation:"부터 used alone to ask just the starting time."},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "I work from nine to six." (아홉 시작 · Start with 아홉.)',tokens:["아홉","시부터","여섯","시까지","일해요."],correct:"아홉 시부터 여섯 시까지 일해요.",explanation:""},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "I'll read the book by tomorrow." (내일까지 시작 · Start with 내일까지.)`,tokens:["내일까지","책을","읽어요."],correct:"내일까지 책을 읽어요.",explanation:""}],canDo:"Give a time or place range with N부터 N까지 (아홉 시부터 여섯 시까지)",id:"chapter-10-b2",chapterId:"chapter-10",index:1},{kind:"words",title:"단어 Words 2 · 다시~",cards:[{kind:"guess",word:{ko:"다시",romanization:"dasi",en:"again / once more",pos:"adverb",nuance:"다시 is one of the most useful repair words for learners."},sentence:{ko:"다시 말해 주세요.",en:"Please say it again."},target:"다시",options:["bathroom / restroom","again / once more","subway station"],note:"다시 placed before the verb — it modifies the action (말하다)"},{kind:"guess",word:{ko:"천천히",romanization:"cheoncheonhi",en:"slowly",pos:"adverb",nuance:"천천히 is polite and clear for asking someone to slow down."},sentence:{ko:"천천히 말해 주세요.",en:"Please speak slowly."},target:"천천히",options:["slowly","bathroom / restroom","subway station"],note:"천천히 before 말해 주세요 specifies the speed — add it any time you need less pace"},{kind:"guess",word:{ko:"모르다",romanization:"moreuda",en:"to not know",pos:"verb",nuance:"모르다 is the standalone verb 'to not know / be unaware of', the lexical opposite of 알다, and it likewise takes the object marker 을/를: 길을 몰라요. It is a 르-irregular: when an 아/어 ending attaches, the 르 stem doubles the ㄹ and the vowel drops, so 모르 + 아요 → 몰라요 (never 모르아요) and the past is 몰랐어요. The crucial register tool is 겠: 잘 모르겠어요 ('I'm not quite sure') is markedly softer and more natural than a blunt 몰라요, which can sound curt or even dismissive depending on tone, so Koreans lean on the 겠 form constantly when admitting ignorance politely. Compare 모르다 with 헷갈리다 ('to be confused / mix things up'): 모르다 is having no information at all, while 헷갈리다 is having information but getting it tangled. The English-speaker pitfall is the conjugation — applying a regular pattern to get 모르아요 instead of the irregular 몰라요 — and forgetting that the smooth, courteous version is 잘 모르겠어요."},sentence:{ko:"잘 모르겠어요.",en:"I'm not quite sure."},target:"모르",options:["to walk","to take (time) / to be required","to not know"],note:"잘 모르겠어요 is softer and more natural than just 몰라요 — 겠 adds an element of 'I think / I guess'"},{kind:"guess",word:{ko:"걷다",romanization:"geotda",en:"to walk",pos:"verb",nuance:"걷다 means to walk on foot and is a ㄷ irregular verb: before a vowel ending the final ㄷ softens to ㄹ, so the 요-form is 걸어요 (not 걷어요) and the past is 걸었어요. Before a consonant ending the ㄷ stays put, so the formal form remains 걷습니다 and you say 걷지 마세요, 걷고 싶어요. The nearest relative is 산책하다 ('take a stroll'): 걷다 is the raw act of walking anywhere, while 산책하다 implies a leisurely walk for pleasure, so 'I walk to work' is 걸어서 출근해요, never 산책해서 출근해요. The trap for English speakers is that 걷다 doesn't take an object the way 'walk the dog' does — Korean uses 산책시키다 for that, and the path you walk takes 을/를 (공원을 걸어요), so don't reach for 에. Also remember 걸어서 ('on foot') is one fixed chunk for describing how you travel."},sentence:{ko:"여기서 역까지 걸어요.",en:"I walk from here to the station."},target:null,options:["to walk","to not know","to take (time) / to be required"],note:"걷다 is ㄷ-irregular: 걷 + 어 → 걸어요 (ㄷ changes to ㄹ before a vowel)"},{kind:"guess",word:{ko:"걸리다",romanization:"geollida",en:"to take (time) / to be required",pos:"verb",nuance:"걸리다 is a high-frequency verb that fans out into three everyday senses learners meet fast: (1) time being needed — 시간이 걸리다; (2) catching an illness — 감기에 걸리다; and (3) getting caught/busted — 경찰한테 걸리다, 거짓말이 걸리다. The thread linking them is its origin as the passive of 걸다 ('to hang/hook'): something gets hooked — by time, by sickness, by the law — so 벽에 그림이 걸려 있어요 ('a picture is hung on the wall') is the same word. The number-one English-speaker pitfall is the subject/particle: for 'take time' the *time* is the subject (시간이 걸려요), never 시간을 걸려요; and for illness you must use 에 (감기에 걸리다), not the object 를. Compare 걸리다 ('take/require time') with 들다, which is used for cost/effort/money (돈이 들다) — 시간이 걸리다 vs 돈이 들다 is a pairing Koreans keep distinct. It is a regular ㅣ-stem verb: 걸리 + 어 contracts to 걸려요."},sentence:{ko:"버스로 30분 걸려요.",en:"It takes 30 minutes by bus."},target:"걸려",options:["to not know","to take (time) / to be required","to walk"],note:"얼마나 걸려요? (How long does it take?) is a must-know travel question — 걸리다 expresses time cost"},{kind:"guess",word:{ko:"도와주다",romanization:"dowajuda",en:"to help",pos:"verb",nuance:"도와주다 means 'to help (for someone's benefit)' and is built from 돕다 ('to help') + 주다 ('to give'), so the 주다 already bakes in the warm sense of doing the help for another person. The base 돕다 is a ㅂ-irregular (돕 + 아요 → 도와요), which is why the compound surfaces as 도와- and the polite present is 도와줘요, past 도와줬어요. The person helped takes the object marker 을/를: 친구를 도와줘요. The most useful register fact is the request form: because 주다 is inside the verb, 'please help me' is simply 도와주세요 — adding a second giving verb to make 도와줘 주세요 is redundant and wrong. Contrast plain 돕다 (which feels more neutral/written, 어려운 이웃을 돕다 'help a struggling neighbor') with 도와주다 (the warm, conversational everyday form). The English-speaker pitfall is exactly that double 주세요, plus marking the helped person with 에게 by analogy to 'give to' — but help is done to a person directly, so it is 저를 도와줘요, not 저에게 도와줘요."},sentence:{ko:"도와주세요!",en:"Please help me!"},target:"도와주",options:["to not know","to walk","to help"],note:"돕다 + 아/어 주다 → 도와주다 (ㅂ-irregular): 도와주세요 is a one-word survival phrase"},{kind:"guess",word:{ko:"찾다",romanization:"chatda",en:"to look for / find",pos:"verb",nuance:"찾다 can mean find or look for. 찾고 있어요 often means “I am looking for.”"},sentence:{ko:"지하철역을 찾고 있어요.",en:"I'm looking for the subway station."},target:"찾고",options:["to not know","to walk","to look for / find"],note:"찾고 있어요 = currently searching (ongoing action) — useful when you're lost and need help"},{kind:"payoff",line:{speaker:"지민",ko:"죄송한데, 천천히 말해 주세요. 잘 이해가 안 돼요.",en:"Sorry, please speak slowly. I don't understand well."},hl:"천천히"}],canDo:"Ask someone to do something for me with V아/어 주세요 (말해 주세요)",id:"chapter-10-b3",chapterId:"chapter-10",index:2},{kind:"pattern",title:"문법 Grammar · V아/어 주세요",cards:[{kind:"hunt",name:"V아/어 주세요",sub:"asking someone to do something for you",lines:[{tokens:[{pre:"다시",mid:"",post:"",hit:!1},{pre:"말해",mid:"",post:"",hit:!1},{pre:"",mid:"주세요",post:".",hit:!0}],ko:"다시 말해 주세요.",en:"Please say that again.",romanization:"da-si mal-hae ju-se-yo."},{tokens:[{pre:"이",mid:"",post:"",hit:!1},{pre:"책을",mid:"",post:"",hit:!1},{pre:"읽",mid:"어",post:"",hit:!0},{pre:"",mid:"주세요",post:".",hit:!0}],ko:"이 책을 읽어 주세요.",en:"Please read this book (to me).",romanization:"i chae-geul il-geo ju-se-yo."}],rule:{name:"V아/어 주세요",rows:[{when:"Stem's last vowel is ㅏ or ㅗ (bright)",add:"아 주세요",ex:"받다 → 받아 주세요 · 보다 → 봐 주세요"},{when:"Stem's last vowel is anything else (not ㅏ/ㅗ)",add:"어 주세요",ex:"읽다 → 읽어 주세요 · 만들다 → 만들어 주세요"},{when:"하다 verbs",add:"해 주세요",ex:"말하다 → 말해 주세요 · 일하다 → 일해 주세요"},{when:"With a 'help me' adverb (다시, 천천히)",add:"adverb + V아/어 주세요",ex:"다시 → 다시 말해 주세요 · 천천히 → 천천히 써 주세요"}]},more:{func:'V아/어 주세요 is the polite way to ask someone to do something for you: "please (do) … (for me)." Take the verb stem, add 아/어 by vowel harmony, then attach 주세요. It powers the survival phrases you need in class and out on the street — 다시 말해 주세요 (please say it again), 천천히 말해 주세요 (please speak slowly).',funcLead:'V아/어 주세요 is the polite way to ask someone to do something for you: "please (do) … (for me)." Take the verb stem, add 아/어 by vowel harmony, then attach 주세요.',keyPoint:{label:"V아/어 주세요 vs N 주세요",body:`Plain 주세요 (from 주다, "to give") means "please give me ___" and attaches straight to a noun: 물 주세요, 책 주세요. But when you want someone to DO something for you, a bare noun won't carry it — you put the verb in the 아/어 form first: 책을 읽어 주세요 (please read the book for me). So: a thing you want handed over → N 주세요; an action you want done → V아/어 주세요. The deeper 주다 "do-it-for-me" grammar comes later; for now treat V아/어 주세요 as one fixed request phrase.`},pronunciation:"In 말해 주세요 the ㄹ links into 해 — [마래 주세요]. In 읽어 주세요 the hidden ㄱ of 읽 carries onto 어 — [일거 주세요]. Keep 주세요 light and even, don't stress it.",pitfall:{wrong:'다시 말하 주세요 / 천천히 말하세요 (meaning "please say it again for me")',right:"다시 말해 주세요 / 천천히 말해 주세요",explanation:`Two traps. First, you have to conjugate to the 아/어 form before 주세요 — it's 말해 주세요, never the bare stem 말하 주세요. Second, plain 말하세요 is a polite command ("speak") with no "for me" warmth; adding 주세요 turns the order into a real request — exactly what you want when asking a teacher or a stranger for help.`}}},{kind:"drill",prompt:"Please speak slowly.",sentence:"천천히 말해 ___.",options:[{text:"주세요",ok:!0},{text:"어 주세요",ok:!1}],explanation:'천천히 ("slowly") + 말해 주세요 — use it when someone talks too fast for you.'},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "Please say that again."',tokens:["다시","말해","주세요."],correct:"다시 말해 주세요.",explanation:""},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "Please read this book (to me)."',tokens:["이","책을","읽어","주세요."],correct:"이 책을 읽어 주세요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"다시 말해 주세요 / 천천히 말해 주세요",ok:!0},{text:'다시 말하 주세요 / 천천히 말하세요 (meaning "please say it again for me")',ok:!1}],explanation:`Two traps. First, you have to conjugate to the 아/어 form before 주세요 — it's 말해 주세요, never the bare stem 말하 주세요. Second, plain 말하세요 is a polite command ("speak") with no "for me" warmth; adding 주세요 turns the order into a real request — exactly what you want when asking a teacher or a stranger for help.`}],canDo:"Ask someone to do something for me with V아/어 주세요 (말해 주세요)",id:"chapter-10-b4",chapterId:"chapter-10",index:3},{kind:"words",title:"단어 Words 3 · 여기~",cards:[{kind:"guess",word:{ko:"여기",romanization:"yeogi",en:"here (this place)",pos:"pronoun",nuance:"여기 changes with particles: 여기에 location, 여기서 action place, 여기로 direction."},sentence:{ko:"여기부터 역까지 걸어서 10분이에요.",en:"It's a 10-minute walk from here to the station."},target:"여기",options:["bathroom / restroom","here (this place)","subway station"],note:"여기부터 = starting from here — pairs naturally with 까지 for distance ranges"},{kind:"guess",word:{ko:"저기",romanization:"jeogi",en:"over there (that place in the distance)",pos:"pronoun",nuance:"저기 is the 'place' member of the 이/그/저 family — 'over there,' far from both people — completing 여기 (here) / 거기 (there, by you) / 저기 (yonder). Beyond location it has two social jobs English keeps separate: 저기요 is the go-to polite 'excuse me' for hailing a stranger or a waiter when you don't know their name, and a sentence-opening 저기… works like 'um / you know,' softening the ground before a request or bad news. The synonym to separate is 저거 — 저기 is a SPOT, 저거 is a THING, so 저기 뭐 있어요? ('what's over there?') versus 저거 뭐예요? ('what is that object?'). One register caution: in a restaurant, 저기요 is gentler and safer than the blunter 여기요, and calling a stranger 아저씨/아주머니 can sound abrupt, so 저기요 is the diplomatic choice."},sentence:{ko:"화장실은 저기에 있어요.",en:"The bathroom is over there."},target:"저기",options:["bathroom / restroom","subway station","over there (that place in the distance)"],note:"저기 = yonder/over there (visible but farther away). 여기 = here, 거기 = there, 저기 = over there"},{kind:"guess",word:{ko:"왼쪽",romanization:"oenjjok",en:"left side",pos:"noun",nuance:"왼쪽 is the native compound noun for the left side or leftward direction, built from 왼- ('left') + 쪽 ('side/direction'); it attaches to a noun (문 왼쪽) or stands with a direction particle for movement (왼쪽으로 = to the left). The -쪽 element is the same one in 위쪽/아래쪽/앞쪽, marking 'the ~ side'. Its direct opposite is 오른쪽 (right), and confusing the two is the single most common error when giving directions — practice the pair until 왼 reliably means left. Note also the more formal/literary 좌 (左, Sino-Korean) seen in 좌회전 (left turn, on road signs) versus everyday spoken 왼쪽. Register: 왼쪽 is the normal conversational word; 좌 appears in fixed/official terms. English-speaker pitfalls: (1) 왼쪽에서 있어요 for existence instead of 왼쪽에 있어요; (2) swapping 왼쪽 and 오른쪽 under pressure; and (3) using 왼쪽 alone for 'turn left' (왼쪽 도세요 is incomplete) — you need the direction particle: 왼쪽으로 도세요 / 왼쪽으로 가세요."},sentence:{ko:"왼쪽으로 가세요.",en:"Go to the left."},target:"왼쪽",options:["bathroom / restroom","subway station","left side"],note:"으로 = direction marker (go via/toward). 왼쪽으로 가다 = go left"},{kind:"guess",word:{ko:"오른쪽",romanization:"oreunjjok",en:"right side",pos:"noun",nuance:"오른쪽 is the native compound noun for the right side or rightward direction, from 오른- ('right') + 쪽 ('side/direction'); it attaches to a noun (문 오른쪽) or pairs with a direction particle for motion (오른쪽으로 = to the right). The -쪽 piece is shared with 왼쪽/위쪽/앞쪽, all meaning 'the ~ side'. Its opposite is 왼쪽 (left), and mixing the two is the top direction-giving mistake — anchor 오른 firmly to 'right'. The formal/Sino-Korean counterpart is 우 (右), found in signage like 우회전 (right turn) and the set phrase 좌우 (左右, left-and-right), while 오른쪽 is the everyday spoken form. Register: 오른쪽 is conversational, 우 is official/written. English-speaker pitfalls: (1) 오른쪽에서 있어요 for existence instead of 오른쪽에 있어요; (2) confusing 오른쪽 with 왼쪽; and (3) using 오른쪽 by itself for 'turn right' — the direction particle is required: 오른쪽으로 도세요 / 오른쪽으로 가세요, not 오른쪽 도세요."},sentence:{ko:"오른쪽에 편의점이 있어요.",en:"There's a convenience store on the right."},target:"오른쪽",options:["bathroom / restroom","right side","subway station"],note:"에 있다 = something exists in that location — combine direction + 에 있다 to describe where things are"},{kind:"guess",word:{ko:"알겠어요",romanization:"algesseoyo",en:"I understand / okay / got it",pos:"expression",nuance:"알겠어요 often means “okay, I got it,” not only intellectual understanding."},sentence:{ko:"네, 알겠어요. 감사합니다.",en:"Yes, I understand. Thank you."},target:"알겠어요",options:["bathroom / restroom","subway station","I understand / okay / got it"],note:"알겠어요 is warmer and more engaged than just 네 — it shows you actually processed what was said"},{kind:"payoff",line:{speaker:"민준",ko:"3번 출구 쪽으로 가세요. 오른쪽에 있어요.",en:"Go toward exit 3. It's on the right."},hl:"오른쪽"}],canDo:"Ask for repetition or a slower pace when lost (다시 · 천천히)",id:"chapter-10-b5",chapterId:"chapter-10",index:4},{kind:"dialogue",title:"대화 Dialogue · 진짜 한국어",cards:[{kind:"chat",setting:"Jimin is a foreign learner at Seoul Station. She approaches 민준 (a station employee) looking confused.",lines:[{speaker:"지민",ko:"저기요, 화장실이 어디예요?",en:"Excuse me, where is the bathroom?",romanization:"jeogiyo, hwajangsiri eodiyeyo?"},{speaker:"민준",ko:"3번 출구 쪽으로 가세요. 오른쪽에 있어요.",en:"Go toward exit 3. It's on the right.",romanization:"3beon chulgu jjogeuro gaseyo. oreunjjoge isseoyo."},{speaker:"지민",ko:"죄송한데, 천천히 말해 주세요. 잘 이해가 안 돼요.",en:"Sorry, please speak slowly. I don't understand well.",romanization:"joesonghande, cheoncheonhi malhae juseyo. jal ihaega an dwaeyo."},{speaker:"민준",ko:"아, 네! 저기 계단 보여요? 계단에서 오른쪽으로 가세요.",en:"Ah, yes! Do you see those stairs over there? From the stairs, go right.",romanization:"a, ne! jeogi gyedan boyeoyo? gyedaneseo oreunjjogeuro gaseyo."},{speaker:"지민",ko:"알겠어요! 감사합니다. 혹시 2호선 타는 곳은 몇 번 출구 쪽이에요?",en:"Got it! Thank you. Also, which exit side is the Line 2 boarding area toward?",romanization:"algesseoyo! gamsahamnida. hoksi i hoseon taneun goseun myeot beon chulgu jjogiyeyo?"},{speaker:"민준",ko:"2호선 타는 곳은 5번 출구 쪽이에요. 여기서 5번 출구까지 걸어서 3분이에요.",en:"The Line 2 boarding area is toward exit 5. It's a 3-minute walk from here to exit 5.",romanization:"i hoseon taneun goseun obeon chulgu jjogiyeyo. yeogiseo obeon chulgukkaji georeoseo sambunieyo."},{speaker:"지민",ko:"안내소는 몇 시부터 몇 시까지 열어요?",en:"From what time to what time is the information desk open?",romanization:"annaesoneun myeot sibuteo myeot sikkaji yeoreoyo?"},{speaker:"민준",ko:"오전 9시부터 오후 6시까지 열어요. 안내소에서 물어보세요.",en:"It's open from 9 a.m. to 6 p.m. Please ask at the information desk.",romanization:"ojeon ahopsibuteo ohu yeoseot sikkaji yeoreoyo. annaesoeseo mureoboseyo."}]},{kind:"order",prompt:"Build: 'Please say it again.'",tokens:["다시","말해 주세요"],correct:"다시 말해 주세요",explanation:"다시 means again, and 말해 주세요 is the polite request. Together they form the repair phrase you use when you missed what someone said."},{kind:"drill",prompt:"누가 한 말일까요? · Who said this?",sentence:"2호선 타는 곳은 5번 출구 쪽이에요. 여기서 5번 출구까지 걸어서 3분이에요.",options:[{text:"지민",ok:!1},{text:"민준",ok:!0}],explanation:"The Line 2 boarding area is toward exit 5. It's a 3-minute walk from here to exit 5."},{kind:"drill",prompt:'무엇이 들어갈까요? · "Excuse me, where is the bathroom?"',sentence:"저기요, ___이 어디예요?",options:[{text:"화장실",ok:!0},{text:"지하철역",ok:!1},{text:"출구",ok:!1}],explanation:""}],canDo:"Give a time or place range with N부터 N까지 (아홉 시부터 여섯 시까지)",id:"chapter-10-b6",chapterId:"chapter-10",index:5},{kind:"reading",title:"읽기 Reading · 서울역에서 온 문자 (Text messages from Seoul Station)",cards:[{kind:"read",title:"서울역에서 온 문자 (Text messages from Seoul Station)",chunks:["지민: 민아야, 지금 서울역에 있어. 근데 길을 잘 모르겠어. 민아: 어디 가려고? 지민: 2호선 타려고. 몇 번 출구 쪽인지 몰라. 민아: 14번 출구 쪽이야. 거기서 2호선 타는 곳까지 걸어서 5분이야.","지민: 아, 그리고 화장실도 찾고 있었는데. 민아: 화장실은 1번 출구 왼쪽에 있어. 출구에서 나오면 바로 보여. 지민: 알겠어! 참, 안내소는 몇 시까지 열어? 민아: 안내소는 오전 9시부터 오후 6시까지 열어."],translation:`Jimin: Mina, I'm at Seoul Station now. But I don't really know my way around.
Mina: Where are you trying to go?
Jimin: I'm trying to take Line 2. I don't know which exit side it is toward.
Mina: It's toward exit 14. From there to the Line 2 boarding area is a 5-minute walk.
Jimin: Oh, and I was also looking for the bathroom.
Mina: The bathroom is to the left of exit 1. Once you come out the exit, you'll see it right away.
Jimin: Got it! By the way, until what time is the information desk open?
Mina: The information desk is open from 9 a.m. to 6 p.m.`,qas:[{q:"Which exit should Jimin use to get to Line 2?",a:"14번 출구 쪽 (toward exit 14). From there it's a 5-minute walk to the Line 2 boarding area."},{q:"Where is the bathroom?",a:"1번 출구 왼쪽에 있어 — it is to the left of exit 1, visible as soon as you exit."},{q:"Find every use of 부터 and 까지 in the text. Why is each one used — and why does one sentence use both?",a:"몇 시까지 열어? — 까지 alone marks the end-point of the opening hours (asking 'until what time'). 오전 9시부터 오후 6시까지 열어 — both 부터 and 까지 appear because Mina is giving the full range: 'from 9 AM (부터 = start) to 6 PM (까지 = end)'. The first question only needed the endpoint; the answer needed both endpoints of the ruler. And 2호선 타는 곳까지 걸어서 5분이야 — 까지 marking the spatial end-point of the walk (as far as the Line 2 boarding area)."}]},{kind:"drill",prompt:"지문에서 뭐라고 했어요? · What did the passage say?",sentence:"지민: ___ 타려고.",options:[{text:"지하철역",ok:!1},{text:"오른쪽",ok:!1},{text:"2호선",ok:!0}],explanation:""},{kind:"drill",prompt:"지문에서 뭐라고 했어요? · What did the passage say?",sentence:"몇 번 ___ 쪽인지 몰라.",options:[{text:"지하철역",ok:!1},{text:"오른쪽",ok:!1},{text:"출구",ok:!0}],explanation:""}],canDo:"Ask someone to do something for me with V아/어 주세요 (말해 주세요)",id:"chapter-10-b7",chapterId:"chapter-10",index:6},{kind:"boss",title:"보스 Boss bite · 다 걸어요",cards:[{kind:"drill",prompt:"A local just gave you fast directions. You didn't catch everything. What do you say?",sentence:null,options:[{text:"잘 모르겠어요.",ok:!1},{text:"천천히 말해 주세요.",ok:!0},{text:"다시 한 번 주세요.",ok:!1},{text:"네, 알겠어요.",ok:!1}],explanation:"천천히 말해 주세요 (Please speak slowly) is the best repair phrase when the issue is speed. 잘 모르겠어요 (I don't really know) signals confusion but doesn't ask for help. 다시 한 번 주세요 is missing the verb — it would mean 'give me one more time' (like asking for a second serving). 네, 알겠어요 would falsely signal comprehension."},{kind:"drill",prompt:"안내소는 오전 9시___ 오후 6시___ 열어요. Which pair of particles fits?",sentence:null,options:[{text:"에 / 에",ok:!1},{text:"부터 / 까지",ok:!0},{text:"에서 / 까지",ok:!1},{text:"부터 / 에",ok:!1}],explanation:"This is a time range (opening hours), so you need the RULER pair: 부터 for the start (9시부터) and 까지 for the end (6시까지). 에 alone marks single moments, not ranges. 에서 is for physical locations where actions happen, not time expressions. Mixing 에서 or 에 with 까지 would be grammatically wrong here."},{kind:"drill",prompt:"9시___ 6시까지 일해요. (I work from 9 to 6.)",sentence:null,options:[{text:"부터",ok:!0},{text:"에",ok:!1},{text:"를",ok:!1}],explanation:"부터 marks the starting point of a time range. 까지 already marks the endpoint, so the natural pair is 9시부터 6시까지."}],canDo:"Ask for repetition or a slower pace when lost (다시 · 천천히)",id:"chapter-10-b8",chapterId:"chapter-10",index:7}]},{id:"chapter-11",number:11,title:"-아서/어서 · -고 / -(으)면 / -(으)ㄹ게요",goal:"Use 아서/어서 to connect a reason to its result in a single sentence",biteCount:8,bites:[{kind:"words",title:"단어 Words 1 · 바쁘다~",cards:[{kind:"guess",word:{ko:"바쁘다",romanization:"bappeuda",en:"to be busy",pos:"adjective",nuance:"바쁘다 becomes 바빠요 in polite speech. It is a high-frequency reason word because 바빠서 못 가요 politely explains why a plan is impossible."},sentence:{ko:"요즘 너무 바빠서 쉬고 싶어요.",en:"I've been so busy lately that I want to rest."},target:null,options:["to be expensive","to be busy","to be cheap / inexpensive"],note:"아서/어서 reason → result: the busyness causes the desire to rest"},{kind:"guess",word:{ko:"아프다",romanization:"apeuda",en:"to be sick / to hurt",pos:"adjective",nuance:"아프다 covers both a specific body part hurting (배가 아파요 = my stomach hurts) and the whole-body state of being unwell/sick. The crucial point for English speakers: it is a descriptive adjective, not an action verb, so you describe yourself as 아파요, never 아파해요 — that -해요 ending belongs to verbs like 좋아해요. To say WHAT hurts, the hurting part takes the subject particle 이/가, not 을/를: 머리가 아파요, never 머리를 아파요, because nothing is doing an action to the head; the head simply is in a hurting state. The stem 아프- is ㅡ-irregular: before the -아/어 ending the bare ㅡ drops and, because the remaining vowel ㅏ is bright, 아 is chosen, giving 아 + 아 → 아파요 (not 아프어요). Compare 아프다 with 슬프다 (sad): both are emotional/physical states ending in -프다 and both drop ㅡ the same way (슬퍼요), so once you master 아파요 the pattern transfers. Note the polite/respectful form for an elder is 편찮으세요, a separate honorific word you would use instead of 아프세요 for grandparents."},sentence:{ko:"머리가 아파서 병원에 갔어요.",en:"My head hurt, so I went to the hospital."},target:null,options:["to be expensive","to be cheap / inexpensive","to be sick / to hurt"],note:"아서/어서 domino: the pain is the cause that pushes the result (hospital visit)"},{kind:"guess",word:{ko:"피곤하다",romanization:"pigonhada",en:"to be tired",pos:"adjective",nuance:"피곤하다 is physical/general tiredness — worn out, drained, exhausted — typically after work, study, travel, or poor sleep. It is Sino-Korean 疲困 (疲 weary + 困 exhausted), literally 'weary-exhausted', which is why it reads as bodily fatigue rather than sleepiness. Keep it apart from 졸리다 ('sleepy'): you can be 피곤하다 yet wide awake (drained but not nodding off), and 졸리다 is specifically wanting to sleep — don't swap them. It is also milder and more everyday than 지치다 ('to be worn out/burned out'), which implies you've reached your limit. As a regular 하다-adjective it is 피곤해요 (not 피곤하요). One common English-speaker slip: 피곤하다 normally describes a PERSON being tired; to call an activity 'tiring' you also use 피곤하다 (피곤한 일 = 'tiring work'), but to call a person 'tiresome/draining' Koreans say 피곤한 사람 — meaning 'a person who is exhausting to deal with', a nuance worth knowing so you don't misread it as 'a tired person.'"},sentence:{ko:"피곤해서 일찍 잘게요.",en:"I'm tired, so I'll go to sleep early."},target:"피곤해",options:["to be tired","to be okay / fine / alright","to contact / get in touch"],note:"해서 (하다 verb → 해서) + ㄹ게요 (speaker's first-person decision): double connector usage"},{kind:"guess",word:{ko:"늦다",romanization:"neutda",en:"to be late",pos:"verb/adjective",nuance:"늦다 is a descriptive verb, so it behaves like an adjective in Korean. Use 늦게 for the adverb 'late': 늦게 왔어요."},sentence:{ko:"늦어서 죄송해요.",en:"I'm sorry for being late."},target:"늦어",options:["to be late","to be expensive","to be cheap / inexpensive"],note:"늦다 (consonant-final 다 → 어서): lateness is the reason for the apology"},{kind:"guess",word:{ko:"비싸다",romanization:"bissada",en:"to be expensive",pos:"adjective",nuance:"비싸요 is useful for shopping but can sound blunt if said directly to staff."},sentence:{ko:"비싸면 안 사요.",en:"If it's expensive, I don't buy it."},target:"비싸",options:["to be expensive","to be busy","to be sick / to hurt"],note:"면 (condition/switch): buying decision depends on the price condition being met"},{kind:"guess",word:{ko:"싸다",romanization:"ssada",en:"to be cheap / inexpensive",pos:"adjective",nuance:"싸다 can also mean “to wrap” in other contexts, but 싸요 in shopping usually means cheap."},sentence:{ko:"이 식당은 싸고 맛있어요.",en:"This restaurant is cheap and delicious."},target:"싸고",options:["to be cheap / inexpensive","to be busy","to be sick / to hurt"],note:"고 as coupling hook between two adjectives — just linking, no causal relationship between them"},{kind:"payoff",line:{speaker:"민준",ko:"회사 일이 많아서 늦게까지 일해야 해요.",en:"There's a lot of work, so I have to work until late."},hl:"늦게"}],canDo:"Link a reason to a result with -아서/어서 (아파서 못 가요)",id:"chapter-11-b1",chapterId:"chapter-11",index:0},{kind:"pattern",title:"문법 Grammar · -아서/어서",cards:[{kind:"teach",name:"-아서/어서",sub:"because / so (reason and result)",rows:[{when:"Verb/Adj stem with ㅏ or ㅗ as last vowel",add:"-아서",ex:"가다 → 가서, 좋다 → 좋아서"},{when:"Stem with any other last vowel",add:"-어서",ex:"먹다 → 먹어서, 읽다 → 읽어서"},{when:"하다 verbs/adjectives",add:"해서",ex:"공부하다 → 공부해서, 피곤하다 → 피곤해서"},{when:"이다 (to be): after 받침 / after vowel",add:"-이라서 / -라서",ex:"학생이다 → 학생이라서, 친구다 → 친구라서"}],examples:[{ko:"배가 고파서 밥을 먹었어요.",en:"I was hungry, so I ate.",romanization:"bae-ga go-pa-seo bap-eul meo-geo-sseo-yo.",note:"고프다 (ㅡ drops) → 고파서; the reason (hungry) leads to the result (ate)."},{ko:"시간이 없어서 영화를 못 봤어요.",en:"I didn't have time, so I couldn't see the movie.",romanization:"si-ga-ni eop-seo-seo yeong-hwa-reul mot bwa-sseo-yo.",note:"없다 → 없어서; the past tense sits only on the last verb (봤어요), never on -어서."}],more:{func:"Use -아서/어서 to link a reason to its result in one sentence: the first clause is the cause, the second is what follows from it. It's the everyday way to say 'because' or 'so' when two ideas are naturally connected.",funcLead:"Use -아서/어서 to link a reason to its result in one sentence: the first clause is the cause, the second is what follows from it.",keyPoint:{label:"-아서/어서 vs -(으)니까",body:"Both mean 'because,' but you can't end an -아서/어서 sentence with a command or a suggestion. For 'Let's…' or 'Please…,' switch to -(으)니까: 피곤하니까 쉬세요 (You're tired, so rest), not 피곤해서 쉬세요. Also, -아서/어서 never carries past tense itself — say 늦어서 미안해요, not 늦었어서. The full -(으)니까 contrast comes later; for now just remember these two limits."},pronunciation:"In 좋아서 the ㅎ is silent and the sounds link smoothly: [조아서]. Same with 많아서 → [마나서].",pitfall:{wrong:"늦었어서 미안해요.",right:"늦어서 미안해요.",explanation:"English puts 'was' in the reason clause ('because I WAS late'), so learners add 었 before -어서. In Korean the tense lives only on the final verb; -아서/어서 always attaches to the plain stem, no matter when it happened."}}},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "I was hungry, so I ate."',tokens:["배가","고파서","밥을","먹었어요."],correct:"배가 고파서 밥을 먹었어요.",explanation:""},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "I didn't have time, so I couldn't see the movie."`,tokens:["시간이","없어서","영화를","못","봤어요."],correct:"시간이 없어서 영화를 못 봤어요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"늦어서 미안해요.",ok:!0},{text:"늦었어서 미안해요.",ok:!1}],explanation:"English puts 'was' in the reason clause ('because I WAS late'), so learners add 었 before -어서. In Korean the tense lives only on the final verb; -아서/어서 always attaches to the plain stem, no matter when it happened."}],canDo:"Link a reason to a result with -아서/어서 (아파서 못 가요)",id:"chapter-11-b2",chapterId:"chapter-11",index:1},{kind:"words",title:"단어 Words 2 · 연락하다~",cards:[{kind:"guess",word:{ko:"연락하다",romanization:"yeollakada",en:"to contact / get in touch",pos:"verb"},sentence:{ko:"도착하면 연락할게요.",en:"When I arrive, I'll contact you."},target:"연락할",options:["to arrive","to explain","to contact / get in touch"],note:"면 (when/if condition) + 할게요 (speaker's promise): the connector and promise form working together"},{kind:"guess",word:{ko:"도착하다",romanization:"dochakada",en:"to arrive",pos:"verb",nuance:"도착하다 is Sino-Korean 到着(도착: 到 reach + 着 attach/touch down) plus 하다 — the moment of REACHING and touching a destination. Its mirror is 출발하다(depart), and the key is the particle: you arrive AT a place with 에 (호텔에 도착해요), whereas 출발하다 leaves FROM a place with 에서. Don't confuse it with 들어가다/들어오다(enter): 도착하다 is reaching the destination's threshold, not stepping inside a building. As a 하다 verb, 하 + 아 fuses to 해 (도착해요) and the short negative and inability split the noun off: 도착 안 해요, 도착 못 해요. The classic English-speaker error is copying 'arrive at' as 에서 — 'at' here is the static endpoint 에, so 공항에 도착해요, and 공항에서 도착해요 is wrong."},sentence:{ko:"도착하면 문자 보낼게요.",en:"When I arrive, I'll send a text."},target:"도착하",options:["to contact / get in touch","to arrive","to explain"],note:"하다 verb + 면 (condition): 도착하 + 면 = 도착하면; paired with ㄹ게요 promise"},{kind:"guess",word:{ko:"시간",romanization:"sigan",en:"time / hour",pos:"noun",nuance:"시간 works with 있어요/없어요 and is essential for scheduling."},sentence:{ko:"시간이 있으면 같이 밥 먹어요.",en:"If you have time, let's eat together."},target:"시간",options:["reason","time / hour","appointment / promise / plans"],note:"있으면 = 있다 + 으면 (consonant-final): the condition is whether time exists"},{kind:"guess",word:{ko:"이유",romanization:"iyu",en:"reason",pos:"noun",nuance:"이유 is Sino-Korean (理由, 理 'principle/logic' + 由 'cause/origin'), the 'reason' or grounds behind something — the answer to 'why?'. Its sharpest contrast is with 원인 (原因, 'cause'): 이유 is the justification or motive a person gives ('the reason I'm late'), often subjective and explainable, while 원인 is the objective, often impersonal cause of a result ('the cause of the fire', 화재의 원인). So you ask a friend 무슨 이유로 늦었어? but an investigator looks for the 원인 of an accident. Also distinguish 까닭, a more native, slightly literary synonym of 이유. Register-neutral and extremely common. Core collocations: 이유가 있다/없다, 이유를 묻다/대다/설명하다, 이유 없이 (for no reason), 그런 이유로 (for that reason), ~는 이유는 (the reason that ~ is). The English-speaker pitfall: don't bolt 이유 onto a 'because' clause redundantly — Korean already has 왜냐하면 ... 때문이에요 / ~기 때문에 to say 'because', so '왜냐하면 그 이유는...' is clunky; pick one. Also, 'the reason is because...' should be ~는 이유는 ... 때문이에요, where the sentence ends in 때문이다, not a second 이유."},sentence:{ko:"이유가 있어서 못 가요.",en:"I have a reason, so I can't go."},target:"이유",options:["time / hour","text message","reason"],note:"있어서 (있다 + 어서): having a reason is the domino that causes not being able to go"},{kind:"guess",word:{ko:"약속",romanization:"yakssok",en:"appointment / promise / plans",pos:"noun",nuance:"약속(約束, literally 'bind + tie' — a tying-together of words) carries two English senses Koreans treat as one: a PROMISE (a verbal commitment) and an APPOINTMENT/plans to meet someone. So 약속이 있어요 almost always means 'I have plans (to meet a person),' which surprises English speakers expecting 'I have a promise.' The signature collocations come as an opposed pair: 약속을 지키다 (keep a promise, lit. 'protect') vs 약속을 어기다 (break it, lit. 'violate'). Contrast 약속 with 예약 豫約 (a RESERVATION/booking for a restaurant, hotel, or hospital — 식당 예약), which is institutional, and with 계획 (your own plan, no other party). The English-speaker pitfalls: the 하다 particle slip 약속이 해요 (use 약속을 해요); using 약속 for a restaurant booking (that is 예약); and saying 약속을 깨다 — while understood, the idiomatic 'break a promise' is 약속을 어기다, whereas 깨다 ('shatter') fits cancelling an appointment (약속을 깨다 = bail on plans)."},sentence:{ko:"약속이 있어서 일찍 가야 해요.",en:"I have plans, so I have to leave early."},target:"약속",options:["time / hour","appointment / promise / plans","text message"],note:"있어서 reason: having plans (약속) is the cause for needing to leave early"},{kind:"guess",word:{ko:"괜찮다",romanization:"gwaenchanta",en:"to be okay / fine / alright",pos:"adjective",nuance:"괜찮아요 can mean okay, fine, no thanks, or not bad. Context decides."},sentence:{ko:"괜찮으면 같이 가요.",en:"If it's okay with you, let's go together."},target:"괜찮",options:["to be okay / fine / alright","to be busy","to be sick / to hurt"],note:"괜찮다 (consonant-final 다 after ㅎ drop → 괜찮 + 으면): switch track — only proceed together if condition of okayness is met"},{kind:"payoff",line:{speaker:"민준",ko:"고마워요! 다음 주에 시간 괜찮으면 제가 살게요.",en:"Thank you! If next week works, I'll treat you."},hl:"시간"}],canDo:"List or sequence two ideas with -고 (바쁘고 피곤해요)",id:"chapter-11-b3",chapterId:"chapter-11",index:2},{kind:"pattern",title:"문법 Grammar · -고 / -(으)면 / -(으)ㄹ게요",cards:[{kind:"teach",name:"-고 / -(으)면 / -(으)ㄹ게요",sub:"and, if/when, I'll (a promise)",rows:[{when:"-고: any verb/adj stem (nothing changes)",add:"-고",ex:"먹다 → 먹고, 좋다 → 좋고"},{when:"-(으)면 after stem WITH 받침",add:"-으면",ex:"먹다 → 먹으면, 읽다 → 읽으면"},{when:"-(으)면 after stem WITHOUT 받침 (or ㄹ 받침)",add:"-면",ex:"가다 → 가면, 만들다 → 만들면"},{when:"-(으)ㄹ게요 after stem WITH 받침",add:"-을게요",ex:"먹다 → 먹을게요, 읽다 → 읽을게요"},{when:"-(으)ㄹ게요 after stem WITHOUT 받침 (or ㄹ)",add:"-ㄹ게요",ex:"가다 → 갈게요, 만들다 → 만들게요"}],examples:[{ko:"밥을 먹고 학교에 가요.",en:"I eat and (then) go to school.",romanization:"bap-eul meok-go hak-gyo-e ga-yo.",note:"먹다 → 먹고; here -고 links two actions in order, 'do A and then B.'"},{ko:"시간이 있으면 영화를 봐요.",en:"If/when I have time, I watch a movie.",romanization:"si-ga-ni i-sseu-myeon yeong-hwa-reul bwa-yo.",note:"있다 (받침) → 있으면; -(으)면 states the condition before the result."}],more:{func:"Three small connectors for joining ideas: -고 lists or sequences two clauses ('and'), -(으)면 sets up a condition ('if/when'), and -(으)ㄹ게요 makes a promise about what the speaker will do.",funcLead:"Three small connectors for joining ideas: -고 lists or sequences two clauses ('and'), -(으)면 sets up a condition ('if/when'), and -(으)ㄹ게요 makes a promise about w…",keyPoint:{label:"-(으)ㄹ게요 vs -(으)ㄹ 거예요",body:"-(으)ㄹ게요 is a promise made to whoever's listening — used only with 'I/we': 제가 할게요 (I'll do it, count on me). -(으)ㄹ 거예요 is a neutral prediction or plan and can take any subject: 내일 비가 올 거예요 (It'll rain tomorrow). You can't say 비가 올게요 — rain can't make a promise. The deeper future grammar comes later; for now, promise vs. prediction is the key split."},pronunciation:"-(으)ㄹ게요 is spelled with ㄱ but pronounced tense: 갈게요 → [갈께요], 먹을게요 → [머글께요].",pitfall:{wrong:"내일 비가 올게요.",right:"내일 비가 올 거예요.",explanation:"English uses 'will' for both promises and predictions, so learners reach for -(으)ㄹ게요 everywhere. But -(으)ㄹ게요 is a personal promise and needs an 'I/we' subject who can actually commit. For forecasts or anything in the third person, use -(으)ㄹ 거예요 instead."}}},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "I eat and (then) go to school." (밥을 시작 · Start with 밥을.)',tokens:["밥을","먹고","학교에","가요."],correct:"밥을 먹고 학교에 가요.",explanation:""},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "If/when I have time, I watch a movie."',tokens:["시간이","있으면","영화를","봐요."],correct:"시간이 있으면 영화를 봐요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"내일 비가 올 거예요.",ok:!0},{text:"내일 비가 올게요.",ok:!1}],explanation:"English uses 'will' for both promises and predictions, so learners reach for -(으)ㄹ게요 everywhere. But -(으)ㄹ게요 is a personal promise and needs an 'I/we' subject who can actually commit. For forecasts or anything in the third person, use -(으)ㄹ 거예요 instead."}],canDo:"List or sequence two ideas with -고 (바쁘고 피곤해요)",id:"chapter-11-b4",chapterId:"chapter-11",index:3},{kind:"words",title:"단어 Words 3 · 나중에~",cards:[{kind:"guess",word:{ko:"나중에",romanization:"najunge",en:"later",pos:"adverb",nuance:"나중에 means 'later' at some vague, unspecified future point — possibly today, possibly next week, the time is deliberately left open. That open-endedness is exactly why it's so handy for politely putting things off (나중에 할게요 'I'll do it later'). The sharp contrast to learn is 나중에 vs 이따가: 이따가 means 'a little later but still TODAY', whereas 나중에 carries no same-day promise and can mean any future time. Don't reach for English 'after' here — 나중에 is a standalone time adverb, not the connector '-(으)ㄴ 후에/다음에' you use to say 'after doing X'. Note the fixed 에 is baked in: the word is 나중에, and bare 나중 sounds incomplete in speech. It naturally collocates with 봐요, 연락하다, 다시, and 후회하다, and its opposite pole is 먼저/지금 (first/now)."},sentence:{ko:"나중에 전화할게요.",en:"I'll call later."},target:"나중에",options:["to be busy","to be sick / to hurt","later"],note:"나중에 + ㄹ게요: a complete speaker's promise anchored in time; this exact phrase appears in the chapter dialogue"},{kind:"guess",word:{ko:"먼저",romanization:"meonjeo",en:"first / ahead",pos:"adverb",nuance:"먼저 means 'first / beforehand / ahead (of others)' — it ranks one action or person EARLIER in a sequence or in time. The key contrast is 먼저 vs 처음: 먼저 is relative ('before the other thing/person', e.g. 먼저 가요 'go ahead of you'), while 처음 means 'the first time ever / the beginning' (처음 만나요 'meeting for the first time'). So 먼저 봤어요 = 'I saw it first (before you)', but 처음 봤어요 = 'I saw it for the first time'. 먼저 is also a courtesy word: 먼저 가세요 / 먼저 하세요 ('go ahead, you first') is everyday politeness, and 먼저 갈게요 / 먼저 들어가겠습니다 softens leaving before others. Register-neutral. The English-speaker pitfall is mapping every 'first' to one word — choose 먼저 for order-relative 'first/ahead', but 처음 for 'first-ever/at first', and keep 먼저 before the verb."},sentence:{ko:"저는 먼저 갈게요.",en:"I'll go first."},target:"먼저",options:["first / ahead","to be busy","to be sick / to hurt"],note:"먼저 + 갈게요: classic speaker's promise/decision — the engineer announces departure first"},{kind:"guess",word:{ko:"그럼",romanization:"geureom",en:"then / in that case / well then",pos:"conjunction"},sentence:{ko:"그럼 내일 만나면 얘기할게요.",en:"Well then, if we meet tomorrow, I'll talk about it."},target:"그럼",options:["then / in that case / well then","to be busy","to be sick / to hurt"],note:"그럼 as discourse opener + 면 condition + 게요 promise: three connective tools in one natural sentence"},{kind:"guess",word:{ko:"문자",romanization:"munja",en:"text message",pos:"noun",nuance:"문자 (文字, 'written character/letter') in daily speech is the everyday word for an SMS text message — short for 문자 메시지. The pitfall is its double life: literally 문자 means written characters/letters (e.g. 한글은 한국의 문자예요, 'Hangul is Korea's writing system'), so context decides. Crucially, 문자 is NOT a paper letter in the mail — that is 편지 (便紙). The near-synonym 카톡 (a KakaoTalk message) is what most people actually send now; 문자 specifically implies the carrier SMS (often bank/official notices), while a casual chat is 카톡 or 메시지. Register is neutral. Habitual collocations: 문자를 보내다/받다, 문자가 오다, 문자를 확인하다, 문자로 연락하다, and the source pattern 은행/회사에서 문자가 오다. Particle traps: 'by text' is 문자로 (means); the sender/source is marked 에서 for organizations (은행에서) or 한테서/에게서 for people. English speakers often want 'text' as a verb — Korean splits it into 문자를 보내다 (send a text)."},sentence:{ko:"전화 못 하면 문자 보낼게요.",en:"If I can't call, I'll send a text."},target:"문자",options:["time / hour","reason","text message"],note:"못 하면 (못 + 하다 + 면): double negative condition — the inability to call triggers the text promise"},{kind:"guess",word:{ko:"설명하다",romanization:"seolmyeonghada",en:"to explain",pos:"verb",nuance:"설명하다 is 說明(설명)하다, hanja 說 'speak' + 明 'bright/clear', so it literally means to 'speak something into clarity' — you talk about a thing so the listener understands it. The dividing line against 설득하다 and 말하다 matters: 설명하다 is to make something UNDERSTOOD (neutral, informational), 설득하다 is to PERSUADE (change someone's mind), and 말하다 is just to 'say/tell' without the goal of clarifying. So '설명해 주세요' = 'help me understand,' which is far more specific than '말해 주세요' = 'just tell me.' The thing explained takes 을/를 (이유를 설명하다), and for a broad topic Koreans add -에 대해(서): 그 사건에 대해 설명했어요. Natural adverbs are 자세히 (in detail), 쉽게 (simply), 간단히 (briefly). The English-speaker pitfall is the construction 'explain me' / 'explain to me' — Korean attaches the listener with 에게/한테, not the object slot, and very often just uses 설명해 주다 (explain as a favor) to imply the listener. It is a regular 하다 verb: 설명 + 해요, negating as 설명 안 해요 / 설명 못 해요."},sentence:{ko:"나중에 만나면 제가 설명할게요.",en:"If we meet later, I'll explain it."},target:"설명할",options:["to contact / get in touch","to arrive","to explain"],note:"면 condition + 제가 설명할게요 (first-person promise): the engineer announces what they'll do when the switch is set"},{kind:"payoff",line:{speaker:"유나",ko:"알겠어요. 그럼 다음에 같이 먹어요.",en:"Understood. Then let's eat together next time."},hl:"그럼"}],canDo:"Set up a condition with -(으)면 (시간이 있으면)",id:"chapter-11-b5",chapterId:"chapter-11",index:4},{kind:"dialogue",title:"대화 Dialogue · 진짜 한국어",cards:[{kind:"chat",setting:"Minjun texts his colleague Yuna to explain why he can't make it to their group dinner and makes promises about what he'll do instead",lines:[{speaker:"유나",ko:"민준 씨, 오늘 같이 저녁 먹을 수 있어요?",en:"Minjun, can you join dinner tonight?",romanization:"Minjun ssi, oneul gachi jeonyeok meogeul su isseoyo?"},{speaker:"민준",ko:"미안해요. 오늘 너무 바빠서 못 가요.",en:"I'm sorry. I'm too busy today, so I can't go.",romanization:"Mianhaeyo. Oneul neomu bappaseo mot gayo."},{speaker:"유나",ko:"왜요? 무슨 일이 있어요?",en:"Why? Is something going on?",romanization:"Waeyo? Museun iri isseoyo?"},{speaker:"민준",ko:"회사 일이 많아서 늦게까지 일해야 해요.",en:"There's a lot of work, so I have to work until late.",romanization:"Hoesa iri manaseo neutgekkaji ilhaeya haeyo."},{speaker:"유나",ko:"알겠어요. 그럼 다음에 같이 먹어요.",en:"Understood. Then let's eat together next time.",romanization:"Algesseoyo. Geureom daeume gachi meogeoyo."},{speaker:"민준",ko:"고마워요! 다음 주에 시간 괜찮으면 제가 살게요.",en:"Thank you! If next week works, I'll treat you.",romanization:"Gomawoyo! Daeum jue sigan gwaenchanheumyeon jega salgeyo."},{speaker:"유나",ko:"와, 정말요? 그럼 제가 식당 찾아볼게요.",en:"Wow, really? Then I'll look for a restaurant.",romanization:"Wa, jeongmalyo? Geureom jega sikdang chajabolgeyo."},{speaker:"민준",ko:"일 끝나면 바로 연락할게요. 오늘 저녁 맛있게 드세요!",en:"When I finish work, I'll contact you right away. Enjoy dinner tonight!",romanization:"Il kkeunnamyeon baro yeollakhalgeyo. Oneul jeonyeok masitge deuseyo!"}]},{kind:"order",prompt:"Build: 'I'm busy, so I can't go.'",tokens:["바빠서","못 가요"],correct:"바빠서 못 가요",explanation:"-아서/어서 connects the reason to the result in one smooth sentence. 바빠서 gives the reason before 못 가요."},{kind:"drill",prompt:"누가 한 말일까요? · Who said this?",sentence:"일 끝나면 바로 연락할게요. 오늘 저녁 맛있게 드세요!",options:[{text:"유나",ok:!1},{text:"민준",ok:!0}],explanation:"When I finish work, I'll contact you right away. Enjoy dinner tonight!"},{kind:"drill",prompt:`무엇이 들어갈까요? · "Understood. Then let's eat together next time."`,sentence:"알겠어요. ___ 다음에 같이 먹어요.",options:[{text:"그럼",ok:!0},{text:"바쁘다",ok:!1},{text:"아프다",ok:!1}],explanation:""}],canDo:"Link a reason to a result with -아서/어서 (아파서 못 가요)",id:"chapter-11-b6",chapterId:"chapter-11",index:5},{kind:"reading",title:"읽기 Reading · 지연 씨의 문자 대화 (Jiyeon's Text Exchange)",cards:[{kind:"read",title:"지연 씨의 문자 대화 (Jiyeon's Text Exchange)",chunks:["지연: 수호 씨, 오늘 약속 괜찮아요? 저 요즘 좀 바빠서요. 수호: 아, 그래요? 많이 바빠요? 지연: 네, 이번 주에 시험이 있어서 공부해야 해요. 수호: 알겠어요. 그럼 시험 끝나면 만나요.","지연: 좋아요! 시험이 목요일이에요. 금요일에 시간 있어요? 수호: 금요일은 괜찮아요. 제가 예약할게요. 지연: 감사합니다! 시험 잘 보고 연락할게요."],translation:`Jiyeon: Suho, is our plan for today still okay? I've been a bit busy lately.
Suho: Oh, is that so? Are you very busy?
Jiyeon: Yes, I have an exam this week so I have to study.
Suho: I see. Then let's meet when the exam is over.
Jiyeon: Sounds good! The exam is Thursday. Do you have time Friday?
Suho: Friday is fine. I'll make the reservation.
Jiyeon: Thank you! I'll do well on the exam and then contact you.`,qas:[{q:"Why can't Jiyeon meet today?",a:"바빠서 — she's busy, and specifically 시험이 있어서 (because she has an exam this week so she has to study)"},{q:"What does Suho promise to do?",a:"예약할게요 — he promises to make the reservation (a first-person speaker's decision using ㄹ/을게요)"},{q:"Find every connector (아서/어서, 고, 면, 게요) in the text. For each one, explain why that specific connector was chosen over the others.",a:"바빠서요 — 아서/어서 because being busy is the stated REASON (domino) for the uncertainty about the plan. 있어서 — 아서/어서 because having an exam CAUSES the need to study. 공부해야 해요 — no connector; standalone result clause. 끝나면 — 면 because this is a CONDITION ('when/if the exam ends') not a reason. 예약할게요 — ㄹ/을게요 because Suho is making a first-person promise/decision. 연락할게요 — ㄹ/을게요 because Jiyeon is making her own first-person promise. 잘 보고 — 고 as a simple coupling hook: do well on the exam AND THEN contact (sequence, no causal push needed)."}]},{kind:"drill",prompt:"지문에서 뭐라고 했어요? · What did the passage say?",sentence:"지연: 수호 씨, 오늘 ___ 괜찮아요?",options:[{text:"문자",ok:!1},{text:"약속",ok:!0},{text:"바쁘다",ok:!1}],explanation:""},{kind:"drill",prompt:"지문에서 뭐라고 했어요? · What did the passage say?",sentence:"___ 시험 끝나면 만나요.",options:[{text:"바쁘다",ok:!1},{text:"아프다",ok:!1},{text:"그럼",ok:!0}],explanation:""}],canDo:"List or sequence two ideas with -고 (바쁘고 피곤해요)",id:"chapter-11-b7",chapterId:"chapter-11",index:6},{kind:"boss",title:"보스 Boss bite · 다 걸어요",cards:[{kind:"drill",prompt:"Your friend says she'll treat you. You want to respond 'Then I'll choose the restaurant!' Which is correct?",sentence:null,options:[{text:"그럼 제가 식당을 고를게요.",ok:!0},{text:"그럼 제가 식당을 고릴게요.",ok:!1},{text:"그럼 제가 식당을 고를 거예요.",ok:!1}],explanation:"고르다 (to choose) → stem 고르 ends in a vowel with no 받침, so it takes -ㄹ게요 like 가다 → 갈게요: 고를게요. This is correct ㄹ/을게요 usage — the speaker is making a first-person decision. 고릴게요 (option 2) is wrong spelling. 고를 거예요 (option 3) is grammatically fine but sounds like a neutral future plan rather than an in-the-moment promise/decision in response to your friend's offer."},{kind:"drill",prompt:"You want to say 'I'm tired, so I'm going to rest.' Which connector is correct?",sentence:null,options:[{text:"피곤하면 쉴게요.",ok:!1},{text:"피곤해서 쉴게요.",ok:!0},{text:"피곤하고 쉴게요.",ok:!1}],explanation:"Being tired is the CAUSE of the speaker's decision to rest, so 아서/어서 (해서 for 하다 verbs) is correct. 피곤하면 쉴게요 means 'if I'm tired, I'll rest,' which changes the real reason into a condition. 피곤하고 쉴게요 just links 'tired and rest' without showing that tiredness is WHY you're resting."},{kind:"drill",prompt:"이유___ 있어요? (Is there a reason?)",sentence:null,options:[{text:"가",ok:!0},{text:"를",ok:!1},{text:"에서",ok:!1}],explanation:"있어요 takes 이/가 for the thing that exists. 이유를 would make 이유 an object, which does not fit 있다/있어요."}],canDo:"Set up a condition with -(으)면 (시간이 있으면)",id:"chapter-11-b8",chapterId:"chapter-11",index:7}]}],t={generatedFrom:e,chapters:o};export{o as chapters,t as default,e as generatedFrom};
